190: create or replace function private.inversiones_escritura_bajo_candado()
191: returns boolean language plpgsql security definer set search_path='' as $$
192: begin
193:   -- Orden común: bandera identidad -> bandera inversión -> jerarquía -> documentos -> persona.
194:   if not private.resolver_en_puertas_bajo_candado() then return false; end if;
195:   perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_inversiones_escritura'));
196:   return coalesce((select activo from crm.multiempresa_flags where nombre='inversiones_escritura'),false);
197: end;
198: $$;
