201: -- Autoriza y bloquea la identidad vigente. Una lectura de una inversión ya
202: -- confirmada conserva el ámbito actual, aunque después se haya vetado operar.
203: create or replace function private.inversion_persona_autorizada(p_persona uuid)
204: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
205: declare
206:   v_uid uuid := (select auth.uid());
207:   v_rol text;
208:   v_i crm.inversionistas%rowtype;
209:   v_docs text[];
210:   v_docs_actuales text[];
211:   v_persona uuid;
212: begin
213:   if v_uid is null or not private.puede_gestionar_contratos_crm() then
214:     raise exception 'No autorizado para registrar inversiones' using errcode='42501';
215:   end if;
216:   if not private.inversiones_escritura_bajo_candado() then
217:     raise exception 'El registro multiempresa todavía no está habilitado' using errcode='P0409';
218:   end if;
219:   perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia',0));
220:   v_rol := private.rol_crm(v_uid);
221:   if v_rol is null or v_rol not in ('vendedor','supervisor','gerencia') then
222:     raise exception 'No autorizado para registrar inversiones' using errcode='42501';
223:   end if;
224:   -- La solicitud conserva la identidad con que nació. La autorización y los
225:   -- nuevos hechos pertenecen a su canónica vigente, también tras otra fusión.
226:   v_persona := private.inversionista_canonica(p_persona);
227:   v_docs := private.identidad_bloquear_documentos_de(array[v_persona]);
228:   select * into v_i from crm.inversionistas where id=v_persona for update;
229:   if not found or not coalesce((
230:     v_rol='gerencia' or v_i.responsable_relacion_id in (select private.vendedor_ids_visibles(v_uid))
231:   ),false) then
232:     raise exception 'Persona no encontrada o fuera de tu ámbito' using errcode='42501';
233:   end if;
234:   if private.inversionista_canonica(p_persona) is distinct from v_persona then
235:     raise exception 'La identidad cambió mientras se esperaba; vuelve a cargar la persona' using errcode='40001';
236:   end if;
237:   select coalesce(array_agg(k order by k),'{}') into v_docs_actuales
238:   from (select distinct tipo_documento||':'||documento_normalizado as k
239:         from crm.inversionista_identificadores where inversionista_id=v_persona and estado='vigente') d;
240:   if v_docs is distinct from v_docs_actuales then
241:     raise exception 'El documento cambió durante la operación; vuelve a cargar la persona' using errcode='40001';
242:   end if;
243:   return jsonb_build_object('inversionista_id',v_i.id,'perfil_id',v_i.perfil_id,
244:     'responsable_id',v_i.responsable_relacion_id);
245: end;
246: $$;
247: revoke all on function private.inversion_persona_autorizada(uuid) from public,anon,authenticated,service_role;
