251: create or replace function private.inversion_persona_contexto(p_persona uuid)
252: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
253: declare
254:   v_i crm.inversionistas%rowtype;
255:   v_p public.perfiles%rowtype;
256:   v_l crm.leads%rowtype;
257:   v_doc crm.inversionista_identificadores%rowtype;
258:   v_leads uuid[];
259:   v_nombre text;
260:   v_persona uuid;
261: begin
262:   v_persona := (private.inversion_persona_autorizada(p_persona)->>'inversionista_id')::uuid;
263:   select * into v_i from crm.inversionistas where id=v_persona for update;
264:   if v_i.estado <> 'activo' or v_i.no_contactar then
265:     raise exception 'La persona no permite nuevas inversiones: revisa su estado o No insistir' using errcode='P0429';
266:   end if;
267:   if v_i.responsable_relacion_id is null or not exists (
268:     select 1 from crm.equipo e join public.perfiles p on p.id=e.perfil_id
269:     where e.perfil_id=v_i.responsable_relacion_id and e.activo and p.activo
270:       and e.rol_crm in ('vendedor','supervisor')
271:   ) then
272:     raise exception 'Asigna un responsable comercial activo antes de registrar la inversión' using errcode='P0409';
273:   end if;
274:   select * into v_doc from crm.inversionista_identificadores
275:   where inversionista_id=v_persona and estado='vigente' and verificado
276:   order by case tipo_documento when 'DNI' then 1 when 'CE' then 2 else 3 end,id limit 1;
277:   if not found then
278:     raise exception 'La inversión requiere un documento verificado' using errcode='P0409';
279:   end if;
280:   if v_i.perfil_id is not null then
281:     select * into v_p from public.perfiles where id=v_i.perfil_id for share;
282:     if not found or v_p.activo is not true or v_p.rol <> 'cliente' then
283:       raise exception 'El perfil Avance requiere revisión antes de operar' using errcode='P0409';
284:     end if;
285:     if not private.documento_es_de_identidad(v_persona,v_p.tipo_documento,v_p.dni) then
286:       raise exception 'El documento del perfil requiere conciliación con la persona' using errcode='P0409';
287:     end if;
288:   end if;
289:   select array_agg(distinct id order by id) into v_leads from (
290:     select l.id from crm.leads l where l.inversionista_id=v_persona
291:     union select il.lead_id from crm.inversionista_leads il
292:       where il.inversionista_id=v_persona and il.rol='canonico'
293:   ) l;
294:   if coalesce(cardinality(v_leads),0)>1 then
295:     raise exception 'Hay más de un lead canónico; corresponde conciliación de identidad' using errcode='P0409';
296:   end if;
297:   if cardinality(v_leads)=1 then
298:     -- NOWAIT mantiene el orden de la corrección/fusión y evita esperar una reasignación que ya tomó el lead.
299:     select * into v_l from crm.leads where id=v_leads[1] for share nowait;
300:     if v_l.no_contactar then
301:       raise exception 'La persona tiene No insistir en su lead' using errcode='P0429';
302:     end if;
303:     if v_l.etapa <> 'convertido' then
304:       raise exception 'Completa la conversión inicial antes de registrar otra inversión' using errcode='P0409';
305:     end if;
306:   end if;
307:   v_nombre := coalesce(nullif(btrim(v_p.nombre_completo),''),nullif(btrim(v_l.nombre_completo),''),
308:     (select ce.nombre_completo from crm.cierres_externos ce where ce.inversionista_id=v_persona order by ce.creado_en desc,ce.id desc limit 1));
309:   if v_nombre is null then
310:     raise exception 'La persona necesita un antecedente con su nombre completo' using errcode='P0409';
311:   end if;
312:   return jsonb_build_object('inversionista_id',v_i.id,'perfil_id',v_i.perfil_id,
313:     'responsable_id',v_i.responsable_relacion_id,'lead_id',v_l.id,
314:     'documento_tipo',v_doc.tipo_documento,'documento',v_doc.documento_normalizado,'nombre',v_nombre);
315: end;
316: $$;
