336: create or replace function private.inversion_datos_portal(p_datos jsonb)
337: returns jsonb language plpgsql immutable security invoker set search_path='' as $$
338: declare v_correo text; v_nombre text; v_domicilio text;
339: begin
340:   if jsonb_typeof(p_datos) is distinct from 'object' then
341:     raise exception 'Completa los datos para el acceso Avance de esta persona' using errcode='22023';
342:   end if;
343:   if exists(select 1 from jsonb_object_keys(p_datos) k where k not in
344:     ('correo','nombre_completo','apellidos','nombres','telefono','domicilio'))
345:     or exists(select 1 from jsonb_each(p_datos) d where jsonb_typeof(d.value) not in ('string','null')) then
346:     raise exception 'El alta Avance contiene campos no admitidos; documento y responsable los determina el servidor' using errcode='22023';
347:   end if;
348:   v_correo:=lower(btrim(p_datos->>'correo'));
349:   v_nombre:=upper(btrim(p_datos->>'nombre_completo'));
350:   if v_correo is null or length(v_correo)>254 or v_correo !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
351:      or v_nombre is null or length(v_nombre) not between 2 and 240 or v_nombre ~ '[[:cntrl:]]' then
352:     raise exception 'Completa el nombre legal y un correo válido para el acceso Avance' using errcode='22023';
353:   end if;
354:   if exists(select 1 from jsonb_each_text(p_datos) d where d.key in ('apellidos','nombres','telefono')
355:     and (length(d.value)>240 or d.value ~ '[[:cntrl:]]')) then
356:     raise exception 'Revisa los nombres y el teléfono del cliente' using errcode='22023';
357:   end if;
358:   v_domicilio:=crm.normalizar_domicilio_legal(p_datos->>'domicilio');
359:   return jsonb_build_object('correo',v_correo,'nombre_completo',v_nombre,
360:     'apellidos',nullif(upper(btrim(p_datos->>'apellidos')),''),
361:     'nombres',nullif(upper(btrim(p_datos->>'nombres')),''),
362:     'telefono',nullif(btrim(p_datos->>'telefono'),''),'domicilio',v_domicilio);
363: end;
364: $$;
