367: create or replace function crm.preparar_inversion_fn(p_clave uuid,p_datos jsonb)
368: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
369: declare
370:   v_persona uuid;
371:   v_ctx jsonb;
372:   v_e crm.empresas%rowtype;
373:   v_s crm.inversion_solicitudes%rowtype;
374:   v_monto numeric;
375:   v_fecha date;
376:   v_vence date;
377:   v_ruta text;
378:   v_hash text;
379: begin
380:   if p_clave is null or p_datos is null or jsonb_typeof(p_datos)<>'object' then
381:     raise exception 'Falta la clave o el contenido de la inversión' using errcode='22023';
382:   end if;
383:   if exists (select 1 from jsonb_object_keys(p_datos) k where k not in (
384:     'inversionista_id','empresa','monto','moneda','fecha_comercial','vence_en','numero_transaccion',
385:     'referencia','evidencia','producto_condicion_id','contrato','cronograma','cuenta','alta_portal'
386:   )) then
387:     raise exception 'La solicitud contiene campos no admitidos' using errcode='22023';
388:   end if;
389:   begin v_persona := (p_datos->>'inversionista_id')::uuid;
390:   exception when invalid_text_representation then
391:     raise exception 'Identificador de persona inválido' using errcode='22023';
392:   end;
393:   v_ctx := private.inversion_persona_autorizada(v_persona);
394:   v_hash := private.idem_hash(p_datos);
395:   perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('f4_solicitud:'||p_clave::text,0));
396:   select * into v_s from crm.inversion_solicitudes where id=p_clave for update;
397:   if found then
398:     if v_s.hash_payload<>v_hash or v_s.inversionista_id<>v_persona then
399:       raise exception 'La misma clave llegó con datos distintos' using errcode='P0409';
400:     end if;
401:     if v_s.estado<>'confirmada' then
402:       v_ctx := private.inversion_persona_contexto(v_persona);
403:     end if;
404:     return private.inversion_solicitud_resultado(v_s.id,v_ctx);
405:   end if;
406:   v_ctx := private.inversion_persona_contexto(v_persona);
407:   v_e.id:=private.inversion_validar_datos(p_clave,p_datos,v_ctx);
408:   insert into crm.inversion_solicitudes(id,inversionista_id,empresa_id,responsable_esperado_id,hash_payload,datos,creado_por)
409:   values(p_clave,v_persona,v_e.id,(v_ctx->>'responsable_id')::uuid,v_hash,p_datos,(select auth.uid()));
410:   return private.inversion_solicitud_resultado(p_clave,v_ctx);
411: end;
412: $$;
