465: create or replace function private.inversion_vincular_fuente(
466:   p_persona uuid,p_contrato uuid,p_cierre uuid,p_por uuid,p_inicial boolean default false)
467: returns uuid language plpgsql security definer set search_path='' as $$
468: declare
469:   v_empresa uuid;
470:   v_fecha date;
471:   v_estado text;
472:   v_identidad uuid;
473:   v_i crm.inversiones%rowtype;
474: begin
475:   if ((p_contrato is not null)::integer+(p_cierre is not null)::integer)<>1 then
476:     raise exception 'La inversión requiere exactamente una fuente económica' using errcode='22023';
477:   end if;
478:   if p_cierre is not null then
479:     select e.id,coalesce(ce.fecha_comercial,(ce.creado_en at time zone 'America/Lima')::date),
480:       case when ce.anulado_en is null then 'vigente' else 'anulada' end,
481:       private.inversionista_canonica(ce.inversionista_id)
482:     into v_empresa,v_fecha,v_estado,v_identidad
483:     from crm.cierres_externos ce join crm.empresas e on e.clave=ce.cooperativa
484:     where ce.id=p_cierre for share of ce;
485:   else
486:     select e.id,c.fecha_cierre_comercial,'vigente',private.inversionista_canonica(p.id)
487:     into v_empresa,v_fecha,v_estado,v_identidad
488:     from public.contratos c join crm.inversionistas p on p.perfil_id=c.cliente_id and p.estado<>'fusionado'
489:     cross join crm.empresas e where c.id=p_contrato and e.clave='avance' for share of c;
490:   end if;
491:   if v_empresa is null or v_identidad is distinct from p_persona then
492:     raise exception 'La fuente económica no corresponde a esta persona' using errcode='P0409';
493:   end if;
494:   -- También protege una vinculación histórica: si el borrado se preparó antes
495:   -- de obtener el candado contractual, no añadir una relación a esa fuente.
496:   if p_contrato is not null and private.contrato_en_eliminacion(p_contrato) then
497:     raise exception 'El contrato está en proceso de eliminación; requiere revisión' using errcode='55000';
498:   end if;
499:   select * into v_i from crm.inversiones
500:   where contrato_id=p_contrato or cierre_externo_id=p_cierre for update;
501:   if found then
502:     if v_i.inversionista_id<>p_persona or v_i.empresa_id<>v_empresa then
503:       raise exception 'La fuente ya está vinculada a otra persona o empresa' using errcode='P0409';
504:     end if;
505:   else
506:     insert into crm.inversiones(inversionista_id,empresa_id,contrato_id,cierre_externo_id,
507:       estado,fecha_comercial,es_primera_conversion,creado_por)
508:     values(p_persona,v_empresa,p_contrato,p_cierre,v_estado,v_fecha,p_inicial,p_por)
509:     returning * into v_i;
510:   end if;
511:   if exists (select 1 from crm.inversion_titulares it
512:              where it.inversion_id=v_i.id and it.rol='principal' and it.inversionista_id<>p_persona) then
513:     raise exception 'El titular principal requiere conciliación' using errcode='P0409';
514:   end if;
515:   insert into crm.inversion_titulares(inversion_id,inversionista_id,rol,creado_por)
516:   select v_i.id,p_persona,'principal',p_por where not exists (
517:     select 1 from crm.inversion_titulares it where it.inversion_id=v_i.id and it.rol='principal');
518:   return v_i.id;
519: end;
520: $$;
521: revoke all on function private.inversion_vincular_fuente(uuid,uuid,uuid,uuid,boolean)
522:   from public,anon,authenticated,service_role;
