524: create or replace function crm.confirmar_inversion_revisada_fn(p_solicitud uuid,p_revision_datos_esperada integer)
525: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
526: declare
527:   v_uid uuid := (select auth.uid());
528:   v_persona uuid;
529:   v_origen uuid;
530:   v_ctx jsonb;
531:   v_s crm.inversion_solicitudes%rowtype;
532:   v_e crm.empresas%rowtype;
533:   v_obj storage.objects%rowtype;
534:   v_cierre uuid;
535:   v_contrato uuid;
536:   v_inversion uuid;
537:   v_fecha date;
538:   v_imputacion date;
539:   v_periodo date;
540:   v_ahora timestamptz := statement_timestamp();
541:   v_ajuste boolean := false;
542:   v_fuente jsonb;
543:   v_payload_contrato jsonb;
544:   v_condicion uuid;
545:   v_config_producto text := current_setting('crm.producto_condicion_id',true);
546:   v_responsable_inicial uuid;
547:   v_res jsonb;
548: begin
549:   if v_uid is null or not private.puede_gestionar_contratos_crm() then
550:     raise exception 'No autorizado para registrar inversiones' using errcode='42501';
551:   end if;
552:   select inversionista_id into v_persona from crm.inversion_solicitudes where id=p_solicitud;
553:   if not found then raise exception 'Solicitud no encontrada' using errcode='P0002'; end if;
554:   v_origen := v_persona;
555:   v_ctx := private.inversion_persona_autorizada(v_persona);
556:   v_persona := (v_ctx->>'inversionista_id')::uuid;
557:   select * into v_s from crm.inversion_solicitudes where id=p_solicitud for update;
558:   if not found or v_s.inversionista_id is distinct from v_origen then
559:     raise exception 'La solicitud cambió; vuelve a cargarla' using errcode='40001';
560:   end if;
561:   if v_s.estado='confirmada' then
562:     v_res:=v_s.resultado;
563:     select contrato_id into v_contrato from crm.inversiones where id=v_s.inversion_id;
564:     if v_contrato is not null then
565:       if private.contrato_en_eliminacion(v_contrato) then
566:         raise exception 'El contrato está en proceso de eliminación; requiere revisión' using errcode='55000';
567:       end if;
568:       v_res:=jsonb_set(v_res,'{fuente,pdf}',private.contrato_pdf_estado_base(v_contrato));
569:     end if;
570:     return v_res||jsonb_build_object('inversionista_id',v_persona,'reintento',true);
571:   end if;
572:   if v_s.estado<>'preparada' then raise exception 'La solicitud está cancelada' using errcode='P0409'; end if;
573:   if p_revision_datos_esperada is distinct from v_s.revision_datos then
574:     raise exception 'Los datos cambiaron; revisa la versión vigente antes de confirmar' using errcode='40001';
575:   end if;
576:   v_ctx := private.inversion_persona_contexto(v_persona);
577:   if v_s.responsable_esperado_id is distinct from (v_ctx->>'responsable_id')::uuid then
578:     raise exception 'El responsable cambió; revisa esta misma solicitud antes de confirmarla' using errcode='P0409';
579:   end if;
580:   select * into v_e from crm.empresas where id=v_s.empresa_id and activa for share;
581:   if not found then raise exception 'La empresa ya no está disponible para nuevas inversiones' using errcode='P0409'; end if;
582:   if v_e.fuente_capital='cierres_externos' then
583:     if v_s.datos->>'moneda' is distinct from 'PEN' or not ('PEN'=any(v_e.monedas)) then
584:       raise exception 'La moneda ya no está admitida por la cooperativa' using errcode='P0409';
585:     end if;
586:     select * into v_obj from storage.objects
587:     where bucket_id='f4-comprobantes' and name=v_s.datos#>>'{evidencia,ruta}' for key share;
588:     if not found or coalesce((v_obj.metadata->>'size')::bigint,0) not between 1 and 10485760
589:        or coalesce(v_obj.metadata->>'mimetype','') not in ('application/pdf','image/jpeg','image/png') then
590:       raise exception 'Sube el comprobante válido antes de confirmar la inversión' using errcode='P0409';
591:     end if;
592:     v_fecha := (v_s.datos->>'fecha_comercial')::date;
593:     v_periodo := date_trunc('month',v_fecha)::date;
594:     -- Mismo candado que el sello mensual. El sello no puede aparecer entre la
595:     -- decisión y el alta. Un mes sellado recibe un hecho posterior trazable.
596:     perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm.periodos_cerrados'),
597:       (v_periodo-date '2000-01-01')::integer);
598:     v_ajuste := exists(select 1 from crm.periodos_cerrados where periodo=v_periodo);
599:     v_imputacion := case when v_ajuste then (v_ahora at time zone 'America/Lima')::date else v_fecha end;
600:     if v_ajuste then
601:       perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtext('crm.periodos_cerrados'),
602:         (date_trunc('month',v_imputacion)::date-date '2000-01-01')::integer);
603:       if exists(select 1 from crm.periodos_cerrados where periodo=date_trunc('month',v_imputacion)::date) then
604:         raise exception 'El período de registro también está sellado; corresponde revisión de Gerencia' using errcode='P0409';
605:       end if;
606:     end if;
607:     begin
608:       insert into crm.cierres_externos(lead_id,cooperativa,monto,moneda,documento_tipo,documento,
609:         nombre_completo,numero_transaccion,referencia_externa,vence_en,vendedor_id,creado_por,
610:         inversionista_id,creado_en,es_cierre_inicial,fecha_comercial,fecha_imputacion,comprobante_objeto_id)
611:       values((v_ctx->>'lead_id')::uuid,v_e.clave,(v_s.datos->>'monto')::numeric,'PEN',
612:         v_ctx->>'documento_tipo',v_ctx->>'documento',v_ctx->>'nombre',
613:         upper(btrim(v_s.datos->>'numero_transaccion')),btrim(v_s.datos->>'referencia'),
614:         (v_s.datos->>'vence_en')::date,(v_ctx->>'responsable_id')::uuid,v_uid,v_persona,
615:         v_ahora,false,v_fecha,v_imputacion,v_obj.id) returning id into v_cierre;
616:       -- La reclamación histórica del depósito es global para ambas cooperativas.
617:       insert into crm.depositos_reclamados(numero_norm,cierre_id,reclamado_por)
618:       values(upper(btrim(v_s.datos->>'numero_transaccion')),v_cierre,v_uid);
619:     exception when unique_violation then
620:       raise exception 'Ese número de operación del depósito ya está registrado' using errcode='P0409';
621:     end;
622:     v_fuente:=jsonb_build_object('cierre_id',v_cierre,'fecha_comercial',v_fecha,
623:       'fecha_imputacion',v_imputacion,'ajuste_mes_cerrado',v_ajuste);
624:   elsif v_e.clave='avance' then
625:     if v_ctx->>'perfil_id' is null then
626:       raise exception 'Completa el acceso Avance de esta persona y vuelve a confirmar la misma solicitud' using errcode='P0409';
627:     end if;
628:     v_payload_contrato := v_s.datos->'contrato';
629:     select r.responsable_anterior_id into v_responsable_inicial
630:       from crm.inversion_solicitud_revisiones r where r.solicitud_id=v_s.id order by r.revision limit 1;
631:     v_responsable_inicial:=coalesce(v_responsable_inicial,v_s.responsable_esperado_id);
632:     if v_payload_contrato->>'cliente_id' is not null
633:        and v_payload_contrato->>'cliente_id' is distinct from v_ctx->>'perfil_id' then
634:       raise exception 'El contrato no corresponde a esta persona' using errcode='P0409';
635:     end if;
636:     if v_payload_contrato->>'analista_cierre_id' is not null
637:        and v_payload_contrato->>'analista_cierre_id' is distinct from v_responsable_inicial::text then
638:       raise exception 'El analista del contenido original no corresponde al responsable con que se preparó la inversión' using errcode='P0409';
639:     end if;
640:     -- El contenido original conserva su huella. Una revisión explícita cambia
641:     -- el responsable con quien se confirma, sin reescribir las condiciones.
642:     v_payload_contrato := v_payload_contrato||jsonb_build_object('cliente_id',v_ctx->>'perfil_id',
643:       'analista_cierre_id',v_ctx->>'responsable_id');
644:     -- La fuente existente conserva producto, tasa, cronograma, cuenta, titularidad
645:     -- documental y operaciones de cartera. Todo participa de esta transacción.
646:     -- Reutiliza además la reserva y el snapshot documentales del alta publicada.
647:     -- Un PDF pendiente no vuelve a crear el contrato cuando se recupera el envío.
648:     -- El flujo Avance vigente es libre y fotografía sus términos. El catálogo
649:     -- sigue siendo opcional: F4 no lo convierte en un requisito comercial nuevo.
650:     perform pg_catalog.set_config('crm.producto_condicion_id',
651:       coalesce((nullif(v_s.datos->>'producto_condicion_id','')::uuid)::text,''),true);
652:     begin
653:       v_fuente := crm.crear_contrato_con_cuenta_pdf_v2(
654:         v_payload_contrato||jsonb_build_object('clave_idempotencia',v_s.id),
655:         v_s.datos->'cronograma',v_s.datos->'cuenta');
656:     exception when others then
657:       perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
658:       raise;
659:     end;
660:     perform pg_catalog.set_config('crm.producto_condicion_id',coalesce(v_config_producto,''),true);
661:     v_contrato := (v_fuente->>'id')::uuid;
662:     if v_contrato is null then raise exception 'El contrato no devolvió su identificador' using errcode='P0001'; end if;
663:     select producto_condicion_id into v_condicion from public.contratos where id=v_contrato;
664:     v_fuente:=v_fuente||private.metadata_condicion_producto(v_condicion);
665:   else
666:     raise exception 'Empresa sin puerta de inversión disponible' using errcode='P0409';
667:   end if;
668:   v_inversion := private.inversion_vincular_fuente(v_persona,v_contrato,v_cierre,v_uid,false);
669:   if v_ajuste then
670:     insert into crm.inversion_ajustes_mes_cerrado(inversion_id,periodo_origen,fecha_imputacion,creado_por)
671:     values(v_inversion,v_periodo,v_imputacion,v_uid);
672:   end if;
673:   insert into crm.inversion_eventos(inversion_id,tipo,creado_por) values(v_inversion,'registro',v_uid);
674:   v_res := jsonb_build_object('ok',true,'solicitud_id',v_s.id,'inversion_id',v_inversion,
675:     'inversionista_id',v_persona,'lead_id',v_ctx->>'lead_id','empresa',v_e.clave,'fuente',v_fuente,
676:     'revision_datos',v_s.revision_datos);
677:   update crm.inversion_solicitudes set estado='confirmada',inversion_id=v_inversion,
678:     resultado=v_res,confirmado_por=v_uid,actualizado_en=statement_timestamp() where id=v_s.id;
679:   return v_res;
680: end;
