720: -- Adaptación acotada de private.backfill_multiempresa_ejecutar(); antes 930acfc792eb4db91df599f26e283f12
721: CREATE OR REPLACE FUNCTION private.backfill_multiempresa_ejecutar()
722:  RETURNS jsonb
723:  LANGUAGE plpgsql
724:  SECURITY DEFINER
725:  SET search_path TO ''
726: AS $function$
727: declare
728:   r record; v_inv uuid; v_valido boolean;
729:   v_old_priv text := pg_catalog.current_setting('crm.op_privilegiada', true);
730:   v_demo_cierre constant uuid := 'a112aead-184a-4979-9041-943978fadae4';
731:   v_a int:=0; v_b int:=0; v_c int:=0; v_e int:=0; v_resp int:=0; v_noc int:=0;
732: begin
733:   if to_regclass('crm.inversion_solicitudes') is not null then
734:     raise exception 'F2 global ya fue sustituida por el censo y los lotes históricos F4'
735:       using errcode='55000';
736:   end if;
737:   perform pg_catalog.set_config('crm.op_privilegiada','on', true);
738: 
739:   -- ── Clase A / E: perfiles cliente ──
740:   for r in
741:     select p.id, p.tipo_documento as tipo, p.asesor_perfil_id,
742:            pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p.dni,''),'[^A-Za-z0-9]','','g')) as dnorm
743:     from public.perfiles p where p.rol='cliente'
744:     order by p.id
745:   loop
746:     if r.dnorm = '' then
747:       perform private.f2_mapear('perfil', r.id, null, 'E', 'cliente sin documento', 'revision');
748:       v_e := v_e+1; continue;
749:     end if;
750:     v_valido := coalesce(case r.tipo
751:       when 'DNI' then r.dnorm ~ '^[0-9]{8}$'
752:       when 'CE' then r.dnorm ~ '^[0-9]{9,12}$'
753:       when 'PASAPORTE' then r.dnorm ~ '^[A-Z0-9]{6,12}$' else false end, false);
754:     if not v_valido then
755:       perform private.f2_mapear('perfil', r.id, null, 'E', 'documento con formato invalido para '||r.tipo, 'revision');
756:       v_e := v_e+1; continue;
757:     end if;
758:     if exists (
759:       select 1 from public.perfiles p2
760:       where p2.id <> r.id
761:         and pg_catalog.upper(pg_catalog.regexp_replace(coalesce(p2.dni,''),'[^A-Za-z0-9]','','g')) = r.dnorm
762:     ) then
763:       perform private.f2_mapear('perfil', r.id, null, 'E', 'documento compartido con otro perfil (multirrol/colision)', 'revision');
764:       v_e := v_e+1; continue;
765:     end if;
766:     v_inv := private.inversionista_resolver(r.tipo, r.dnorm, true, 'backfill-A');
767:     update crm.inversionistas set perfil_id = r.id
768:       where id = v_inv and perfil_id is null
769:         and not exists (select 1 from crm.inversionistas i2 where i2.perfil_id = r.id and i2.id <> v_inv);
770:     perform private.f2_mapear('perfil', r.id, v_inv, 'A', 'perfil cliente con documento valido y unico', 'alta');
771:     v_a := v_a+1;
772:     if r.asesor_perfil_id is not null
773:        and exists (select 1 from crm.equipo e where e.perfil_id=r.asesor_perfil_id and e.activo)
774:        and not exists (select 1 from crm.inversionista_responsables ir where ir.inversionista_id=v_inv and ir.hasta is null) then
775:       insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo)
776:       values (v_inv, r.asesor_perfil_id, 'backfill: asesor del perfil cliente');
777:       update crm.inversionistas set responsable_relacion_id = r.asesor_perfil_id where id=v_inv and responsable_relacion_id is null;
778:       v_resp := v_resp+1;
779:     end if;
780:   end loop;
781: 
782:   -- ── Clase B / E: cierres coop (EXCLUYE el demo por id) ──
783:   for r in
784:     select ce.id, ce.documento_tipo as tipo, ce.cooperativa, ce.vendedor_id, ce.creado_por, ce.creado_en,
785:            pg_catalog.upper(pg_catalog.regexp_replace(ce.documento,'[^A-Za-z0-9]','','g')) as dnorm
786:     from crm.cierres_externos ce where ce.id <> v_demo_cierre
787:     order by ce.creado_en, ce.id
788:   loop
789:     v_valido := coalesce(case r.tipo
790:       when 'DNI' then r.dnorm ~ '^[0-9]{8}$'
791:       when 'CE' then r.dnorm ~ '^[0-9]{9,12}$'
792:       when 'PASAPORTE' then r.dnorm ~ '^[A-Z0-9]{6,12}$' else false end, false);
793:     if not v_valido then
794:       perform private.f2_mapear('cierre', r.id, null, 'E', 'documento de cierre invalido', 'revision');
795:       v_e := v_e+1; continue;
796:     end if;
797:     v_inv := private.inversionista_resolver(r.tipo, r.dnorm, true, 'backfill-B');
798:     update crm.cierres_externos set inversionista_id = v_inv where id = r.id and inversionista_id is null;
799:     insert into crm.inversiones (inversionista_id, empresa_id, cierre_externo_id, estado, fecha_comercial, es_primera_conversion, creado_por)
800:     select v_inv, e.id, r.id, 'vigente',
801:            least((r.creado_en at time zone 'America/Lima')::date, (pg_catalog.now() at time zone 'America/Lima')::date),
802:            true, r.creado_por
803:     from crm.empresas e
804:     where e.clave = r.cooperativa
805:       and not exists (select 1 from crm.inversiones inv where inv.cierre_externo_id = r.id);
806:     insert into crm.inversion_titulares (inversion_id, inversionista_id, rol)
807:     select inv.id, v_inv, 'principal' from crm.inversiones inv
808:     where inv.cierre_externo_id = r.id
809:       and not exists (select 1 from crm.inversion_titulares it where it.inversion_id=inv.id and it.rol='principal');
810:     perform private.f2_mapear('cierre', r.id, v_inv, 'B', 'cierre coop con documento valido; inversion externa inicial', 'alta');
811:     v_b := v_b+1;
812:     if r.vendedor_id is not null
813:        and not exists (select 1 from crm.inversionista_responsables ir where ir.inversionista_id=v_inv and ir.hasta is null) then
814:       insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo)
815:       values (v_inv, r.vendedor_id, 'backfill: vendedor del cierre coop');
816:       update crm.inversionistas set responsable_relacion_id = r.vendedor_id where id=v_inv and responsable_relacion_id is null;
817:       v_resp := v_resp+1;
818:     end if;
819:   end loop;
820: 
821:   -- ── Clase C / E: leads convertidos ──
822:   for r in
823:     select l.id as lead_id, l.no_contactar,
824:            pg_catalog.upper(pg_catalog.regexp_replace(coalesce(l.dni,''),'[^A-Za-z0-9]','','g')) as ldni,
825:            (select i.id from crm.inversionistas i where i.perfil_id = l.perfil_id and i.estado <> 'fusionado' limit 1) as inv_perfil,
826:            (select ce.inversionista_id from crm.cierres_externos ce where ce.lead_id = l.id) as inv_cierre
827:     from crm.leads l where l.etapa='convertido'
828:     order by l.creado_en, l.id
829:   loop
830:     if r.inv_perfil is not null and r.inv_cierre is not null and r.inv_perfil <> r.inv_cierre then
831:       perform private.f2_mapear('lead', r.lead_id, null, 'E', 'convertido con perfil y cierre en identidades distintas', 'revision');
832:       v_e := v_e+1; continue;
833:     end if;
834:     v_inv := coalesce(r.inv_perfil, r.inv_cierre);
835:     if v_inv is null then
836:       perform private.f2_mapear('lead', r.lead_id, null, 'E', 'lead convertido sin identidad inequivoca de perfil ni cierre', 'revision');
837:       v_e := v_e+1; continue;
838:     end if;
839:     if r.ldni <> '' and not exists (
840:       select 1 from crm.inversionista_identificadores d
841:       where d.inversionista_id = v_inv and d.documento_normalizado = r.ldni and d.estado='vigente'
842:     ) then
843:       perform private.f2_mapear('lead', r.lead_id, null, 'E', 'discrepancia documental del lead convertido', 'revision');
844:       v_e := v_e+1; continue;
845:     end if;
846:     if exists (select 1 from crm.leads l2 where l2.inversionista_id = v_inv) then
847:       insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
848:       select v_inv, r.lead_id, 'historico'
849:       where not exists (select 1 from crm.inversionista_leads il where il.lead_id = r.lead_id);
850:     else
851:       update crm.leads set inversionista_id = v_inv where id = r.lead_id and inversionista_id is null;
852:       insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
853:       select v_inv, r.lead_id, 'canonico'
854:       where not exists (select 1 from crm.inversionista_leads il where il.lead_id = r.lead_id);
855:     end if;
856:     perform private.f2_mapear('lead', r.lead_id, v_inv, 'C', 'lead convertido hereda identidad de perfil/cierre', 'alta');
857:     v_c := v_c+1;
858:     if r.no_contactar then
859:       update crm.inversionistas set no_contactar = true, no_contactar_en = coalesce(no_contactar_en, pg_catalog.now())
860:       where id = v_inv and no_contactar = false;
861:       v_noc := v_noc+1;
862:     end if;
863:   end loop;
864: 
865:   perform pg_catalog.set_config('crm.op_privilegiada', coalesce(v_old_priv, 'off'), true);
866:   return jsonb_build_object('A',v_a,'B',v_b,'C',v_c,'E',v_e,'responsables',v_resp,'no_contactar',v_noc);
867: end
868: $function$;
869: -- Adaptación acotada de private.capital_episodios(timestamp with time zone, timestamp with time zone, boolean, uuid[]); antes b8f375fbb377582835f4cfe222240c5b
870: CREATE OR REPLACE FUNCTION private.capital_episodios(p_ini timestamp with time zone, p_fin timestamp with time zone, p_global boolean, p_visibles uuid[])
871:  RETURNS TABLE(tipo text, medida text, contrato_id uuid, cierre_externo_id uuid, lead_id uuid, cliente_id uuid, analista_id uuid, registrado_por uuid, en_roster boolean, moneda text, monto numeric, categoria text, mes_comercial date, fecha timestamp with time zone, fecha_vencimiento date, estado text, anulado boolean)
872:  LANGUAGE sql
873:  STABLE SECURITY DEFINER
874:  SET search_path TO ''
875: AS $function$
876: 
877:   -- CONTRATO TEMPORAL (P0-4 de Codex, escrito): contratos y desgloses parten
878:   -- por FECHA LOCAL de Lima — el dia comercial entra COMPLETO o no entra;
879:   -- cooperativas parten por INSTANTE. Llamar con medianoches locales (o con
880:   -- ±infinity para "sin limite"); cualquier otra hora parte distinto.
881:   select
882:     'contrato_' || coalesce(c.categoria, 'nuevo'),
883:     'stock',
884:     c.id, null::uuid, null::uuid,
885:     c.cliente_id,
886:     -- ATR-2: la cadena de upgrade adopta tambien el CAPITAL (contrato 2026-08-30).
887:     coalesce(private.analista_atribuido_cadena(c.id), c.analista_cierre_id),
888:     c.creado_por,
889:     exists (
890:       select 1 from crm.metas_vendedor mv
891:       where mv.meta_periodo_id = (
892:         select mp.id from crm.meta_periodos mp
893:         where mp.periodo = date_trunc('month', c.fecha_cierre_comercial)::date
894:         order by mp.revision desc limit 1)
895:         and mv.vendedor_id = coalesce(private.analista_atribuido_cadena(c.id), c.analista_cierre_id)
896:     ),
897:     c.moneda,
898:     c.capital,
899:     c.categoria,
900:     date_trunc('month', c.fecha_cierre_comercial)::date,
901:     (c.fecha_cierre_comercial::timestamp at time zone 'America/Lima'),
902:     c.fecha_vencimiento,
903:     c.estado,
904:     false
905:   from public.contratos c
906:   where not c.es_demo
907:     and c.fecha_cierre_comercial >= (p_ini at time zone 'America/Lima')::date
908:     and c.fecha_cierre_comercial <  (p_fin at time zone 'America/Lima')::date
909:     and (p_global or coalesce(private.analista_atribuido_cadena(c.id), c.analista_cierre_id) = any(p_visibles))
910: 
911:   union all
912: 
913:   select
914:     'desglose_' || parte.tipo,
915:     'desglose',
916:     o.contrato_nuevo_id, null::uuid, null::uuid,
917:     o.cliente_id,
918:     coalesce(private.analista_atribuido_cadena(o.contrato_nuevo_id), o.vendedor_id),
919:     o.creado_por,
920:     exists (
921:       select 1 from crm.metas_vendedor mv
922:       where mv.meta_periodo_id = (
923:         select mp.id from crm.meta_periodos mp
924:         where mp.periodo = o.periodo
925:         order by mp.revision desc limit 1)
926:         and mv.vendedor_id = coalesce(private.analista_atribuido_cadena(o.contrato_nuevo_id), o.vendedor_id)
927:     ),
928:     o.moneda,
929:     parte.monto,
930:     o.tipo,
931:     o.periodo,
932:     (o.fecha_operacion::timestamp at time zone 'America/Lima'),
933:     c.fecha_vencimiento,
934:     c.estado,
935:     false
936:   from crm.operaciones_cartera o
937:   join public.contratos c on c.id = o.contrato_nuevo_id and not c.es_demo
938:   cross join lateral (values
939:     ('renovado',  o.capital_renovado),
940:     ('adicional', o.capital_adicional)
941:   ) as parte(tipo, monto)
942:   where parte.monto is not null
943:     and o.fecha_operacion >= (p_ini at time zone 'America/Lima')::date
944:     and o.fecha_operacion <  (p_fin at time zone 'America/Lima')::date
