1006: -- Adaptación acotada de private.leads_before_update(); antes 213e284d9c50fde7f8cd136b4ecaa5d2
1007: CREATE OR REPLACE FUNCTION private.leads_before_update()
1008:  RETURNS trigger
1009:  LANGUAGE plpgsql
1010:  SECURITY DEFINER
1011:  SET search_path TO 'crm', 'public'
1012: AS $function$
1013: declare
1014:   v_priv boolean := coalesce(current_setting('crm.op_privilegiada', true) = 'on', false);
1015: begin
1016:   -- Columnas inmutables: restaurar siempre desde OLD.
1017:   new.id := old.id;
1018:   new.creado_por := old.creado_por;
1019:   new.alta_manual := old.alta_manual;
1020:   new.creado_en := old.creado_en;
1021:   new.actualizado_en := now();
1022: 
1023:   -- Conversión y enlace al portal: SOLO desde una RPC privilegiada
1024:   -- (que fija crm.op_privilegiada='on'). Un cliente API no puede convertir
1025:   -- ni enlazar perfil_id/contrato_id a mano.
1026:   if not v_priv then
1027:     if new.etapa = 'convertido' and old.etapa <> 'convertido' then
1028:       raise exception 'La conversión a cliente solo se hace vía la operación de conversión';
1029:     end if;
1030:     new.perfil_id := old.perfil_id;
1031:     new.contrato_id := old.contrato_id;
1032:     new.convertido_en := old.convertido_en;
1033: 
1034:     -- ── SELLO DEL ORIGEN (migración D, 2026-08-11) ────────────────────────
1035:     -- El origen se elige al ALTA y no se vuelve a mover. Lo que esto protege
1036:     -- NO es un mes ya contado —el snapshot `lead_asignaciones.origen` ya era
1037:     -- inmutable por `trg_lead_asignaciones_00_inmutables`— sino dos cosas del
1038:     -- presente y del futuro:
1039:     --   · el origen que copiará `private.trg_leads_asignaciones` al abrir el
1040:     --     PRÓXIMO episodio de este lead (y ése sí sale del divisor del mes en
1041:     --     curso si dice 'referido');
1042:     --   · el bloque `referidos.dados_de_alta`, único número del payload que
1043:     --     lee esta columna viva, agrupado por el mes de ALTA del lead.
1044:     -- Se avisa con EXCEPCIÓN en vez de restaurar en silencio porque el store
1045:     -- del front es optimista: un 200 mudo dejaría al usuario convencido de
1046:     -- que corrigió.
1047:     -- Va DENTRO de `if not v_priv`, a propósito: encima del gate el dato
1048:     -- quedaría incorregible para siempre y el único remedio sería
1049:     -- `disable trigger` en producción, que CLAUDE.md prohíbe.
1050:     -- `is distinct from` (y no `<>`) hace que un UPDATE de payload completo que
1051:     -- reenvía el MISMO valor no lance nada: es el caso de seed-demo.mjs y de
1052:     -- test-rls.mjs, los dos únicos escritores que mandan `origen` en un UPDATE.
1053:     if new.origen is distinct from old.origen then
1054:       raise exception using
1055:         errcode = 'P0409',
1056:         message = 'El origen de un lead no se cambia despues del alta',
1057:         detail  = pg_catalog.format(
1058:           'lead %s: origen actual %L, intento %L',
1059:           old.id, old.origen, new.origen),
1060:         hint    = 'El origen se elige al crear el lead (crm.crear_lead_si_disponible). '
1061:                   'La conversion mensual lee la FOTO del episodio, que ya es inmutable: '
1062:                   'cambiar la ficha no mueve ningun mes ya contado, pero si moveria el '
1063:                   'origen de los episodios FUTUROS de este lead y el bloque de referidos '
1064:                   'dados de alta de su mes de creacion.';
1065:     end if;
1066:   end if;
1067: 
1068:   -- ── P4 RELAJADA (migración cierres externos, 2026-08-12) ────────────────
1069:   -- Invariante de negocio en la transición (no como CHECK de tabla). Antes:
1070:   -- «convertido ⇒ perfil_id no nulo». Ahora un convertido puede carecer de
1071:   -- perfil SI Y SOLO SI tiene cierre externo (invirtió en una cooperativa y
1072:   -- el portal no lo conoce). El EXISTS corre solo en la rama rara (convertido
1073:   -- sin perfil) y lo sirve el UNIQUE de lead_id. Nótese que P2 sigue intacta:
1074:   -- sin válvula no hay transición a convertido, con o sin cierre.
1075:   if new.etapa = 'convertido' and new.perfil_id is null
1076:      and not exists (
1077:        select 1 from crm.cierres_externos ce where ce.lead_id = new.id and ce.es_cierre_inicial
1078:      ) then
1079:     raise exception 'Un lead convertido debe estar enlazado a un perfil de cliente';
1080:   end if;
1081: 
1082:   return new;
1083: end;
1084: $function$;
1085: -- Adaptación acotada de crm.cierres_estado_fn(uuid[]); antes 1411c7395cf5579359d93565c42ce638
1086: CREATE OR REPLACE FUNCTION crm.cierres_estado_fn(p_lead_ids uuid[])
1087:  RETURNS jsonb
1088:  LANGUAGE plpgsql
1089:  STABLE SECURITY DEFINER
1090:  SET search_path TO ''
1091: AS $function$
1092: declare
1093:   v_uid      uuid := (select auth.uid());
1094:   v_rol      text;
1095:   v_lector   boolean;
1096:   v_visibles uuid[];
1097:   v_payload  jsonb;
1098: begin
1099:   v_rol := private.rol_crm(v_uid);
1100:   v_lector := private.es_lector_global();
1101: 
1102:   -- Guardia de ADMISION, igual que cartera_pagina_fn: quien no es del CRM ni
1103:   -- lector global no pregunta.
1104:   if v_uid is null or (v_rol is null and not v_lector) then
1105:     raise exception 'No autorizado' using errcode = '42501';
1106:   end if;
1107: 
1108:   -- El gate RESTRICTIVO de `crm.leads` (`crm_actor_activo_gate`) se INVOCA en
1109:   -- vez de copiarse: una llamada no se desincroniza. Sin esto, un actor
1110:   -- revocado —que la RLS expulsa de la tabla— seguiria leyendo por aqui.
1111:   if not coalesce(private.puede_acceder_crm(), false) then
1112:     raise exception 'No autorizado' using errcode = '42501';
1113:   end if;
1114: 
1115:   -- Tope alineado con `cartera_pagina_fn` (p_limite maximo 200): esta funcion
1116:   -- sirve a una pagina en pantalla, no a un volcado.
1117:   if p_lead_ids is not null and array_length(p_lead_ids, 1) > 200 then
1118:     raise exception 'Parametro p_lead_ids invalido: maximo 200'
1119:       using errcode = '22023';
1120:   end if;
1121:   if p_lead_ids is null or array_length(p_lead_ids, 1) is null then
1122:     return '[]'::jsonb;
1123:   end if;
1124: 
1125:   -- Se resuelve UNA vez (la policy lo evalua como SubPlan en cada fila).
1126:   v_visibles := array(select private.vendedor_ids_visibles(v_uid));
1127: 
1128:   select coalesce(jsonb_agg(f.fila order by f.lead_id), '[]'::jsonb)
1129:     into v_payload
1130:   from (
1131:     select
1132:       l.id as lead_id,
1133:       jsonb_build_object(
1134:         'lead_id', l.id,
1135:         -- La foto del cierre manda sobre la etapa: si hay fila en
1136:         -- cierres_externos, ese lead cerro en cooperativa, punto.
1137:         'canal', case when ce.lead_id is not null then 'cooperativa' else 'avance' end,
1138:         -- `coalesce` y no un case: los dos canales son excluyentes por
1139:         -- construccion (crm.anular_cierre_avance rechaza un lead con cierre en
1140:         -- cooperativa), asi que como mucho uno de los dos trae fecha.
1141:         'anulado_en', coalesce(ce.anulado_en, ca.anulado_en),
1142:         -- El motivo viaja: la regla de Miguel es que a quien se le quita el
1143:         -- merito merece una razon escrita, no un numero que baja sin explicacion.
1144:         'motivo', coalesce(ce.motivo_anulacion, ca.motivo)
1145:       ) as fila
1146:     from crm.leads l
1147:     -- Los dos son UNIQUE por lead (`cierres_externos_un_cierre_por_lead` y el
1148:     -- unique de `lead_id` en cierres_avance_anulados), asi que ningun join
1149:     -- duplica la fila del lead.
1150:     left join crm.cierres_externos ce on ce.lead_id = l.id and ce.es_cierre_inicial
1151:     left join crm.cierres_avance_anulados ca on ca.lead_id = l.id
1152:     where l.id = any(p_lead_ids)
1153:       -- ── ESPEJO EXACTO de la policy `leads_select` (20260902040000) ─────────
1154:       --   using: activo = true
1155:       --          and ( vendedor_id in (vendedor_ids_visibles(uid))
1156:       --                or (vendedor_id is null and asignado_supervisor_id in (...))
1157:       --                or rol_crm(uid) = 'gerencia'
1158:       --                or es_lector_global() )
1159:       -- 🔴 El `or v_lector` va DENTRO del `activo`, igual que en la policy: el
1160:       -- lector global ve todo lo VIVO y NADA de lo borrado. Hasta el 01/09 iba
1161:       -- fuera —aqui y en la policy— y por eso el Directorio leia el estado de
1162:       -- cierre de leads dados de baja.
1163:       and l.activo = true
1164:       and (
1165:         l.vendedor_id = any(v_visibles)
1166:         -- Lead en la bandeja de un supervisor: sin vendedor todavia.
1167:         -- (`NULL = any(...)` da NULL, no TRUE, asi que la rama de arriba
1168:         -- no se lo lleva por delante.)
1169:         or (l.vendedor_id is null and l.asignado_supervisor_id = any(v_visibles))
1170:         or v_rol = 'gerencia'
1171:         or v_lector
1172:       )
1173:       -- Solo los leads con algo que decir. Un convertido de Avance sano no
1174:       -- viaja: es el caso por defecto del front.
1175:       and (ce.lead_id is not null or ca.lead_id is not null)
1176:   ) f;
1177: 
1178:   return v_payload;
1179: end;
1180: $function$;
1181: -- Adaptación acotada de crm.anular_cierre_avance(uuid, text); antes 9322f86beba6b40bb4a9c07186f0028f
1182: CREATE OR REPLACE FUNCTION crm.anular_cierre_avance(p_lead_id uuid, p_motivo text)
1183:  RETURNS jsonb
1184:  LANGUAGE plpgsql
1185:  SECURITY DEFINER
1186:  SET search_path TO ''
1187: AS $function$
1188: declare
1189:   v_uid    uuid := (select auth.uid());
1190:   v_rol    text := private.rol_crm((select auth.uid()));
1191:   v_lead   crm.leads%rowtype;
1192:   v_motivo text := btrim(p_motivo);
1193:   v_contratos uuid[];
1194:   v_ajuste uuid;
1195: begin
1196:   if v_uid is null or v_rol is distinct from 'gerencia' then
1197:     raise exception 'Solo gerencia anula cierres'
1198:       using errcode = '42501';
1199:   end if;
1200: 
1201:   -- El motivo es obligatorio a proposito: esto le quita merito a una persona y
1202:   -- esa persona merece una razon escrita, no un registro de auditoria mudo.
1203:   if v_motivo is null or v_motivo = '' then
1204:     raise exception 'Escribe el motivo de la anulacion'
1205:       using errcode = '22023';
1206:   end if;
1207:   if length(v_motivo) > 300 then
1208:     raise exception 'El motivo admite como maximo 300 caracteres'
1209:       using errcode = '22023';
1210:   end if;
1211: 
1212:   select * into v_lead
1213:   from crm.leads
1214:   where id = p_lead_id
1215:   for update;
1216:   if not found then
1217:     raise exception 'Lead no encontrado';
1218:   end if;
1219: 
1220:   if exists (select 1 from crm.cierres_externos ce where ce.lead_id = p_lead_id and ce.es_cierre_inicial) then
1221:     raise exception 'Ese lead cerro en cooperativa: usa crm.anular_cierre_externo'
1222:       using errcode = '22023';
1223:   end if;
1224: 
1225:   if v_lead.etapa is distinct from 'convertido' then
1226:     raise exception 'Ese lead no tiene ningun cierre que anular'
1227:       using errcode = '22023';
1228:   end if;
1229: 
1230:   if v_lead.convertido_en is null then
1231:     raise exception 'Ese lead esta convertido pero sin fecha de conversion: no se puede saber que contratos trajo'
1232:       using errcode = '22023';
1233:   end if;
1234: 
1235:   if exists (select 1 from crm.cierres_avance_anulados ca where ca.lead_id = p_lead_id) then
1236:     raise exception using
1237:       errcode = 'P0409',
1238:       message = 'Ese cierre ya estaba anulado';
1239:   end if;
1240: 
1241:   -- Los contratos afectados se calculan ANTES de insertar la anulacion: despues,
1242:   -- `contratos_afectados_por_anulacion` ya leeria la foto recien creada y daria
1243:   -- lo mismo, pero el orden explicito evita depender de ese detalle.
1244:   select coalesce(array_agg(x), '{}'::uuid[]) into v_contratos
1245:   from private.contratos_afectados_por_anulacion(p_lead_id) x;
1246: 
1247:   insert into crm.cierres_avance_anulados (lead_id, motivo, anulado_por, acreditado_a)
1248:   values (p_lead_id, v_motivo, v_uid,
1249:           private.vendedor_acreditado_del_cierre(p_lead_id));
1250: 
1251:   -- Si el mes de ese cierre YA ESTA CERRADO, el mes no se reescribe: nace la
1252:   -- deuda que el vendedor arrastrara al mes vivo hasta saldarla.
1253:   v_ajuste := private.registrar_ajuste_si_mes_cerrado(p_lead_id, v_motivo, v_uid);
1254: 
1255:   insert into crm.actividades (
1256:     lead_id, tipo, detalle, metadata, creado_por
1257:   ) values (
1258:     p_lead_id,
1259:     'nota',
1260:     'Gerencia anulo el cierre',
1261:     jsonb_build_object(
1262:       'accion', 'anulacion_cierre_avance',
1263:       'motivo', v_motivo,
1264:       'mes_cerrado', v_ajuste is not null,
1265:       'anulado', jsonb_build_object(
1266:         'vendedor_id', v_lead.vendedor_id,
1267:         'contrato_id', v_lead.contrato_id)
1268:     ),
1269:     v_uid
1270:   );
1271: 
1272:   return jsonb_build_object(
1273:     'ok', true,
1274:     'lead_id', p_lead_id,
1275:     'contratos_afectados', to_jsonb(v_contratos),
1276:     'afecta_cuota', array_length(v_contratos, 1) is not null,
1277:     -- CLAVES NUEVAS. `mes_cerrado` le dice a gerencia que ese mes ya se pago y
1278:     -- que por eso el descuento va al mes vivo en vez de moverle el pasado.
1279:     'mes_cerrado', v_ajuste is not null,
1280:     'ajuste_id', v_ajuste);
1281: end;
1282: $function$;
