1425: -- Adaptación acotada de crm.altas_nuevas_por_analista_fn(integer); antes 2cd38241a1331e1ac335658fc7f653f5
1426: CREATE OR REPLACE FUNCTION crm.altas_nuevas_por_analista_fn(p_meses integer DEFAULT 12)
1427:  RETURNS TABLE(mes date, analista_id uuid, analista_nombre text, altas bigint)
1428:  LANGUAGE sql
1429:  STABLE SECURITY DEFINER
1430:  SET search_path TO ''
1431: AS $function$
1432:   with gate as (
1433:     -- fail-closed: sin rol CRM ni lector global, el reporte sale VACIO.
1434:     select coalesce(
1435:       (select auth.uid()) is not null
1436:       and (
1437:         private.rol_crm((select auth.uid())) in ('vendedor','supervisor','gerencia')
1438:         or private.es_lector_global()
1439:       ), false) as ok
1440:   ),
1441:   ambito as (
1442:     select
1443:       (coalesce(private.es_lector_global(), false)
1444:        or private.rol_crm((select auth.uid())) = 'gerencia') as es_global,
1445:       array(select private.vendedor_ids_visibles((select auth.uid()))) as ids
1446:   ),
1447:   anulados as (
1448:     -- Contratos cuyo cierre fue anulado, por el mapeo CANONICO (no reinventado).
1449:     -- Rama 2 (cierres_externos = cooperativa): las coop NO viven en public.contratos,
1450:     -- asi que el mapeo devuelve contratos Avance solo si el MISMO lead ligo un 'nuevo'
1451:     -- Avance al mismo acreditado; hoy 0 impacto (unica coop anulada -> 0 'nuevo').
1452:     select x as contrato_id
1453:     from crm.cierres_avance_anulados ca
1454:     cross join lateral private.contratos_afectados_por_anulacion(ca.lead_id) x
1455:     union
1456:     select x
1457:     from crm.cierres_externos ce
1458:     cross join lateral private.contratos_afectados_por_anulacion(ce.lead_id) x
1459:     where ce.anulado_en is not null and ce.es_cierre_inicial
1460:   ),
1461:   base as (
1462:     -- 🔴 fecha_cierre_comercial ES `date` (el dia comercial de Lima). NUNCA
1463:     --    `at time zone` sobre un date: en un servidor UTC el dia 1 se cae al mes
1464:     --    anterior (footgun del proyecto). Se bucketea y se acota en espacio de FECHA,
1465:     --    igual que private.capital_episodios.
1466:     select
1467:       (date_trunc('month', c.fecha_cierre_comercial))::date as mes,
1468:       coalesce(private.analista_atribuido_cadena(c.id), c.analista_cierre_id) as analista_id
1469:     from public.contratos c
1470:     where c.categoria = 'nuevo'
1471:       and not c.es_demo
1472:       and c.fecha_cierre_comercial is not null
1473:       and not exists (select 1 from anulados an where an.contrato_id = c.id)
1474:       and c.fecha_cierre_comercial >=
1475:         (date_trunc('month', now() at time zone 'America/Lima')
1476:           - make_interval(months => least(greatest(p_meses, 1), 60) - 1))::date
1477:   )
1478:   select
1479:     b.mes,
1480:     b.analista_id,
1481:     coalesce(pf.nombre_completo, 'Sin analista') as analista_nombre,
1482:     count(*)::bigint as altas
1483:   from gate g
1484:   cross join ambito a
1485:   join base b on g.ok
1486:   left join public.perfiles pf on pf.id = b.analista_id
1487:   where a.es_global or b.analista_id = any(a.ids)
1488:   group by b.mes, b.analista_id, coalesce(pf.nombre_completo, 'Sin analista')
1489:   order by b.mes desc, altas desc;
1490: $function$;
1491: -- Adaptación acotada de crm.contrato_eliminacion_preparar(uuid, uuid); antes 1b0617656c06eddade935d4c15b5bfd4
1492: CREATE OR REPLACE FUNCTION crm.contrato_eliminacion_preparar(p_contrato_id uuid, p_actor_id uuid)
1493:  RETURNS jsonb
1494:  LANGUAGE plpgsql
1495:  SECURITY DEFINER
1496:  SET search_path TO ''
1497: AS $function$
1498: declare
1499:   v_poder jsonb;
1500:   v_eliminacion private.contrato_eliminaciones%rowtype;
1501:   v_objetos jsonb;
1502: begin
1503:   perform private.bloquear_fila_contrato_pdf(p_contrato_id);
1504:   v_poder := private.poder_eliminar_contrato_como(
1505:     p_contrato_id, p_actor_id
1506:   );
1507:   if not coalesce((v_poder->>'admin')::boolean, false) then
1508:     raise insufficient_privilege using
1509:       message = 'Solo Admin o Superadmin puede eliminar contratos';
1510:   end if;
1511:   if coalesce((v_poder->>'tiene_pagos')::boolean, false)
1512:      and not coalesce((v_poder->>'superadmin')::boolean, false) then
1513:     raise insufficient_privilege using
1514:       message = 'Este contrato tiene pagos; solo Superadmin puede eliminarlo';
1515:   end if;
1516: 
1517:   -- La fila contractual ya está bloqueada y el actor ya fue autorizado.
1518:   -- Rechazar ANTES de reservar el borrado o entregar rutas al borrador Storage.
1519:   if exists(select 1 from crm.inversiones i where i.contrato_id=p_contrato_id) then
1520:     raise exception 'El contrato forma parte del historial de inversiones; conserva el registro y utiliza la anulación comercial que corresponda'
1521:       using errcode='55000';
1522:   end if;
1523: 
1524:   select * into v_eliminacion
1525:   from private.contrato_eliminaciones e
1526:   where e.contrato_id = p_contrato_id
1527:   for update;
1528:   if found then
1529:     return jsonb_build_object(
1530:       'contrato_id', v_eliminacion.contrato_id,
1531:       'token', v_eliminacion.token,
1532:       'objetos', v_eliminacion.objetos
1533:     );
1534:   end if;
1535: 
1536:   if exists (
1537:     select 1
1538:     from private.contrato_pdf_jobs j
1539:     where j.contrato_id = p_contrato_id
1540:       and j.estado in ('procesando', 'subido_verificado')
1541:       and j.lease_expira_en > statement_timestamp()
1542:   ) then
1543:     raise exception
1544:       'El PDF se está generando; reintenta la eliminación en unos minutos'
1545:       using errcode = '55000';
1546:   end if;
1547: 
1548:   if exists (
1549:     select 1
1550:     from public.documentos d
1551:     where d.contrato_id = p_contrato_id
1552:       and (
1553:         d.storage_path is null
1554:         or d.storage_path <> btrim(d.storage_path)
1555:         or length(d.storage_path) not between 5 and 1024
1556:         or left(d.storage_path, length(p_contrato_id::text) + 1)
1557:              <> p_contrato_id::text || '/'
1558:         or strpos(d.storage_path, '..') > 0
1559:         or strpos(d.storage_path, '//') > 0
1560:         or strpos(d.storage_path, E'\\') > 0
1561:         or d.storage_path ~ '[[:cntrl:]]'
1562:       )
1563:   ) then
1564:     raise exception 'Un documento del contrato tiene una ruta Storage inválida'
1565:       using errcode = '23514';
1566:   end if;
1567: 
1568:   select coalesce(jsonb_agg(objeto order by objeto->>'bucket', objeto->>'path'), '[]'::jsonb)
1569:   into v_objetos
1570:   from (
1571:     select distinct jsonb_build_object(
1572:       'bucket', 'contratos-generados', 'path', x.storage_path
1573:     ) as objeto
1574:     from (
1575:       select j.storage_path
1576:       from private.contrato_pdf_jobs j
1577:       where j.contrato_id = p_contrato_id
1578:       union
1579:       select p.storage_path
1580:       from private.contrato_pdfs p
1581:       where p.contrato_id = p_contrato_id
1582:     ) x
1583:     where x.storage_path is not null
1584: 
1585:     union
1586: 
1587:     select distinct jsonb_build_object(
1588:       'bucket', 'documentos', 'path', d.storage_path
1589:     ) as objeto
1590:     from public.documentos d
1591:     where d.contrato_id = p_contrato_id
1592:       and d.storage_path is not null
1593:       and btrim(d.storage_path) <> ''
1594:   ) objetos;
1595: 
1596:   if jsonb_array_length(v_objetos) > 1000 then
1597:     raise exception 'El contrato supera el límite seguro de archivos para borrar'
1598:       using errcode = '54000';
1599:   end if;
1600: 
1601:   insert into private.contrato_eliminaciones (
1602:     contrato_id, solicitado_por, objetos
1603:   ) values (
1604:     p_contrato_id, p_actor_id, v_objetos
1605:   ) returning * into v_eliminacion;
1606: 
1607:   return jsonb_build_object(
1608:     'contrato_id', v_eliminacion.contrato_id,
1609:     'token', v_eliminacion.token,
1610:     'objetos', v_eliminacion.objetos
1611:   );
1612: end;
1613: $function$;
1614: -- Adaptación acotada de public.proteger_campos_inmutables(); antes 5e64e3fc95b367d262b4d7b39c687cde
1615: CREATE OR REPLACE FUNCTION public.proteger_campos_inmutables()
1616:  RETURNS trigger
1617:  LANGUAGE plpgsql
1618:  SET search_path TO 'public', 'pg_temp'
1619: AS $function$
1620: DECLARE
1621:   v_f4_alinea boolean := false;
1622: BEGIN
1623:   -- Excepción de una única columna desde la revisión F4 del servidor. Las
1624:   -- escrituras directas mantienen todas las congelaciones originales.
1625:   IF TG_TABLE_NAME='perfiles' AND current_user='postgres'
1626:      AND nullif(current_setting('crm.f4_revision_solicitud',true),'') IS NOT NULL THEN
1627:     v_f4_alinea:=private.f4_alineacion_perfil_permitida(OLD.id,NEW.asesor_perfil_id);
1628:   END IF;
1629:   NEW.id         := OLD.id;
1630:   NEW.creado_en  := OLD.creado_en;
1631:   NEW.creado_por := OLD.creado_por;
1632: 
1633:   -- Campos privilegiados / de asignacion: se congelan para el usuario que edita su PROPIA
1634:   -- fila (cliente) y TAMBIEN para un ANALISTA que edita la fila de un cliente. Antes solo se
1635:   -- congelaban en la auto-edicion (NEW.id=auth.uid()), por eso un analista podia togglear
1636:   -- activo / debe_cambiar_password / blanquear asesor_perfil_id de su cliente via UPDATE forjado.
1637:   -- admin/superadmin quedan EXCLUIDOS (siguen reasignando/activando). service_role
1638:   -- (auth.uid() IS NULL, no es_analista) NO se ve afectado -> las edges de alta/baja siguen igual.
1639:   IF TG_TABLE_NAME = 'perfiles'
1640:      AND NOT public.es_admin()
1641:      AND ( NEW.id = auth.uid() OR public.es_analista() ) THEN
1642:     NEW.activo           := OLD.activo;
1643:     NEW.rol              := OLD.rol;
1644:     NEW.asesor_id        := OLD.asesor_id;
1645:     IF NOT v_f4_alinea THEN NEW.asesor_perfil_id := OLD.asesor_perfil_id; END IF;
1646:     NEW.cargo            := OLD.cargo;
1647:     -- El flag de cambio de clave solo lo baja el PROPIO usuario (primer login);
1648:     -- un analista editando a un cliente NO puede tocarlo.
1649:     IF NEW.id <> auth.uid() THEN
1650:       NEW.debe_cambiar_password := OLD.debe_cambiar_password;
1651:     END IF;
1652:   END IF;
1653: 
1654:   -- Asiento «Operaciones» (2026-08-21): edita al cliente y lo activa o desactiva,
1655:   -- pero NO lo mueve de analista. El `rol` se congela ademas por si acaso: la
1656:   -- politica ya lo acota a 'cliente', esto es la segunda linea de defensa.
1657:   IF TG_TABLE_NAME = 'perfiles'
1658:      AND NOT public.es_admin()
1659:      AND public.es_operaciones()
1660:      AND NEW.id <> auth.uid() THEN
1661:     IF (NEW.asesor_perfil_id IS DISTINCT FROM OLD.asesor_perfil_id AND NOT v_f4_alinea)
1662:        OR NEW.asesor_id IS DISTINCT FROM OLD.asesor_id THEN
1663:       RAISE EXCEPTION 'El asiento Operaciones no puede reasignar el asesor de un cliente'
1664:         USING ERRCODE = '42501';
1665:     END IF;
1666:     NEW.rol := OLD.rol;
1667:   END IF;
1668: 
1669:   -- Ciclo de vida de contratos (2026-07-13): una vez cerrado un ciclo, el
1670:   -- enlace de renovacion y los sellos de cierre quedan congelados para
1671:   -- cualquier no-superadmin (correcciones = superadmin).
1672:   IF TG_TABLE_NAME = 'contratos' AND NOT public.es_superadmin() THEN
1673:     IF OLD.renovado_a_id IS NOT NULL THEN NEW.renovado_a_id := OLD.renovado_a_id; END IF;
1674:     IF OLD.cerrado_en    IS NOT NULL THEN NEW.cerrado_en    := OLD.cerrado_en;    END IF;
1675:     IF OLD.cerrado_por   IS NOT NULL THEN NEW.cerrado_por   := OLD.cerrado_por;   END IF;
1676:   END IF;
1677: 
1678:   RETURN NEW;
1679: END; $function$;
