1732:   -- Si el mes de ese cierre YA ESTA CERRADO, el mes no se reescribe: nace la
1733:   -- deuda que el vendedor arrastrara al mes vivo.
1734:   if v_cierre.es_cierre_inicial then
1735:     v_ajuste := private.registrar_ajuste_si_mes_cerrado(v_cierre.lead_id, v_motivo, v_uid);
1736:   end if;
1737: 
1738:   if v_cierre.lead_id is not null then
1739:   insert into crm.actividades (
