1769: -- Adaptación acotada de crm.corregir_cierre_externo(uuid, numeric, text, text, text, text, date, text); antes 73cccb38b57506b065b0eb903838b4a0
1770: CREATE OR REPLACE FUNCTION crm.corregir_cierre_externo(p_cierre_id uuid, p_monto numeric, p_moneda text, p_cooperativa text, p_numero_transaccion text, p_referencia text, p_vence_en date, p_nota text)
1771:  RETURNS jsonb
1772:  LANGUAGE plpgsql
1773:  SECURITY DEFINER
1774:  SET search_path TO ''
1775: AS $function$
1776: declare
1777:   v_uid         uuid := (select auth.uid());
1778:   v_rol         text := private.rol_crm((select auth.uid()));
1779:   v_cierre      crm.cierres_externos%rowtype;
1780:   v_transaccion text := btrim(p_numero_transaccion);
1781:   v_referencia  text := nullif(btrim(p_referencia), '');
1782: begin
1783:   if v_uid is null or v_rol is distinct from 'gerencia' then
1784:     raise exception 'Solo gerencia corrige cierres externos'
1785:       using errcode = '42501';
1786:   end if;
1787: 
1788:   if p_cooperativa is null or p_cooperativa not in ('qorilazo', 'prodelco') then
1789:     raise exception 'Cooperativa invalida: debe ser qorilazo o prodelco'
1790:       using errcode = '22023';
1791:   end if;
1792:   -- El NaN se rechaza EXPLÍCITAMENTE y primero: `NaN <= 0` es false y
1793:   -- `NaN <> round(NaN,2)` también, así que sin esta línea se cuela por las dos
1794:   -- validaciones de abajo y acaba envenenando la suma de la cuota.
1795:   if p_monto is null or p_monto = 'NaN'::numeric or p_monto <= 0 then
1796:     raise exception 'El monto invertido debe ser mayor que cero'
1797:       using errcode = '22023';
1798:   end if;
1799:   if p_monto <> round(p_monto, 2) then
1800:     raise exception 'El monto admite como maximo 2 decimales'
1801:       using errcode = '22023';
1802:   end if;
1803:   if p_moneda is distinct from 'PEN' then
1804:     raise exception 'En cooperativas solo se registran inversiones en soles'
1805:       using errcode = '22023';
1806:   end if;
1807:   if v_transaccion is null or v_transaccion = '' then
1808:     raise exception 'El numero de operacion del deposito es obligatorio'
1809:       using errcode = '22023';
1810:   end if;
1811:   if length(v_transaccion) > 64 then
1812:     raise exception 'El numero de operacion admite como maximo 64 caracteres'
1813:       using errcode = '22023';
1814:   end if;
1815:   if v_referencia is not null and length(v_referencia) > 64 then
1816:     raise exception 'El numero de certificado admite como maximo 64 caracteres'
1817:       using errcode = '22023';
1818:   end if;
1819: 
1820:   select * into v_cierre
1821:   from crm.cierres_externos
1822:   where id = p_cierre_id
1823:   for update;
1824:   if not found then
1825:     raise exception 'Cierre externo no encontrado';
1826:   end if;
1827:   -- Un cierre anulado no se retoca: corregirlo daría a entender que vuelve a
1828:   -- contar, y no vuelve. Si el monto anulado estaba mal, da igual: no paga.
1829:   if v_cierre.anulado_en is not null then
1830:     raise exception using
1831:       errcode = 'P0409',
1832:       message = 'Ese cierre esta anulado: ya no cuenta y no se corrige',
1833:       detail  = pg_catalog.format('cierre %s, anulado el %s', v_cierre.id, v_cierre.anulado_en);
1834:   end if;
1835: 
1836:   perform set_config('crm.op_privilegiada', 'on', true);
1837:   begin
1838:     update crm.cierres_externos
1839:        set monto = p_monto,
1840:            moneda = p_moneda,
1841:            cooperativa = p_cooperativa,
1842:            numero_transaccion = v_transaccion,
1843:            referencia_externa = v_referencia,
1844:            vence_en = p_vence_en,
1845:            nota = nullif(btrim(p_nota), '')
1846:      where id = p_cierre_id;
1847: 
1848:     -- Si gerencia cambia el número, el NUEVO se reclama para siempre. El
1849:     -- ANTERIOR no se libera: sigue en la memoria histórica, que es justo lo que
1850:     -- impide que otro lead lo declare y el mismo depósito se cobre dos veces.
1851:     if upper(v_transaccion) is distinct from upper(v_cierre.numero_transaccion) then
1852:       insert into crm.depositos_reclamados (numero_norm, cierre_id, reclamado_por)
1853:       values (upper(v_transaccion), p_cierre_id, v_uid);
1854:     end if;
1855:   exception when unique_violation then
1856:     raise exception using
1857:       errcode = 'P0409',
1858:       message = 'Ese numero de operacion ya esta registrado',
1859:       hint    = 'Ese deposito ya se declaro antes (aunque su cierre se haya corregido despues): no se puede reusar.';
1860:   end;
1861:   perform set_config('crm.op_privilegiada', 'off', true);
1862: 
1863:   -- Rastro de negocio en la línea de tiempo del lead. Tipo 'nota' porque el
1864:   -- CHECK de actividades no tiene 'correccion' y ampliarlo por esto no paga:
1865:   -- el QUÉ cambió va en metadata (y el audit trigger guarda la fila entera).
1866:   if v_cierre.lead_id is not null then
1867:   insert into crm.actividades (
1868:     lead_id, tipo, detalle, metadata, creado_por
1869:   ) values (
1870:     v_cierre.lead_id,
1871:     'nota',
1872:     'Gerencia corrigio el cierre externo',
1873:     jsonb_build_object(
1874:       'accion', 'correccion_cierre_externo',
1875:       'cierre_externo_id', p_cierre_id,
1876:       'antes', jsonb_build_object(
1877:         'monto', v_cierre.monto, 'moneda', v_cierre.moneda,
1878:         'cooperativa', v_cierre.cooperativa,
1879:         'numero_transaccion', v_cierre.numero_transaccion,
1880:         'referencia_externa', v_cierre.referencia_externa,
1881:         'vence_en', v_cierre.vence_en, 'nota', v_cierre.nota),
1882:       'despues', jsonb_build_object(
1883:         'monto', p_monto, 'moneda', p_moneda,
1884:         'cooperativa', p_cooperativa,
1885:         'numero_transaccion', v_transaccion,
1886:         'referencia_externa', v_referencia,
1887:         'vence_en', p_vence_en, 'nota', nullif(btrim(p_nota), ''))
1888:     ),
1889:     v_uid
1890:   );
1891:   end if;
1892: 
1893:   return jsonb_build_object('ok', true, 'cierre_id', p_cierre_id);
1894: end;
1895: $function$;
1896: -- Adaptación acotada de crm.cierres_externos_fn(date); antes 337700989baed6b15f72349c021bb387
1897: CREATE OR REPLACE FUNCTION crm.cierres_externos_fn(p_periodo date)
1898:  RETURNS jsonb
1899:  LANGUAGE plpgsql
1900:  STABLE SECURITY DEFINER
1901:  SET search_path TO ''
1902: AS $function$
1903: declare
