1913:   v_fin        timestamptz;
1914:   v_payload    jsonb;
1915: begin
1916:   v_rol := private.rol_crm(v_uid);
1917:   v_lector := private.es_lector_global();
1918:   if v_uid is null
1919:      or not coalesce(v_rol in ('vendedor', 'supervisor', 'gerencia') or v_lector, false) then
1920:     raise exception 'No autorizado' using errcode = '42501';
1921:   end if;
1922: 
1923:   if p_periodo is null or p_periodo <> date_trunc('month', p_periodo)::date then
1924:     raise exception 'Periodo invalido: debe ser el primer dia del mes'
1925:       using errcode = '22023';
1926:   end if;
1927:   if p_periodo > v_mes_actual then
1928:     raise exception 'Periodo invalido: el mes no puede ser futuro'
1929:       using errcode = '22023';
1930:   end if;
1931: 
1932:   v_global := coalesce(v_rol = 'gerencia', false) or v_lector;
1933:   v_filas := coalesce(v_rol in ('vendedor', 'supervisor', 'gerencia'), false);
1934:   v_alcance := case
1935:     when v_global then 'global'
1936:     when v_rol = 'supervisor' then 'equipo'
1937:     else 'propio'
1938:   end;
1939:   v_visibles := case when v_global then '{}'::uuid[]
1940:                      else array(select private.vendedor_ids_visibles(v_uid)) end;
1941: 
1942:   v_ini := p_periodo::timestamp at time zone 'America/Lima';
1943:   v_fin := (p_periodo + interval '1 month')::timestamp at time zone 'America/Lima';
1944: 
1945:   select jsonb_build_object(
1946:     'version', 1,
1947:     'periodo', p_periodo,
1948:     'alcance', v_alcance,
1949:     -- Filas para la sección «En cooperativas» de Mi cartera (todo el
1950:     -- histórico del ámbito, más reciente primero). Tope de 200 con total al
1951:     -- lado: sin tope sería la lista sin fin que F2 vino a matar; con tope
1952:     -- mudo, el front sumaría filas truncadas y mentiría en los totales — por
1953:     -- eso los mini-totales NO salen de las filas sino de `totales`.
1954:     'cierres', case when not v_filas then '[]'::jsonb else coalesce((
1955:       select jsonb_agg(jsonb_build_object(
1956:         'cierre_id', ce.id,
1957:         'lead_id', ce.lead_id,
1958:         'cooperativa', ce.cooperativa,
1959:         'monto', ce.monto,
1960:         'moneda', ce.moneda,
1961:         'nombre_completo', ce.nombre_completo,
1962:         'documento_tipo', ce.documento_tipo,
1963:         'documento', ce.documento,
1964:         -- El teléfono se lee VIVO del lead, pero el ámbito de esta fila lo pone
1965:         -- `ce.vendedor_id`, que es una FOTO. Un lead convertido SÍ se puede
1966:         -- reasignar (el guard de tenencia solo veta cambios de etapa), así que
1967:         -- sin este recorte el vendedor original seguiría leyendo para siempre el
1968:         -- teléfono ACTUAL de un lead que ya no es suyo. La foto del cierre es
1969:         -- suya; los datos vivos del lead, no.
1970:         'telefono', case when v_global or case
1971:           -- F3 conserva la tenencia del lead convertido como historia. El
1972:           -- teléfono vivo de una persona reconocida sigue su relación actual.
1973:           when ce.inversionista_id is not null then exists (
1974:             select 1 from crm.inversionistas ip
1975:             where ip.id=private.inversionista_canonica(ce.inversionista_id)
1976:               and ip.responsable_relacion_id=any(v_visibles))
1977:           else l.vendedor_id=any(v_visibles) end
1978:                          then l.telefono end,
1979:         'numero_transaccion', ce.numero_transaccion,
1980:         'referencia_externa', ce.referencia_externa,
1981:         'vence_en', ce.vence_en,
1982:         'nota', ce.nota,
1983:         'vendedor_id', ce.vendedor_id,
1984:         'vendedor_nombre', p.nombre_completo,
1985:         'creado_en', ce.creado_en,
1986:         'fecha_comercial', coalesce(ce.fecha_comercial,(ce.creado_en at time zone 'America/Lima')::date),
1987:         'fecha_imputacion', coalesce(ce.fecha_imputacion,(ce.creado_en at time zone 'America/Lima')::date),
1988:         'es_cierre_inicial', ce.es_cierre_inicial,
1989:         -- Los anulados SÍ viajan en las filas (y NO en los totales): el asesor
1990:         -- tiene que poder entender por qué le bajó el total, no encontrarse un
1991:         -- hueco donde antes había un cierre.
1992:         'anulado_en', ce.anulado_en,
1993:         'motivo_anulacion', ce.motivo_anulacion
1994:       ) order by ce.creado_en desc)
1995:       from (
1996:         select *
1997:         from crm.cierres_externos ce0
1998:         where v_global or ce0.vendedor_id = any(v_visibles)
1999:         order by ce0.creado_en desc
2000:         limit 200
2001:       ) ce
2002:       left join crm.leads l on l.id = ce.lead_id
2003:       left join public.perfiles p on p.id = ce.vendedor_id
2004:     ), '[]'::jsonb) end,
2005:     'cierres_total', (
2006:       select count(*)::integer
2007:       from crm.cierres_externos ce
2008:       where v_global or ce.vendedor_id = any(v_visibles)
2009:     ),
2010:     -- Las filas DEL MES pedido: es la vista de revisión de supervisor y gerencia
2011:     -- («Ver cierres del mes»), donde el número de operación se contrasta. NO se
2012:     -- filtra en el cliente sobre `cierres`, que viene tope 200 por antigüedad y
2013:     -- podría no alcanzar el mes entero.
2014:     'cierres_mes', case when not v_filas then '[]'::jsonb else coalesce((
2015:       select jsonb_agg(jsonb_build_object(
2016:         'cierre_id', ce.id,
2017:         'lead_id', ce.lead_id,
2018:         'cooperativa', ce.cooperativa,
2019:         'monto', ce.monto,
2020:         'moneda', ce.moneda,
2021:         'nombre_completo', ce.nombre_completo,
2022:         'documento_tipo', ce.documento_tipo,
2023:         'documento', ce.documento,
2024:         -- El teléfono se lee VIVO del lead, pero el ámbito de esta fila lo pone
2025:         -- `ce.vendedor_id`, que es una FOTO. Un lead convertido SÍ se puede
2026:         -- reasignar (el guard de tenencia solo veta cambios de etapa), así que
2027:         -- sin este recorte el vendedor original seguiría leyendo para siempre el
2028:         -- teléfono ACTUAL de un lead que ya no es suyo. La foto del cierre es
2029:         -- suya; los datos vivos del lead, no.
2030:         'telefono', case when v_global or case
2031:           -- F3 conserva la tenencia del lead convertido como historia. El
2032:           -- teléfono vivo de una persona reconocida sigue su relación actual.
2033:           when ce.inversionista_id is not null then exists (
2034:             select 1 from crm.inversionistas ip
2035:             where ip.id=private.inversionista_canonica(ce.inversionista_id)
2036:               and ip.responsable_relacion_id=any(v_visibles))
2037:           else l.vendedor_id=any(v_visibles) end
2038:                          then l.telefono end,
2039:         'numero_transaccion', ce.numero_transaccion,
2040:         'referencia_externa', ce.referencia_externa,
2041:         'vence_en', ce.vence_en,
2042:         'nota', ce.nota,
2043:         'vendedor_id', ce.vendedor_id,
2044:         'vendedor_nombre', p.nombre_completo,
2045:         'creado_en', ce.creado_en,
2046:         'fecha_comercial', coalesce(ce.fecha_comercial,(ce.creado_en at time zone 'America/Lima')::date),
2047:         'fecha_imputacion', coalesce(ce.fecha_imputacion,(ce.creado_en at time zone 'America/Lima')::date),
2048:         'es_cierre_inicial', ce.es_cierre_inicial,
2049:         'anulado_en', ce.anulado_en,
2050:         'motivo_anulacion', ce.motivo_anulacion
2051:       ) order by ce.creado_en desc)
2052:       from (
2053:         select *
2054:         from crm.cierres_externos ce0
2055:         where coalesce((ce0.fecha_imputacion::timestamp at time zone 'America/Lima'),ce0.creado_en) >= v_ini and coalesce((ce0.fecha_imputacion::timestamp at time zone 'America/Lima'),ce0.creado_en) < v_fin
2056:           and (v_global or ce0.vendedor_id = any(v_visibles))
2057:         order by ce0.creado_en desc
2058:         limit 200
2059:       ) ce
2060:       left join crm.leads l on l.id = ce.lead_id
2061:       left join public.perfiles p on p.id = ce.vendedor_id
2062:     ), '[]'::jsonb) end,
2063:     'cierres_mes_total', (
2064:       select count(*)::integer
2065:       from crm.cierres_externos ce
2066:       where coalesce((ce.fecha_imputacion::timestamp at time zone 'America/Lima'),ce.creado_en) >= v_ini and coalesce((ce.fecha_imputacion::timestamp at time zone 'America/Lima'),ce.creado_en) < v_fin
2067:         and (v_global or ce.vendedor_id = any(v_visibles))
2068:     ),
2069:     -- Mini-totales de Mi cartera: TODO el histórico del ámbito, por
2070:     -- cooperativa y moneda (PEN/USD jamás sumados). Servidos aquí para que el
2071:     -- front no haga aritmética sobre una lista que puede venir truncada.
2072:     'totales', coalesce((
2073:       select jsonb_agg(jsonb_build_object(
2074:         'cooperativa', t.cooperativa,
2075:         'moneda', t.moneda,
2076:         'capital', t.capital,
2077:         'cierres', t.cierres
2078:       ) order by t.cooperativa, t.moneda)
2079:       from (
2080:         select ce.cooperativa, ce.moneda,
2081:                sum(ce.monto) as capital,
2082:                count(*)::integer as cierres
2083:         from crm.cierres_externos ce
2084:         where (v_global or ce.vendedor_id = any(v_visibles))
2085:           -- ATR-4 (regla 31/08): los anulados REALES SIGUEN siendo dinero.
2086:           -- Fuera SOLO la demo declarada (la misma exclusion por id que el
2087:           -- nucleo; si algun dia nace otra demo, se tocan los dos JUNTOS).
2088:           and ce.id <> 'a112aead-184a-4979-9041-943978fadae4'::uuid
2089:         group by ce.cooperativa, ce.moneda
2090:       ) t
2091:     ), '[]'::jsonb),
2092:     -- Desglose por empresa del MES pedido, por vendedor × cooperativa ×
2093:     -- moneda, para supervisor y gerencia. La parte «Avance» del desglose la
2094:     -- pone cumplimiento_metas_fn (capital_real ya INCLUYE los externos tras
2095:     -- esta migración): Avance = capital_real − estos agregados, resta de dos
2096:     -- números servidos — no una división en cliente.
2097:     'por_empresa', coalesce((
2098:       select jsonb_agg(jsonb_build_object(
2099:         'vendedor_id', x.vendedor_id,
2100:         'vendedor_nombre', x.nombre,
2101:         'cooperativa', x.cooperativa,
2102:         'moneda', x.moneda,
2103:         'capital', x.capital,
2104:         'cierres', x.cierres
2105:       ) order by x.nombre, x.cooperativa, x.moneda)
2106:       from (
2107:         select ce.vendedor_id, p.nombre_completo as nombre,
2108:                ce.cooperativa, ce.moneda,
2109:                sum(ce.monto) as capital,
2110:                count(*)::integer as cierres
2111:         from crm.cierres_externos ce
2112:         left join public.perfiles p on p.id = ce.vendedor_id
2113:         where coalesce((ce.fecha_imputacion::timestamp at time zone 'America/Lima'),ce.creado_en) >= v_ini and coalesce((ce.fecha_imputacion::timestamp at time zone 'America/Lima'),ce.creado_en) < v_fin
2114:           and (v_global or ce.vendedor_id = any(v_visibles))
2115:           -- ATR-4 (regla 31/08): los anulados REALES SIGUEN siendo dinero.
2116:           -- Fuera SOLO la demo declarada (la misma exclusion por id que el
2117:           -- nucleo; si algun dia nace otra demo, se tocan los dos JUNTOS).
2118:           and ce.id <> 'a112aead-184a-4979-9041-943978fadae4'::uuid
2119:         group by ce.vendedor_id, p.nombre_completo, ce.cooperativa, ce.moneda
2120:       ) x
2121:     ), '[]'::jsonb)
2122:   ) into v_payload;
2123: 
2124:   return v_payload;
2125: end;
2126: $function$;
2127: -- Adaptación acotada de private.metricas_conversiones_implementacion(date, date, text); antes be4e1c283a1f3042828cbb8c66332252
2128: CREATE OR REPLACE FUNCTION private.metricas_conversiones_implementacion(p_desde date, p_hasta date, p_origen text DEFAULT NULL::text)
2129:  RETURNS jsonb
2130:  LANGUAGE plpgsql
2131:  STABLE SECURITY DEFINER
2132:  SET search_path TO ''
2133: AS $function$
2134: declare
2135:   v_uid uuid := (select auth.uid());
2136:   v_hoy date := (now() at time zone 'America/Lima')::date;
2137:   v_ini timestamptz;
2138:   v_fin timestamptz;
2139:   v_cosecha_fin timestamptz;
