2148:     select 1 from crm.equipo e
2149:     join public.perfiles p on p.id = e.perfil_id
2150:     where e.perfil_id = v_uid and e.activo and p.activo and e.rol_crm = 'gerencia'
2151:   ) or private.es_lector_global() into v_autorizado;
2152:   if v_uid is null or not coalesce(v_autorizado, false) then
2153:     raise exception 'No autorizado' using errcode = '42501';
2154:   end if;
2155:   if p_desde is null or p_hasta is null or p_desde > p_hasta
2156:      or p_hasta > v_hoy or p_hasta - p_desde > 365 then
2157:     raise exception 'Periodo invalido' using errcode = '22023';
2158:   end if;
2159:   v_ini := p_desde::timestamp at time zone 'America/Lima';
2160:   v_fin := (p_hasta + 1)::timestamp at time zone 'America/Lima';
2161: 
2162:   -- La cosecha mira hasta HOY: un lead que entro en el rango puede haber
2163:   -- cerrado despues, y esa maduracion es justamente lo que la lectura por
2164:   -- cosecha responde («de ese lote, cuantos acabaron cerrando»).
2165:   v_cosecha_fin := greatest(v_fin, v_ahora);
2166: 
2167:   -- Peso del referido del mes del `hasta` — la MISMA regla que usa el heroe
2168:   -- de HOY para el mes del rango.
2169:   v_mes := date_trunc('month', p_hasta)::date;
2170:   v_factor := private.peso_referido_conversion(v_mes);
2171: 
2172:   -- El periodo identifica una ventana mensual; ya NO habilita/deshabilita
2173:   -- cartera: el núcleo limita toda operación a su fecha efectiva en el rango.
2174:   -- En rangos libres aplica el peso de cada mes dentro del propio núcleo.
2175:   v_periodo := case
2176:     when p_desde = date_trunc('month', p_desde)::date
2177:      and date_trunc('month', p_hasta)::date = date_trunc('month', p_desde)::date
2178:      and (p_hasta = (date_trunc('month', p_desde) + interval '1 month' - interval '1 day')::date
2179:           or p_hasta = v_hoy)
2180:     then p_desde
2181:   end;
2182: 
2183:   with vendedores_base as materialized (
2184:     select e.perfil_id as vendedor_id
2185:     from crm.equipo e
2186:     join public.perfiles p on p.id = e.perfil_id
2187:     where e.activo and p.activo and e.rol_crm = 'vendedor'
2188:   ),
2189:   -- ── TABLA-BASE ──────────────────────────────────────────────────────────
2190:   -- Flujo comercial del rango: llegadas únicas y aportes del núcleo.
2191:   ep_flujo as materialized (
2192:     select e.* from private.conversion_episodios(
2193:       v_ini, v_fin, v_periodo, true, null, v_factor
2194:     ) e
2195:   ),
2196:   -- Cierres del ledger que sirven de numerador a la COSECHA: los de sus
2197:   -- leads, ocurran cuando ocurran (hasta hoy). Sin anulados.
2198:   ep_cosecha as materialized (
2199:     select distinct e.lead_id
2200:     from private.conversion_episodios(
2201:       v_ini, v_cosecha_fin, null, true, null, v_factor
2202:     ) e
2203:     where e.tipo = 'cierre' and not e.anulado and e.origen in ('landing', 'formulario', 'referido') and e.lead_id is not null
2204:   ),
2205:   cohorte_base as materialized (
2206:     -- F1.3b: el capital del lead se mide por los caminos VIVOS y HASTA HOY
2207:     -- (lectura de cosecha: «de ese lote, cuanto ha producido»): contratos del
2208:     -- portal de su perfil + cierres en coops vigentes. Aqui muere la primera
2209:     -- de las dos ultimas lecturas del enlace jamas poblado (leads.contrato_id).
2210:     select l.id, l.origen, l.etapa, l.categoria_interes, l.creado_en,
2211:       l.convertido_en, l.perfil_id, l.contrato_id, l.asignado_supervisor_id,
2212:       l.creado_por, llegada.analista_id as vendedor_id,
2213:       (coalesce((select sum(k.monto) from private.capital_episodios(
2214:            '-infinity'::timestamptz,
2215:            'infinity'::timestamptz, true, '{}'::uuid[]) k
2216:          where k.moneda = 'PEN'
2217:            and (   (k.tipo like 'contrato_%' and k.cliente_id = l.perfil_id)
2218:                 or (k.tipo = 'cooperativa'   and k.lead_id   = l.id))), 0)) as capital_lead_pen,
2219:       (coalesce((select sum(k.monto) from private.capital_episodios(
2220:            '-infinity'::timestamptz,
2221:            'infinity'::timestamptz, true, '{}'::uuid[]) k
2222:          where k.moneda = 'USD'
2223:            and (   (k.tipo like 'contrato_%' and k.cliente_id = l.perfil_id)
2224:                 or (k.tipo = 'cooperativa'   and k.lead_id   = l.id))), 0)) as capital_lead_usd
2225:     from ep_flujo llegada
2226:     join crm.leads l on l.id = llegada.lead_id
2227:     where llegada.tipo = 'recibido'
2228:       -- Filtro de ORIGEN (pedido de Miguel 27/08): recorta el LOTE — cohorte,
2229:       -- embudo, origenes, categorias, responsables y tendencia beben todos de
2230:       -- aqui. 'sin_origen' selecciona los leads sin origen registrado. El
2231:       -- nucleo y las sondas de paridad NO se filtran (miden el MES de la
2232:       -- empresa y esta pantalla ya no los pinta): el payload declara el
2233:       -- filtro en `origen_filtrado` para que nadie confunda las dos aguas.
2234:       and (p_origen is null or coalesce(l.origen, 'sin_origen') = p_origen)
2235:   ),
2236:   -- N1: citas clasificadas por el núcleo, sobre el lote de llegadas. El
2237:   -- instante disponible es vence_en (fecha prevista); no se inventa una fecha
2238:   -- física de asistencia ni una identidad de persona distinta de lead_id.
2239:   citas_reales_ep as materialized (
2240:     select ce.*
2241:     from private.citas_episodios(v_ini, v_ahora, v_ahora) ce
2242:     where ce.realizada and ce.debio_ocurrir
2243:   ),
2244:   citas_reales_cohorte as materialized (
2245:     select cb.id as lead_id,
2246:       count(ce.tarea_id) filter (where ce.vence_en >= cb.creado_en)::int
2247:         as citas_realizadas,
2248:       count(ce.tarea_id) filter (where ce.vence_en < cb.creado_en)::int
2249:         as citas_anteriores_al_alta
2250:     from cohorte_base cb
2251:     left join citas_reales_ep ce on ce.lead_id = cb.id
2252:     group by cb.id
2253:   ),
2254:   senales as materialized (
2255:     select cb.*,
2256:       (cb.vendedor_id is not null or cb.asignado_supervisor_id is not null or exists (
2257:         select 1 from crm.lead_asignaciones la where la.lead_id = cb.id
2258:       )) as h_asignado,
2259:       exists (
2260:         select 1 from crm.actividades a
2261:         where a.lead_id = cb.id and (
2262:           a.tipo in ('llamada_realizada','whatsapp_recibido','reunion_realizada')
2263:           or (a.tipo = 'cambio_etapa' and a.metadata->>'etapa_nueva' in (
2264:             'contactado','reunion_agendada','propuesta_enviada','convertido'
2265:           ))
2266:         )
2267:       ) as h_contacto,
2268:       exists (
2269:         select 1 from crm.tareas t where t.lead_id = cb.id and t.tipo = 'reunion'
2270:       ) or exists (
2271:         select 1 from crm.actividades a where a.lead_id = cb.id
2272:           and a.tipo = 'cambio_etapa' and a.metadata->>'etapa_nueva' = 'reunion_agendada'
2273:       ) as h_reunion_agendada,
2274:       exists (
2275:         select 1 from crm.tareas t where t.lead_id = cb.id
2276:           and t.tipo = 'reunion' and t.estado = 'completada'
2277:       ) or exists (
2278:         select 1 from crm.actividades a where a.lead_id = cb.id and a.tipo = 'reunion_realizada'
2279:       ) as h_reunion_realizada,
2280:       exists (
2281:         select 1 from crm.actividades a where a.lead_id = cb.id
2282:           and a.tipo = 'cambio_etapa' and a.metadata->>'etapa_nueva' = 'propuesta_enviada'
2283:       ) or cb.etapa = 'propuesta_enviada' as h_propuesta,
2284:       -- ANTES: (perfil_id is not null or etapa = 'convertido') / (contrato_id is not null)
2285:       -- AHORA: el cierre del LEDGER, sin anulados. Un cierre anulado por
2286:       -- gerencia deja de contar aqui igual que en el nucleo.
2287:       (cb.id in (select ec.lead_id from ep_cosecha ec)) as h_cliente,
2288:       (cb.id in (select ec.lead_id from ep_cosecha ec)) as h_contrato
2289:     from cohorte_base cb
2290:   ),
2291:   cohorte as materialized (
2292:     select s.*,
2293:       (cr.citas_realizadas > 0) as cita_real,
2294:       cr.citas_realizadas as citas_realizadas_reales,
2295:       cr.citas_anteriores_al_alta,
2296:       h_asignado as asignado,
2297:       (h_contacto or h_reunion_agendada or h_reunion_realizada or h_propuesta or h_cliente or h_contrato) as contactado,
2298:       (h_reunion_agendada or h_reunion_realizada or h_propuesta or h_cliente or h_contrato) as reunion_agendada,
2299:       (h_reunion_realizada or h_propuesta or h_cliente or h_contrato) as reunion_realizada,
2300:       (h_propuesta or h_cliente or h_contrato) as propuesta,
2301:       (h_cliente or h_contrato) as cliente,
2302:       h_contrato as contrato
2303:     from senales s
2304:     join citas_reales_cohorte cr on cr.lead_id = s.id
2305:   ),
2306:   resumen as (
2307:     select
2308:       count(*)::int as leads,
2309:       count(*) filter (where asignado)::int as asignados,
2310:       count(*) filter (where contactado)::int as contactados,
2311:       count(*) filter (where reunion_agendada)::int as reuniones_agendadas,
2312:       count(*) filter (where reunion_realizada)::int as reuniones_realizadas,
2313:       count(*) filter (where cita_real)::int as leads_con_cita_real,
2314:       coalesce(sum(citas_realizadas_reales), 0)::int as citas_realizadas_reales,
2315:       coalesce(sum(citas_anteriores_al_alta), 0)::int as citas_anteriores_al_alta,
2316:       count(*) filter (where propuesta)::int as propuestas,
2317:       count(*) filter (where cliente)::int as clientes,
2318:       count(*) filter (where contrato)::int as contratos,
2319:       count(*) filter (where etapa = 'descartado')::int as descartados
2320:     from cohorte
2321:   ),
2322:   -- ── NUCLEO (cifra principal) ────────────────────────────────────────────
2323:   -- Se agrupa POR ANALISTA con la misma aritmetica del nucleo y luego se suma.
2324:   -- OJO: el total NO tiene por que ser la suma de `responsables`: aqui entran
2325:   -- TODOS los analistas con episodios (supervisores incluidos), mientras que
2326:   -- `responsables` sale del roster de vendedores activos y ademas el wrapper
2327:   -- publico elimina del array a quien no sea vendedor. La sonda
2328:   -- `divisor_fuera_del_roster` mide exactamente ese hueco.
2329:   nucleo_vendedor as (
2330:     select e.analista_id,
2331:       coalesce(sum(e.aporte_divisor), 0)::int as divisor,
2332:       count(*) filter (where e.tipo = 'recibido' and e.fue_referido)::int as referidos_recibidos,
2333:       count(distinct e.lead_id) filter (where e.tipo = 'cierre' and not e.anulado and e.origen in ('landing', 'formulario', 'referido') and not e.fue_referido)::int as cierres_no_referidos,
2334:       count(distinct e.lead_id) filter (where e.tipo = 'cierre' and not e.anulado and e.origen in ('landing', 'formulario', 'referido') and e.fue_referido)::int as cierres_referidos,
2335:       count(*) filter (where e.tipo = 'operacion')::int as operaciones,
2336:       coalesce(sum(e.aporte_numerador), 0)::numeric as numerador
2337:     from ep_flujo e
2338:     group by e.analista_id
2339:   ),
2340:   nucleo as (
2341:     select
2342:       coalesce(sum(nv.divisor), 0)::int as divisor,
2343:       coalesce(sum(nv.referidos_recibidos), 0)::int as referidos_recibidos,
2344:       coalesce(sum(nv.cierres_no_referidos), 0)::int as cierres_no_referidos,
2345:       coalesce(sum(nv.cierres_referidos), 0)::int as cierres_referidos,
2346:       coalesce(sum(nv.operaciones), 0)::int as operaciones,
2347:       coalesce(sum(nv.numerador), 0)::numeric as numerador
2348:     from nucleo_vendedor nv
2349:   ),
2350:   -- Sonda de paridad: cuando el rango es un mes exacto, este recomputo debe
2351:   -- coincidir EXACTAMENTE con el nucleo. Si no, el front avisa.
2352:   -- Sonda de paridad: compara TODOS los terminos (divisor, ambos tipos de
2353:   -- cierre y el numerador entero — que es donde vive la cartera), y declara
2354:   -- cuantas filas comparo: sin filas la paridad no prueba nada y se dice
2355:   -- (`cuadra` = null), en vez de dar un cero tranquilizador y vacuo.
2356:   comparacion as (
2357:     select nv.analista_id as a_nuevo, cm.analista_id as a_nucleo,
2358:       abs(coalesce(nv.divisor, 0) - coalesce(cm.divisor, 0))
2359:       + abs(coalesce(nv.cierres_no_referidos, 0) - coalesce(cm.cierres_no_referidos, 0))
2360:       + abs(coalesce(nv.cierres_referidos, 0) - coalesce(cm.cierres_referidos, 0))
2361:       + abs(coalesce(
2362:           nv.numerador, 0)
2363:         - coalesce(cm.numerador, 0)) as delta
2364:     from nucleo_vendedor nv
2365:     full outer join private.conversion_mensual_por_vendedor(
2366:       v_ini, v_fin, true, null, v_factor
2367:     ) cm on coalesce(cm.analista_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(nv.analista_id, '00000000-0000-0000-0000-000000000000'::uuid)
2368:   ),
2369:   sonda_paridad as (
2370:     select
2371:       coalesce(sum(c.delta), 0) as desvio,
2372:       count(*)::int as filas
2373:     from comparacion c
2374:   ),
2375:   produccion as (
2376:     select
2377:       (select count(*)::int from crm.leads l
2378:         where l.convertido_en >= v_ini and l.convertido_en < v_fin) as clientes,
2379:       -- F1.3 (27/08): el enlace leads.contrato_id JAMAS se poblo (auditoria en
2380:       -- prod: 0 enlaces historicos, S/ 0 eterno con capital real cerrado) y
2381:       -- ningun flujo lo escribe. El camino VIVO es el perfil nacido del lead
2382:       -- (leads.perfil_id = contratos.cliente_id) mas los cierres en
2383:       -- cooperativas (crm.cierres_externos por lead, sin anulados). La columna
2384:       -- contrato_id no se toca: en produccion no se borra nada.
2385:       ((select count(*)::int from (select * from public.contratos where not es_demo) c
2386:         where c.fecha_cierre_comercial >= p_desde and c.fecha_cierre_comercial <= p_hasta
2387:           and exists (select 1 from crm.leads l where l.perfil_id = c.cliente_id))
2388:        + (select count(*)::int from crm.cierres_externos ce
2389:           where ce.anulado_en is null
2390:             and (coalesce((ce.fecha_imputacion::timestamp at time zone 'America/Lima'),ce.creado_en) at time zone 'America/Lima')::date between p_desde and p_hasta)) as contratos,
2391:       (coalesce((select sum(k.monto) from private.capital_episodios(
2392:            (p_desde::timestamp at time zone 'America/Lima'),
2393:            ((p_hasta + 1)::timestamp at time zone 'America/Lima'), true, '{}'::uuid[]) k
2394:          where k.moneda = 'PEN'
2395:            and (   (k.tipo like 'contrato_%'
2396:                     and exists (select 1 from crm.leads l where l.perfil_id = k.cliente_id))
2397:                 or k.tipo = 'cooperativa')), 0)) as capital_pen,
2398:       (coalesce((select sum(k.monto) from private.capital_episodios(
2399:            (p_desde::timestamp at time zone 'America/Lima'),
2400:            ((p_hasta + 1)::timestamp at time zone 'America/Lima'), true, '{}'::uuid[]) k
2401:          where k.moneda = 'USD'
2402:            and (   (k.tipo like 'contrato_%'
2403:                     and exists (select 1 from crm.leads l where l.perfil_id = k.cliente_id))
2404:                 or k.tipo = 'cooperativa')), 0)) as capital_usd,
2405:       -- Sonda F1.3: convertidos del rango SIN rastro de capital (ni perfil ni
2406:       -- cierre externo vigente). El hueco se declara; el front lo rotula.
2407:       (select count(*)::int from crm.leads l
2408:         where l.convertido_en >= v_ini and l.convertido_en < v_fin
2409:           and l.perfil_id is null
2410:           and not exists (select 1 from crm.cierres_externos ce
2411:                           where ce.lead_id = l.id and ce.es_cierre_inicial and ce.anulado_en is null)) as sin_rastro
2412:   ),
2413:   origenes as (
2414:     select coalesce(origen, 'sin_origen') as origen,
2415:       count(*)::int as leads,
2416:       count(*) filter (where contactado)::int as contactados,
2417:       count(*) filter (where reunion_agendada)::int as reuniones_agendadas,
2418:       count(*) filter (where reunion_realizada)::int as reuniones_realizadas,
2419:       count(*) filter (where cita_real)::int as leads_con_cita_real,
2420:       coalesce(sum(citas_realizadas_reales), 0)::int as citas_realizadas_reales,
2421:       count(*) filter (where cliente)::int as clientes,
2422:       count(*) filter (where contrato)::int as contratos,
2423:       count(*) filter (where etapa = 'descartado')::int as descartados,
2424:       coalesce(sum(capital_lead_pen), 0) as capital_pen,
2425:       coalesce(sum(capital_lead_usd), 0) as capital_usd
2426:     from cohorte group by coalesce(origen, 'sin_origen')
2427:   ),
2428:   categorias as (
2429:     select coalesce(categoria_interes, 'sin_categoria') as categoria,
2430:       count(*)::int as leads,
2431:       count(*) filter (where cliente)::int as clientes,
2432:       count(*) filter (where contrato)::int as contratos,
2433:       count(*) filter (where etapa = 'descartado')::int as descartados
2434:     from cohorte group by coalesce(categoria_interes, 'sin_categoria')
2435:   ),
2436:   responsables_resumen as (
2437:     select vb.vendedor_id,
2438:       count(c.id)::int as leads,
2439:       count(c.id) filter (where c.contactado)::int as contactados,
2440:       count(c.id) filter (where c.reunion_realizada)::int as reuniones_realizadas,
2441:       count(c.id) filter (where c.cita_real)::int as leads_con_cita_real,
2442:       coalesce(sum(c.citas_realizadas_reales), 0)::int as citas_realizadas_reales,
2443:       count(c.id) filter (where c.contrato)::int as contratos
2444:     from vendedores_base vb
2445:     left join cohorte c on c.vendedor_id = vb.vendedor_id
2446:     group by vb.vendedor_id
2447:   ),
2448:   capital_responsables as (
2449:     -- F1.3b: capital DEL RANGO por vendedor, por los caminos vivos — contratos
2450:     -- del portal (fecha de cierre en el rango) de perfiles nacidos de SUS
2451:     -- leads (el `in` dedupe si dos leads compartieran perfil) + sus cierres en
2452:     -- coops del rango. Aqui muere la ULTIMA lectura del enlace jamas poblado.
2453:     select vb.vendedor_id,
2454:       (coalesce((select sum(k.monto) from private.capital_episodios(
2455:            (p_desde::timestamp at time zone 'America/Lima'),
2456:            ((p_hasta + 1)::timestamp at time zone 'America/Lima'), true, '{}'::uuid[]) k
2457:          where k.moneda = 'PEN'
2458:            and (   (k.tipo like 'contrato_%'
2459:                     and k.cliente_id in (select l.perfil_id from crm.leads l
2460:                                          where l.vendedor_id = vb.vendedor_id and l.perfil_id is not null))
2461:                 or (k.tipo = 'cooperativa' and k.analista_id = vb.vendedor_id))), 0)) as capital_pen,
2462:       (coalesce((select sum(k.monto) from private.capital_episodios(
2463:            (p_desde::timestamp at time zone 'America/Lima'),
2464:            ((p_hasta + 1)::timestamp at time zone 'America/Lima'), true, '{}'::uuid[]) k
2465:          where k.moneda = 'USD'
2466:            and (   (k.tipo like 'contrato_%'
2467:                     and k.cliente_id in (select l.perfil_id from crm.leads l
2468:                                          where l.vendedor_id = vb.vendedor_id and l.perfil_id is not null))
2469:                 or (k.tipo = 'cooperativa' and k.analista_id = vb.vendedor_id))), 0)) as capital_usd
2470:     from vendedores_base vb
2471:   )
2472:   select jsonb_build_object(
2473:     'version', 1,
2474:     'origen_filtrado', p_origen,
2475:     'generado_en', now(),
2476:     'periodo', jsonb_build_object(
2477:       'desde', p_desde, 'hasta', p_hasta,
2478:       'dias', (p_hasta - p_desde) + 1, 'zona', 'America/Lima'
2479:     ),
2480:     'nucleo', jsonb_build_object(
2481:       'llegadas', (select count(*) from ep_flujo e where e.tipo = 'recibido'),
2482:       'altas_manuales', (select count(*) from ep_flujo e
2483:         where e.tipo = 'recibido' and not e.fue_referido and e.aporte_divisor = 0),
2484:       'renovaciones', (select count(*) from ep_flujo e where e.tipo = 'operacion' and e.categoria = 'renovacion'),
2485:       'upgrades', (select count(*) from ep_flujo e where e.tipo = 'operacion' and e.categoria = 'upgrade'),
2486:       'aporte_cartera', (select coalesce(sum(e.aporte_numerador), 0) from ep_flujo e where e.tipo = 'operacion'),
2487:       'base', 'llegada_unica',
2488:       'atribucion', 'primer_analista',
2489:       'peso_renovacion', v_factor,
2490:       'incluye_cartera', true,
2491:       'peso_referido', v_factor,
2492:       'mes_peso', v_mes,
