2853:         ), '[]'::jsonb)
2854:       ) order by rr.contratos desc, rr.leads desc, rr.vendedor_id)
2855:       from responsables_resumen rr
2856:       join capital_responsables cr on cr.vendedor_id = rr.vendedor_id
2857:       left join nucleo_vendedor nv on nv.analista_id = rr.vendedor_id
