2959:   -- aquí habla el idioma del formulario, no el del constraint.
2960:   if (p_documento_tipo = 'DNI'       and v_documento !~ '^[0-9]{8}$')
2961:      or (p_documento_tipo = 'CE'        and v_documento !~ '^[0-9]{9,12}$')
