2971:   -- índice): es lo único que impide cobrar dos veces un mismo cierre real.
2972:   if v_transaccion is null or v_transaccion = '' then
2973:     raise exception 'El numero de operacion del deposito es obligatorio'
2974:       using errcode = '22023';
2975:   end if;
2976:   if length(v_transaccion) > 64 then
2977:     raise exception 'El numero de operacion admite como maximo 64 caracteres'
2978:       using errcode = '22023';
2979:   end if;
