2993:   -- ── PUERTA DE IDENTIDAD (solo con la bandera encendida) ──────────────────
2994:   -- Resolver ANTES del lock del lead (orden identidad->lead, comparte orden con
2995:   -- la fusión y mata el deadlock). El documento ya se validó arriba. Con bandera
2996:   -- APAGADA nada de esto corre (comportamiento idéntico a hoy).
2997:   if v_flag then
2998:     v_inv := private.inversionista_resolver(p_documento_tipo, v_documento, true, 'conversion');
2999:     perform 1 from crm.inversionistas where id = v_inv for update;
3000:     -- F2.b (b4): la PERSONA (no solo este lead) puede tener una conversión Avance en curso en OTRO
