3005:                   and (r.efectos_iniciados_en is not null or r.expira_en > now())) then
3006:       raise exception using
3007:         errcode = 'P0409',
3008:         message = 'Esta persona tiene una conversion a cliente de Avance en curso en otro lead',
3009:         hint    = 'Quien la empezo tiene que terminarla o dejar que caduque.';
