3013:   -- Ámbito y lock: copiados VERBATIM de crm.convertir_lead para que los dos
3014:   -- caminos de conversión signifiquen lo mismo.
3015:   select *
3016:     into v_lead
3017:   from crm.leads
3018:   where id = p_lead_id
3019:     and activo = true
3020:     and (
3021:       v_rol = 'gerencia'
3022:       or vendedor_id in (
3023:         select private.vendedor_ids_visibles((select auth.uid()))
3024:       )
3025:       or (
3026:         vendedor_id is null
3027:         and asignado_supervisor_id in (
3028:           select private.vendedor_ids_visibles((select auth.uid()))
3029:         )
3030:       )
3031:     )
3032:   for update;
3033:   if not found then
3034:     raise exception 'Lead no encontrado o fuera de tu ambito';
3035:   end if;
3036: 
3037:   -- Reintento tras éxito: el lead ya se convirtió y su cierre lleva ESTE número de
3038:   -- operación -> mismo resultado, sin efectos (idempotente).
3039:   if v_flag and v_lead.etapa = 'convertido' then
3040:     -- Revalidar TRAS el lock (Codex): la clave guardada manda; payload distinto → P0409.
3041:     v_prev := private.idem_leer(v_clave, v_hash);
3042:     if v_prev is not null then
3043:       return v_prev || pg_catalog.jsonb_build_object('reintento', true);
3044:     end if;
3045:     -- Sin clave guardada (p.ej. conversión previa a este lote): mismo número de
3046:     -- operación en su cierre = mismo hecho.
3047:     select ce.id into v_cierre_id
3048:     from crm.cierres_externos ce
3049:     where ce.lead_id = p_lead_id and ce.es_cierre_inicial
3050:       and upper(ce.numero_transaccion) = upper(v_transaccion)
3051:     limit 1;
