3053:       v_res := pg_catalog.jsonb_build_object('ok', true, 'lead_id', p_lead_id, 'cierre_id', v_cierre_id,
3054:                                              'cooperativa', p_cooperativa);
3055:       perform private.idem_guardar(v_clave, 'conversion_coop', v_hash, v_res, v_uid);
3056:       return v_res || pg_catalog.jsonb_build_object('reintento', true);
3057:     end if;
3058:   end if;
3059:   if v_lead.etapa in ('convertido', 'descartado') then
3060:     raise exception 'El lead ya esta cerrado';
3061:   end if;
3062:   if v_lead.vendedor_id is null then
3063:     raise exception 'Asigna el lead a un analista antes de convertirlo'
3064:       using errcode = '22023';
3065:   end if;
3066: 
3067:   -- Un solo lead total (invariante #6, decisión Miguel 03/09): un 2.º lead de la
3068:   -- misma persona no se convierte aquí; la nueva inversión sobre el cliente
3069:   -- existente es F5. Mensaje de negocio en vez del choque con leads_inversionista_uidx.
3070:   if v_flag and v_inv is not null then
3071:     select l2.id into v_lead_canon from crm.leads l2
3072:     where l2.inversionista_id = v_inv and l2.id <> p_lead_id limit 1;
3073:     if v_lead_canon is not null then
3074:       raise exception 'Esta persona ya tiene un lead; registra la nueva inversion sobre ese lead, no conviertas otro'
3075:         using errcode = 'P0409';
3076:     end if;
3077:   end if;
3078:   -- F2.b (b5) [Codex B2]: «un solo lead» cuenta también el PUENTE (históricos del backfill sin enlace vivo).
3079:   if v_flag and v_inv is not null
3080:      and exists (select 1 from private.leads_de_identidades(array[v_inv]) x where x <> p_lead_id) then
