3087:      and exists (select 1 from private.leads_de_personas(array[v_inv]) x where x <> p_lead_id) then
3088:     raise exception 'Esta persona ya tiene un lead; registra la nueva inversion sobre ese lead, no conviertas otro'
3089:       using errcode = 'P0409';
3090:   end if;
3091:   -- F2.b (b5) [E3-11]: la persona YA reconocida de este lead manda; el documento del cierre
3092:   -- no se lo lleva a otra identidad (eso es corrección o fusión de Gerencia).
