3129:     -- Caducada y sin efectos: no manda.
3130:     v_reserva := null;
3131:   end if;
3132:   if v_efectos is not null then
3133:     -- Ya existe una cuenta de portal a nombre de esta persona. Este cierre NO
3134:     -- puede entrar nunca: sería justo el inversionista de cooperativa con
3135:     -- portal que toda esta función existe para impedir.
3136:     raise exception using
3137:       errcode = 'P0409',
3138:       message = 'Esta persona ya tiene una cuenta de cliente de Avance en proceso',
3139:       hint    = 'Se le creo (o se le esta creando) su acceso al portal. Termina esa conversion; este lead ya no se puede cerrar en una cooperativa.';
3140:   end if;
3141:   if v_reserva is not null then
3142:     raise exception using
3143:       errcode = 'P0409',
3144:       message = 'Hay una conversion a cliente de Avance en curso para este lead',
3145:       hint    = pg_catalog.format(
3146:         'Vuelve a intentarlo despues de las %s (hora de Lima). Si esa conversion no debia hacerse, avisa antes de cerrar en la cooperativa.',
3147:         pg_catalog.to_char(v_reserva at time zone 'America/Lima', 'HH24:MI'));
