3149: 
3150:   -- La FOTO primero: así, cuando el UPDATE de etapa dispare el BEFORE trigger,
3151:   -- la P4 relajada ya encuentra el cierre y deja pasar el convertido sin
3152:   -- perfil. El UNIQUE(lead_id) es el cinturón contra un doble cierre que el
3153:   -- gate de etapa no haya visto (el FOR UPDATE ya serializa el camino normal).
3154:   begin
3155:     insert into crm.cierres_externos (
3156:       lead_id, cooperativa, monto, moneda,
3157:       documento_tipo, documento, nombre_completo,
3158:       numero_transaccion, referencia_externa, vence_en, nota,
3159:       vendedor_id, creado_por, inversionista_id
3160:     ) values (
3161:       p_lead_id, p_cooperativa, p_monto, p_moneda,
3162:       p_documento_tipo, v_documento, v_nombre,
3163:       v_transaccion, v_referencia, p_vence_en, nullif(btrim(p_nota), ''),
3164:       v_lead.vendedor_id, v_uid, v_inv
3165:     )
3166:     returning id into v_cierre_id;
3167: 
3168:     -- La reclamación es PARTE del mismo insert: si el número ya se declaró
3169:     -- alguna vez —aunque su cierre se haya corregido después y el índice vivo
3170:     -- lo haya soltado— este insert choca y el cierre entero se deshace.
3171:     insert into crm.depositos_reclamados (numero_norm, cierre_id, reclamado_por)
3172:     values (upper(v_transaccion), v_cierre_id, v_uid);
3173:   exception when unique_violation then
3174:     -- El índice habla en idioma de constraint; el vendedor merece saber QUÉ
3175:     -- pasó. El UNIQUE del lead ya lo cazó el gate de etapa más arriba, así que
3176:     -- aquí el choque es el del depósito (vivo o histórico).
3177:     raise exception using
3178:       errcode = 'P0409',
3179:       message = 'Ese numero de operacion ya esta registrado',
3180:       hint    = 'Ese deposito ya se declaro antes, aqui o en la otra cooperativa. Si lo escribiste mal, corrigelo; si es otro cierre, usa su propio numero de operacion.';
3181:   end;
3182: 
3183:   -- El cierre del lead, IDÉNTICO al de convertir_lead salvo que perfil_id
3184:   -- queda NULL (no hay portal). El AFTER trg_leads_asignaciones cierra el
3185:   -- episodio con resultado='convertido' — por eso la conversión mensual cuenta
3186:   -- este cierre sin tocar su fórmula.
3187:   -- Inversión (colgada de la identidad) + titular principal (solo bandera).
3188:   -- F2.b (b4) [Codex v2 #17]: los HECHOS de inversión son de F4: solo con `inversiones_escritura`.
3189:   if v_flag and v_inv is not null and v_escribe_inversion then
3190:     perform private.inversion_vincular_fuente(v_inv,null,v_cierre_id,v_uid,true);
3191:   end if;
3192: 
3193:   -- El cierre del lead. inversionista_id viaja en el MISMO UPDATE bajo la válvula.
3194:   perform set_config('crm.op_privilegiada', 'on', true);
3195:   update crm.leads
3196:      set etapa = 'convertido',
3197:          convertido_en = now(),
3198:          inversionista_id = coalesce(v_inv, inversionista_id)
3199:    where id = p_lead_id;
3200:   perform set_config('crm.op_privilegiada', 'off', true);
3201: 
3202:   -- Reconocimiento de identidad (reemplaza al trigger 200000 para coop).
3203:   if v_flag and v_inv is not null then
3204:     insert into crm.inversionista_leads (inversionista_id, lead_id, rol)
3205:     select v_inv, p_lead_id, 'canonico'
3206:     where not exists (select 1 from crm.inversionista_leads il where il.lead_id = p_lead_id);
3207:     -- Responsable de relación = vendedor del cierre (si activo y sin tramo abierto).
3208:     if v_lead.vendedor_id is not null
3209:        and exists (select 1 from crm.equipo e where e.perfil_id = v_lead.vendedor_id and e.activo)
3210:        and not exists (select 1 from crm.inversionista_responsables ir where ir.inversionista_id = v_inv and ir.hasta is null) then
3211:       insert into crm.inversionista_responsables (inversionista_id, responsable_id, motivo)
3212:       values (v_inv, v_lead.vendedor_id, 'conversion');
3213:       update crm.inversionistas set responsable_relacion_id = v_lead.vendedor_id
3214:         where id = v_inv and responsable_relacion_id is null;
3215:     end if;
3216:     -- no_contactar del lead se centraliza en la persona.
3217:     if v_lead.no_contactar then
3218:       update crm.inversionistas set no_contactar = true, no_contactar_en = coalesce(no_contactar_en, pg_catalog.now())
3219:       where id = v_inv and no_contactar = false;
3220:     end if;
3221:   end if;
3222: 
3223:   insert into crm.actividades (
3224:     lead_id, tipo, detalle, metadata, creado_por
3225:   ) values (
3226:     p_lead_id,
3227:     'conversion',
3228:     'Convertido en ' || case p_cooperativa
3229:       when 'qorilazo' then 'COOPAC Qorilazo'
3230:       else 'COOPAC Prodelco'
3231:     end,
3232:     jsonb_build_object(
3233:       'cooperativa', p_cooperativa,
3234:       'monto', p_monto,
3235:       'moneda', p_moneda,
3236:       'cierre_externo_id', v_cierre_id
3237:     ),
3238:     v_uid
3239:   );
3240: 
3241:   v_res := jsonb_build_object(
3242:     'ok', true,
3243:     'lead_id', p_lead_id,
3244:     'cierre_id', v_cierre_id,
3245:     'cooperativa', p_cooperativa
3246:   );
3247:   if v_flag then
3248:     perform private.idem_guardar(v_clave, 'conversion_coop', v_hash, v_res, v_uid);
3249:   end if;
3250:   return v_res;
3251: end;
