3253: -- Adaptación acotada de public.crear_contrato(jsonb, jsonb); antes 1cd2730dc75c966cfbd9ea8d95d4d1ed
3254: CREATE OR REPLACE FUNCTION public.crear_contrato(p_contrato jsonb, p_cronograma jsonb)
3255:  RETURNS jsonb
3256:  LANGUAGE plpgsql
3257:  SECURITY DEFINER
3258:  SET search_path TO ''
3259: AS $function$
3260: declare
3261:   v_uid uuid := (select auth.uid());
3262:   v_es_gestor_cartera boolean := (select public.es_gestor_cartera());
3263:   v_rol_crm text := private.rol_crm(v_uid);
3264:   v_es_gerencia_crm boolean := coalesce(v_rol_crm = 'gerencia', false);
3265:   v_es_crm_catalogado boolean :=
3266:     coalesce(v_rol_crm in ('vendedor', 'supervisor'), false)
3267:     and nullif(current_setting('crm.producto_condicion_id', true), '') is not null;
3268:   v_cliente_id uuid;
3269:   v_numero text := nullif(btrim(p_contrato->>'numero_contrato'), '');
3270:   v_categoria text := p_contrato->>'categoria';
3271:   v_moneda text := upper(coalesce(nullif(p_contrato->>'moneda', ''), 'PEN'));
3272:   v_capital numeric;
3273:   v_anio integer := extract(year from now() at time zone 'America/Lima')::integer;
3274:   v_contrato_id uuid;
3275:   v_fecha_operacion date;
3276:   v_periodo date;
3277:   v_cuota jsonb;
3278:   v_asesor_id uuid;
3279:   v_asesor_rol text;
3280:   v_operacion_id uuid;
3281:   v_origen_id uuid;
3282:   v_origen public.contratos%rowtype;
3283:   v_capital_renovado numeric;
3284:   v_capital_adicional numeric;
3285:   v_primer_periodo date;
3286:   v_upgrade_elegible boolean;
3287:   v_analista_cierre uuid;
3288: begin
3289:   perform private.inversiones_escritura_bajo_candado(); -- F4: bandera antes de persona/cuenta/PDF
3290:   if p_contrato is null or jsonb_typeof(p_contrato) <> 'object' then
3291:     raise exception 'Faltan los datos del contrato' using errcode = '22023';
3292:   end if;
3293:   begin
3294:     v_cliente_id := (p_contrato->>'cliente_id')::uuid;
3295:     v_capital := (p_contrato->>'capital')::numeric;
3296:   exception when invalid_text_representation then
3297:     raise exception 'Cliente o capital inválido' using errcode = '22023';
3298:   end;
3299: 
3300:   -- Vincula autorización y escritura a la misma versión de la cartera. Una
3301:   -- reasignación concurrente espera este lock; si ganó antes, aquí ya se lee el
3302:   -- nuevo Analista y el anterior queda fuera del gate.
3303:   -- F2.b (E4) [D-1, OK de Miguel 05/09]: con la identidad unificada ENCENDIDA, crear un contrato RECONOCE
3304:   -- a la persona ANTES del FOR SHARE de abajo (jerarquía -> documento -> identidad -> perfil, reentrante).
3305:   -- Solo si el cliente existe activo (así un id inexistente sigue muriendo en el 42501 de siempre).
3306:   -- Sin documento válido o con documento de otra persona reconocida -> P0409 (contrato §4.3, fail-closed).
3307:   -- [auditor A1] la AUTORIDAD se pregunta antes de reconocer: un no autorizado sigue muriendo en el 42501 uniforme
3308:   -- de abajo (sin aprender nada del documento), con ON igual que con OFF.
3309:   if private.resolver_en_puertas_bajo_candado()
3310:      and (select private.puede_registrar_ventas())
3311:      and exists (select 1 from public.perfiles p where p.id = v_cliente_id and p.rol = 'cliente' and p.activo) then
3312:     perform private.asegurar_identidad_perfil(v_cliente_id, 'contrato');
3313:   end if;
3314:   select p.asesor_perfil_id into v_asesor_id
3315:   from public.perfiles p
3316:   where p.id = v_cliente_id and p.rol = 'cliente' and p.activo
3317:   for share;
3318:   if not found then
3319:     raise insufficient_privilege using
3320:       message = 'Cliente no encontrado o fuera de tu cartera';
3321:   end if;
3322: 
3323:   if not (select private.puede_registrar_ventas()) then
3324:     raise insufficient_privilege using
3325:       message = 'Cliente no encontrado o fuera de tu cartera';
3326:   end if;
3327: 
3328:   if v_capital < 100 or v_capital > 100000000 then
3329:     raise exception 'El capital debe estar entre 100 y 100,000,000';
3330:   end if;
3331:   if (p_contrato->>'tasa_anual')::numeric <= 0
3332:      or (p_contrato->>'tasa_anual')::numeric > 50 then
3333:     raise exception 'La tasa anual debe estar entre 0 y 50%%';
3334:   end if;
3335:   if v_categoria is null or v_categoria not in ('nuevo', 'renovacion', 'upgrade') then
3336:     raise exception 'Selecciona la categoría del contrato (Nuevo, Renovación o Upgrade)';
3337:   end if;
3338:   if v_moneda not in ('PEN', 'USD') then
3339:     raise exception 'Moneda inválida' using errcode = '22023';
3340:   end if;
3341: 
3342:   -- EL ANALISTA QUE CIERRA (decision 2 del plan P-055). Es de quien VENDIO, no
3343:   -- de quien tecleo: `creado_por` se conserva aparte y no se pisa.
3344:   begin
3345:     v_analista_cierre := nullif(btrim(coalesce(p_contrato->>'analista_cierre_id', '')), '')::uuid;
3346:   exception when invalid_text_representation then
3347:     raise exception 'El analista que cierra no es valido' using errcode = '22023';
3348:   end;
3349: 
3350:   if v_analista_cierre is not null then
3351:     -- Elegido a mano: tiene que poder tener ventas. SOLO ACTIVOS (decision de
3352:     -- Miguel, 29/08): una venta NUEVA es de alguien que esta trabajando; la
3353:     -- venta vieja de alguien que se fue entra por la reasignacion de gerencia
3354:     -- (que si acepta inactivos, con motivo y rastro). Y los roles OFF-ROSTER
3355:     -- (coordinador, directorio) no son organigrama comercial por diseno.
3356:     if not exists (
3357:       select 1 from crm.equipo e where e.perfil_id = v_analista_cierre
3358:         and e.activo
3359:         and e.rol_crm in ('vendedor','supervisor','gerencia')
3360:     ) then
3361:       raise exception 'El analista que cierra tiene que estar activo en el equipo comercial'
3362:         using errcode = '22023';
3363:     end if;
3364:   else
3365:     -- No vino. «Si no corresponde a nadie, lo pone a su nombre» (decision 2):
3366:     -- eso solo tiene sentido si quien registra PUEDE tener ventas. Si no puede
3367:     -- -una administrativa, por ejemplo-, tiene que elegir a quien corresponde.
3368:     if not exists (select 1 from crm.equipo e where e.perfil_id = v_uid and e.activo) then
3369:       raise exception 'Elige el analista de la venta'
3370:         using errcode = '22023',
3371:               hint = 'Quien registra no forma parte del equipo comercial, asi que la venta no puede quedar a su nombre.';
3372:     end if;
3373:     v_analista_cierre := v_uid;
3374:   end if;
3375: 
3376:   -- Las operaciones de cartera necesitan un dueño congelado. No se atribuye a
3377:   -- quien digitó: se atribuye al Analista de perfiles.asesor_perfil_id.
3378:   if v_categoria in ('renovacion', 'upgrade') then
3379:     select e.rol_crm into v_asesor_rol
3380:     from crm.equipo e
3381:     where e.perfil_id = v_asesor_id and e.activo
3382:     for share;
3383:     if v_asesor_id is null
3384:        or not found
3385:        or v_asesor_rol not in ('vendedor', 'supervisor') then
3386:       raise exception using
3387:         errcode = '22023',
3388:         message = 'Asigna un Analista activo al cliente antes de registrar la operación';
3389:     end if;
3390:   end if;
3391: 
3392:   if v_categoria = 'renovacion' then
3393:     begin
3394:       v_origen_id := (p_contrato->>'contrato_origen_id')::uuid;
3395:       v_capital_renovado := (p_contrato->>'capital_renovado')::numeric;
3396:       v_capital_adicional := coalesce((p_contrato->>'capital_adicional')::numeric, 0);
3397:     exception when invalid_text_representation then
3398:       raise exception 'Completa contrato anterior, capital renovado y adicional válidos'
3399:         using errcode = '22023';
3400:     end;
3401: 
3402:     select * into v_origen
3403:     from public.contratos c
3404:     where c.id = v_origen_id
3405:     for update;
3406:     if not found then
3407:       raise exception 'El contrato a renovar no existe' using errcode = 'P0002';
3408:     end if;
3409:     if v_origen.cliente_id is distinct from v_cliente_id then
3410:       raise exception 'El contrato anterior pertenece a otro cliente' using errcode = '22023';
3411:     end if;
3412:     if v_origen.estado not in ('activo', 'vencido') or v_origen.renovado_a_id is not null then
3413:       raise exception 'El contrato anterior ya fue cerrado o renovado' using errcode = 'P0409';
3414:     end if;
3415:     if v_origen.fecha_vencimiento > (now() at time zone 'America/Lima')::date then
3416:       raise exception 'La renovación solo se registra cuando el contrato llega a su fecha fin'
3417:         using errcode = '22023';
3418:     end if;
3419:     if v_origen.moneda is distinct from v_moneda then
3420:       raise exception 'La renovación debe conservar la moneda del contrato anterior'
3421:         using errcode = '22023';
3422:     end if;
3423:     if (p_contrato->>'fecha_inicio')::date < v_origen.fecha_vencimiento then
3424:       raise exception 'El contrato nuevo no puede iniciar antes del vencimiento anterior'
3425:         using errcode = '22023';
3426:     end if;
3427:     if v_capital_renovado <= 0 or v_capital_renovado > v_origen.capital then
3428:       raise exception 'El capital renovado debe ser mayor a cero y no superar el contrato anterior'
3429:         using errcode = '22023';
3430:     end if;
3431:     if v_capital_adicional < 0 then
3432:       raise exception 'El capital adicional no puede ser negativo' using errcode = '22023';
3433:     end if;
3434:     if v_capital is distinct from (v_capital_renovado + v_capital_adicional) then
3435:       raise exception 'El nuevo capital debe ser capital renovado + capital adicional'
3436:         using errcode = '22023';
3437:     end if;
3438:   end if;
3439: 
3440:   if v_numero is null then
3441:     v_numero := private.siguiente_numero_contrato(v_anio);
3442:   end if;
3443:   if exists (select 1 from public.contratos c where c.numero_contrato = v_numero) then
3444:     raise exception 'El N de contrato % ya existe', v_numero;
3445:   end if;
3446: 
3447:   insert into public.contratos (
3448:     cliente_id, numero_contrato, capital, moneda, tasa_anual, modalidad,
3449:     tipo_interes, fecha_inicio, fecha_vencimiento, notas_internas,
3450:     categoria, estado, creado_por, analista_cierre_id
3451:   ) values (
3452:     v_cliente_id, v_numero, v_capital, v_moneda,
3453:     (p_contrato->>'tasa_anual')::numeric, p_contrato->>'modalidad',
3454:     coalesce(nullif(p_contrato->>'tipo_interes', ''), 'simple'),
3455:     (p_contrato->>'fecha_inicio')::date,
3456:     (p_contrato->>'fecha_vencimiento')::date,
3457:     nullif(btrim(coalesce(p_contrato->>'notas_internas', '')), ''),
3458:     v_categoria, 'activo', v_uid, v_analista_cierre
3459:   ) returning id, fecha_cierre_comercial into v_contrato_id, v_fecha_operacion;
3460: 
3461:   if p_cronograma is null or jsonb_typeof(p_cronograma) <> 'array'
3462:      or jsonb_array_length(p_cronograma) = 0 then
3463:     raise exception 'El cronograma no puede estar vacío';
3464:   end if;
3465:   for v_cuota in select value from jsonb_array_elements(p_cronograma)
3466:   loop
3467:     insert into public.cronograma_pagos (
3468:       contrato_id, numero_cuota, fecha_programada, monto_programado, estado, tipo
3469:     ) values (
3470:       v_contrato_id, (v_cuota->>'numero_cuota')::integer,
3471:       (v_cuota->>'fecha_programada')::date,
3472:       (v_cuota->>'monto_programado')::numeric, 'pendiente',
3473:       coalesce(nullif(v_cuota->>'tipo', ''), 'cuota')
3474:     );
3475:   end loop;
3476:   if p_contrato ? 'titulares' then
3477:     perform public._sync_contrato_titulares(v_contrato_id, p_contrato->'titulares');
3478:   end if;
3479: 
3480:   if v_categoria in ('renovacion', 'upgrade') then
3481:     v_periodo := date_trunc('month', v_fecha_operacion)::date;
3482:     perform pg_catalog.pg_advisory_xact_lock(
3483:       pg_catalog.hashtext('crm.operaciones_cartera'),
3484:       pg_catalog.hashtext(v_cliente_id::text || '|' || v_periodo::text)
3485:     );
3486: 
3487:     if v_categoria = 'upgrade' then
3488:       select min(date_trunc('month', c.fecha_cierre_comercial)::date)
3489:         into v_primer_periodo
3490:       from public.contratos c
3491:       where c.cliente_id = v_cliente_id;
3492:       v_upgrade_elegible := v_periodo > v_primer_periodo;
3493:     else
3494:       v_upgrade_elegible := true;
3495:     end if;
3496: 
3497:     insert into crm.operaciones_cartera (
3498:       cliente_id, vendedor_id, tipo, contrato_origen_id, contrato_nuevo_id,
3499:       fecha_operacion, periodo, moneda, capital_renovado, capital_adicional,
3500:       elegible_conversion, desglose_completo, fuente, creado_por
3501:     ) values (
3502:       v_cliente_id, v_asesor_id, v_categoria, v_origen_id, v_contrato_id,
3503:       v_fecha_operacion, v_periodo, v_moneda,
3504:       case when v_categoria = 'renovacion' then v_capital_renovado end,
3505:       case when v_categoria = 'renovacion' then v_capital_adicional end,
3506:       v_upgrade_elegible, true, 'flujo_cartera', v_uid
3507:     ) returning id into v_operacion_id;
3508:   end if;
3509: 
3510:   if v_categoria = 'renovacion' then
3511:     update public.cronograma_pagos
3512:        set estado = 'trasladado'
3513:      where contrato_id = v_origen_id and estado in ('pendiente', 'vencido');
3514:     update public.contratos
3515:        set estado = 'renovado', renovado_a_id = v_contrato_id,
3516:            cerrado_en = now(), cerrado_por = v_uid
3517:      where id = v_origen_id;
3518:   end if;
3519: 
3520:   return jsonb_build_object(
3521:     'id', v_contrato_id,
3522:     'numero_contrato', v_numero,
3523:     'operacion_id', v_operacion_id,
3524:     'conversion_elegible', case
3525:       when v_categoria in ('renovacion', 'upgrade') then v_upgrade_elegible
3526:     end
3527:   );
3528: end;
3529: $function$;
3530: -- Adaptación acotada de crm.crear_contrato_con_cuenta(jsonb, jsonb, jsonb); antes 79d9d316203ce217456a7d00f834c584
3531: CREATE OR REPLACE FUNCTION crm.crear_contrato_con_cuenta(p_contrato jsonb, p_cronograma jsonb, p_cuenta jsonb)
3532:  RETURNS jsonb
3533:  LANGUAGE plpgsql
3534:  SECURITY DEFINER
3535:  SET search_path TO ''
3536: AS $function$
3537: declare
3538:   v_uid                  uuid := (select auth.uid());
3539:   v_cliente_id           uuid;
3540:   v_moneda               text;
3541:   v_tipo_seleccion       text;
3542:   v_cuenta_id            uuid;
3543:   v_cuenta_activa        crm.cuentas_bancarias%rowtype;
3544:   v_banco                text;
3545:   v_tipo_cuenta          text;
3546:   v_numero_cuenta        text;
3547:   v_cci                  text;
3548:   v_titular_distinto     boolean := false;
3549:   v_beneficiario_nombre  text;
3550:   v_beneficiario_dni     text;
3551:   v_cuenta_esperada      jsonb;
3552:   v_origen               text;
3553:   v_resultado            jsonb;
3554:   v_contrato_id          uuid;
3555: begin
3556:   perform private.inversiones_escritura_bajo_candado(); -- F4: bandera antes de persona/cuenta/PDF
3557:   if p_contrato is null or jsonb_typeof(p_contrato) <> 'object' then
3558:     raise exception using errcode = '22023', message = 'Faltan los datos del contrato';
3559:   end if;
3560:   if p_cuenta is null or jsonb_typeof(p_cuenta) <> 'object' then
3561:     raise exception using errcode = '22023', message = 'Selecciona la cuenta para el pago de intereses';
3562:   end if;
3563: 
3564:   begin
3565:     v_cliente_id := (p_contrato->>'cliente_id')::uuid;
3566:   exception when invalid_text_representation then
3567:     raise exception using errcode = '22023', message = 'Cliente invalido';
3568:   end;
3569:   v_moneda := upper(btrim(coalesce(p_contrato->>'moneda', '')));
3570:   if v_moneda not in ('PEN', 'USD') then
3571:     raise exception using errcode = '22023', message = 'Moneda del contrato invalida';
3572:   end if;
3573:   if not (select private.puede_registrar_ventas()) then
3574:     raise exception using errcode = '42501', message = 'Cliente no encontrado o fuera de tu cartera';
3575:   end if;
3576: 
3577:   -- F2.b (E4) [Codex B-2]: la prepuerta de reconocimiento (jerarquía -> documento -> identidad -> perfil) va ANTES
3578:   -- de los locks de cuenta/perfil de este wrapper, con el mismo orden que public.crear_contrato (reentrante allí).
3579:   -- Después del 42501 de arriba: la precedencia para un no autorizado no cambia.
3580:   if private.resolver_en_puertas_bajo_candado()
3581:      and exists (select 1 from public.perfiles p where p.id = v_cliente_id and p.rol = 'cliente' and p.activo) then
3582:     perform private.asegurar_identidad_perfil(v_cliente_id, 'contrato');
3583:   end if;
3584:   v_tipo_seleccion := lower(btrim(coalesce(p_cuenta->>'tipo', '')));
3585: 
3586:   if v_tipo_seleccion = 'existente' then
3587:     begin
3588:       v_cuenta_id := (p_cuenta->>'cuenta_id')::uuid;
3589:     exception when invalid_text_representation then
3590:       raise exception using errcode = '22023', message = 'Cuenta bancaria invalida';
3591:     end;
3592: 
3593:     select cb.* into v_cuenta_activa
3594:     from crm.cuentas_bancarias cb
3595:     where cb.id = v_cuenta_id
3596:       and cb.cliente_id = v_cliente_id
3597:       and cb.moneda = v_moneda
3598:       and cb.activa = true
3599:     for share;
3600:     if not found then
3601:       raise exception using
3602:         errcode = '22023',
3603:         message = 'La cuenta bancaria no esta disponible para este cliente y moneda';
3604:     end if;
3605: 
3606:   elsif v_tipo_seleccion in ('perfil', 'nueva') then
3607:     if v_tipo_seleccion = 'perfil' then
3608:       select
3609:         btrim(case when v_moneda = 'USD' then p.banco_usd else p.banco end),
3610:         lower(btrim(case when v_moneda = 'USD' then p.tipo_cuenta_usd else p.tipo_cuenta end)),
3611:         upper(btrim(case when v_moneda = 'USD' then p.numero_cuenta_usd else p.numero_cuenta end)),
3612:         btrim(case when v_moneda = 'USD' then p.cci_usd else p.cci end),
3613:         case when v_moneda = 'USD' then p.titular_distinto_usd else p.titular_distinto end,
3614:         case when v_moneda = 'USD' then p.beneficiario_nombre_usd else p.beneficiario_nombre end,
3615:         case when v_moneda = 'USD' then p.beneficiario_dni_usd else p.beneficiario_dni end
3616:       into v_banco, v_tipo_cuenta, v_numero_cuenta, v_cci,
3617:            v_titular_distinto, v_beneficiario_nombre, v_beneficiario_dni
3618:       from public.perfiles p
3619:       where p.id = v_cliente_id
3620:       -- La fotografia del perfil debe seguir siendo cierta hasta que termine
3621:       -- el alta. Sin este lock, un UPDATE concurrente podia confirmar despues
3622:       -- del SELECT y antes de crear el vinculo contractual.
3623:       for share;
3624:       v_origen := 'perfil';
3625:     else
3626:       v_banco := btrim(coalesce(p_cuenta->>'banco', ''));
3627:       v_tipo_cuenta := lower(btrim(coalesce(p_cuenta->>'tipo_cuenta', '')));
3628:       v_numero_cuenta := upper(btrim(coalesce(p_cuenta->>'numero_cuenta', '')));
3629:       v_cci := btrim(coalesce(p_cuenta->>'cci', ''));
3630:       begin
3631:         v_titular_distinto := coalesce((p_cuenta->>'titular_distinto')::boolean, false);
3632:       exception when invalid_text_representation then
3633:         raise exception using errcode = '22023', message = 'Indicador de beneficiario invalido';
3634:       end;
3635:       v_beneficiario_nombre := p_cuenta->>'beneficiario_nombre';
3636:       v_beneficiario_dni := p_cuenta->>'beneficiario_dni';
3637:       v_origen := 'contrato';
3638:     end if;
3639: 
3640:     v_banco := btrim(coalesce(v_banco, ''));
3641:     v_tipo_cuenta := lower(btrim(coalesce(v_tipo_cuenta, '')));
3642:     v_numero_cuenta := upper(btrim(coalesce(v_numero_cuenta, '')));
3643:     v_cci := btrim(coalesce(v_cci, ''));
3644:     if v_titular_distinto then
3645:       v_beneficiario_nombre := upper(regexp_replace(btrim(coalesce(v_beneficiario_nombre, '')), '\s+', ' ', 'g'));
3646:       v_beneficiario_dni := btrim(coalesce(v_beneficiario_dni, ''));
3647:     else
3648:       v_beneficiario_nombre := null;
3649:       v_beneficiario_dni := null;
3650:     end if;
3651: 
3652:     if v_tipo_seleccion = 'perfil' then
3653:       v_cuenta_esperada := jsonb_build_object(
3654:         'banco', v_banco,
3655:         'tipo_cuenta', v_tipo_cuenta,
3656:         'numero_cuenta', v_numero_cuenta,
3657:         'cci', v_cci,
3658:         'titular_distinto', v_titular_distinto,
3659:         'beneficiario_nombre', v_beneficiario_nombre,
3660:         'beneficiario_dni', v_beneficiario_dni
3661:       );
3662:       if jsonb_typeof(p_cuenta->'cuenta_esperada') is distinct from 'object'
3663:          or (p_cuenta->'cuenta_esperada') is distinct from v_cuenta_esperada then
3664:         raise exception using
3665:           errcode = 'P0001',
3666:           message = 'La cuenta actual del cliente cambio. Recarga las cuentas y vuelve a seleccionarla';
3667:       end if;
3668:     end if;
3669: 
3670:     if length(v_banco) not between 1 and 100 then
3671:       raise exception using errcode = '22023', message = 'Selecciona el banco de la cuenta';
3672:     end if;
3673:     if v_tipo_cuenta not in ('ahorros', 'corriente') then
3674:       raise exception using errcode = '22023', message = 'Selecciona un tipo de cuenta valido';
3675:     end if;
3676:     if v_numero_cuenta !~ '^[A-Za-z0-9-]{1,30}$' then
3677:       raise exception using errcode = '22023', message = 'El numero de cuenta solo puede contener letras, numeros y guiones';
3678:     end if;
3679:     if v_cci !~ '^[0-9]{20}$' then
3680:       raise exception using errcode = '22023', message = 'El CCI debe tener exactamente 20 digitos';
3681:     end if;
3682:     if v_titular_distinto and (
3683:       length(v_beneficiario_nombre) not between 1 and 200
3684:       or v_beneficiario_dni !~ '^[0-9]{8,12}$'
3685:     ) then
3686:       raise exception using errcode = '22023', message = 'Completa correctamente los datos del beneficiario';
3687:     end if;
3688: 
3689:     -- Serializa dos altas simultaneas del mismo CCI sin bloquear otras cuentas.
3690:     perform pg_catalog.pg_advisory_xact_lock(
3691:       pg_catalog.hashtextextended(v_cliente_id::text || '|' || v_moneda || '|' || v_cci, 0)
3692:     );
3693: 
3694:     select cb.* into v_cuenta_activa
3695:     from crm.cuentas_bancarias cb
3696:     where cb.cliente_id = v_cliente_id
3697:       and cb.moneda = v_moneda
3698:       and cb.cci = v_cci
3699:       and cb.activa = true
3700:     for update;
3701: 
3702:     if found
3703:        and lower(v_cuenta_activa.banco) = lower(v_banco)
3704:        and v_cuenta_activa.tipo_cuenta = v_tipo_cuenta
3705:        and v_cuenta_activa.numero_cuenta = v_numero_cuenta
3706:        and v_cuenta_activa.titular_distinto = v_titular_distinto
3707:        and v_cuenta_activa.beneficiario_nombre is not distinct from v_beneficiario_nombre
3708:        and v_cuenta_activa.beneficiario_dni is not distinct from v_beneficiario_dni then
3709:       v_cuenta_id := v_cuenta_activa.id;
3710:     else
3711:       if found then
3712:         update crm.cuentas_bancarias
3713:            set activa = false,
3714:                desactivada_por = v_uid,
3715:                desactivada_en = now()
3716:          where id = v_cuenta_activa.id;
3717:       end if;
3718: 
3719:       insert into crm.cuentas_bancarias (
3720:         cliente_id, moneda, banco, tipo_cuenta, numero_cuenta, cci,
3721:         titular_distinto, beneficiario_nombre, beneficiario_dni,
3722:         activa, origen, creado_por
3723:       ) values (
3724:         v_cliente_id, v_moneda, v_banco, v_tipo_cuenta, v_numero_cuenta, v_cci,
3725:         v_titular_distinto, v_beneficiario_nombre, v_beneficiario_dni,
3726:         true, v_origen, v_uid
3727:       )
3728:       returning id into v_cuenta_id;
3729:     end if;
3730:   else
3731:     raise exception using
3732:       errcode = '22023',
3733:       message = 'Selecciona una cuenta existente o registra una cuenta nueva';
3734:   end if;
3735: 
3736:   -- public.crear_contrato mantiene su validacion de rol/cartera, numeracion,
3737:   -- contrato, cronograma y co-titulares. La llamada anidada participa de ESTA
3738:   -- transaccion: si el enlace bancario falla, todo (incluida una cuenta nueva)
3739:   -- se revierte.
3740:   v_resultado := public.crear_contrato(p_contrato, p_cronograma);
3741:   begin
3742:     v_contrato_id := (v_resultado->>'id')::uuid;
3743:   exception when invalid_text_representation then
3744:     raise exception using errcode = 'P0001', message = 'El contrato no devolvio un identificador valido';
3745:   end;
3746:   if v_contrato_id is null then
3747:     raise exception using errcode = 'P0001', message = 'El contrato no devolvio un identificador';
3748:   end if;
3749: 
3750:   insert into crm.contrato_cuentas_pago (
3751:     contrato_id, cuenta_bancaria_id, creado_por
3752:   ) values (
3753:     v_contrato_id, v_cuenta_id, v_uid
3754:   );
3755: 
3756:   return v_resultado || jsonb_build_object('cuenta_bancaria_id', v_cuenta_id);
3757: end;
