3759: -- Adaptación acotada de crm.crear_contrato_con_cuenta_pdf_v2(jsonb, jsonb, jsonb); antes 9833ed526e733dc8af6ca78e5c85c7ca
3760: CREATE OR REPLACE FUNCTION crm.crear_contrato_con_cuenta_pdf_v2(p_contrato jsonb, p_cronograma jsonb, p_cuenta jsonb)
3761:  RETURNS jsonb
3762:  LANGUAGE plpgsql
3763:  SECURITY DEFINER
3764:  SET search_path TO ''
3765: AS $function$
3766: declare
3767:   v_actor_id uuid := (select auth.uid());
3768:   v_contrato jsonb := p_contrato;
3769:   v_resultado jsonb;
3770:   v_contrato_id uuid;
3771:   v_pdf jsonb;
3772:   v_clave_texto text := nullif(btrim(coalesce(p_contrato->>'clave_idempotencia', '')), '');
3773:   v_clave uuid;
3774:   v_huella text;
3775:   v_huella_previa text;
3776: begin
3777:   perform private.inversiones_escritura_bajo_candado(); -- F4: bandera antes de persona/cuenta/PDF
3778:   if v_actor_id is null then
3779:     raise insufficient_privilege using message = 'Sesión no válida';
3780:   end if;
3781: 
3782:   -- IDEMPOTENCIA DEL ALTA (05/09/2026). El front manda una clave (uuid) por intento de
3783:   -- formulario, la MISMA en cada reintento. Si este actor ya registró un alta con esa
3784:   -- clave, se devuelve el MISMO contrato en vez de crear otro. Viaja DENTRO de
3785:   -- p_contrato para no cambiar la firma del RPC; es del transporte, no del contrato:
3786:   -- se quita antes de bajar a la cadena, que recibe EXACTAMENTE lo que recibía.
3787:   -- Sin clave, nada cambia (los clientes que no la mandan siguen igual).
3788:   if v_clave_texto is not null then
3789:     begin
3790:       v_clave := v_clave_texto::uuid;
3791:     exception when invalid_text_representation then
3792:       raise exception 'La clave de idempotencia del alta no es válida'
3793:         using errcode = '22023';
3794:     end;
3795:     -- Dos envíos simultáneos con la misma clave del mismo actor (doble clic, dos
3796:     -- pestañas) se serializan aquí: el segundo espera y lee el alta del primero.
3797:     perform pg_catalog.pg_advisory_xact_lock(
3798:       pg_catalog.hashtextextended(
3799:         'crm.alta_contrato_idempotente|' || v_actor_id::text || '|' || v_clave::text, 0
3800:       )
3801:     );
3802:     -- La huella de LO QUE SE PIDE (sin la clave): la misma clave solo vale para la
3803:     -- misma solicitud. jsonb::text es canónico (claves ordenadas), así que dos
3804:     -- envíos iguales dan la misma huella.
3805:     v_huella := md5(
3806:       (p_contrato - 'clave_idempotencia')::text || '|'
3807:       || coalesce(p_cronograma::text, '') || '|'
3808:       || coalesce(p_cuenta::text, '')
3809:     );
3810:     select a.respuesta, a.contrato_id, a.huella
3811:       into v_resultado, v_contrato_id, v_huella_previa
3812:     from private.contrato_altas_idempotentes a
3813:     where a.actor_id = v_actor_id and a.clave = v_clave;
3814:     if found then
3815:       -- El replay pasa por la MISMA autorización que el alta (Codex 05/09): una
3816:       -- membresía revocada o un contrato fuera de cartera no recuperan nada.
3817:       if not (select private.puede_registrar_ventas()) then
3818:         raise insufficient_privilege using
3819:           message = 'Cliente no encontrado o fuera de tu cartera';
3820:       end if;
3821:       -- Lápida: el contrato de este intento fue eliminado después (FK SET NULL).
3822:       -- Un reintento tardío NO recrea lo que Gerencia borró a propósito.
3823:       if v_contrato_id is null then
3824:         raise exception 'El contrato de este intento fue eliminado después; vuelve a registrar el alta'
3825:           using errcode = 'P0409', hint = 'ALTA_ELIMINADA';
3826:       end if;
3827:       -- Misma fila que bloquea la puerta de eliminación: replay y borrado se
3828:       -- serializan. Si el contrato desaparece mientras esperamos, es lápida.
3829:       begin
3830:         perform private.bloquear_fila_contrato_pdf(v_contrato_id);
3831:       exception when sqlstate 'P0002' then
3832:         raise exception 'El contrato de este intento fue eliminado después; vuelve a registrar el alta'
3833:           using errcode = 'P0409', hint = 'ALTA_ELIMINADA';
3834:       end;
3835:       -- Eliminación PREPARADA y aún no finalizada (Gerencia pulsó «Eliminar» y la edge todavía
3836:       -- no borró): no se devuelve como «alta recuperada» un contrato que está a punto de
3837:       -- desaparecer. La misma pregunta y el mismo 55000 que hace el alta
3838:       -- (private.crear_job_contrato_pdf_base); la fila ya está bloqueada, así que la
3839:       -- respuesta es estable hasta que esta transacción termine.
3840:       if private.contrato_en_eliminacion(v_contrato_id) then
3841:         raise exception 'El contrato está en proceso de eliminación'
3842:           using errcode = '55000';
3843:       end if;
3844:       if not private.puede_leer_contrato_pdf_como(v_contrato_id, v_actor_id) then
3845:         raise insufficient_privilege using
3846:           message = 'Contrato no encontrado o fuera de tu cartera';
3847:       end if;
3848:       -- Misma clave pero OTROS datos (el analista editó el formulario tras un
3849:       -- intento que SÍ creó el contrato): no se devuelve el viejo como si fuera
3850:       -- el nuevo ni se crea otro. Se le dice la verdad, con el número.
3851:       if v_huella_previa is distinct from v_huella then
3852:         raise exception 'Este intento ya creó el contrato % con otros datos; no se creó otro. Revísalo antes de registrar uno nuevo',
3853:           coalesce(v_resultado->>'numero_contrato', v_contrato_id::text)
3854:           using errcode = 'P0409',
3855:                 hint = 'ALTA_YA_CREADA_CON_OTROS_DATOS',
3856:                 detail = jsonb_build_object(
3857:                   'contrato_id', v_contrato_id,
3858:                   'numero_contrato', v_resultado->>'numero_contrato'
3859:                 )::text;
3860:       end if;
3861:       -- El MISMO contrato, con el estado documental de HOY (la reserva pudo avanzar
3862:       -- desde el primer intento) y la marca de que es un alta ya registrada.
3863:       return (v_resultado - 'pdf')
3864:         || jsonb_build_object('pdf', private.contrato_pdf_estado_base(v_contrato_id))
3865:         || jsonb_build_object('idempotente', true);
3866:     end if;
3867:     v_contrato := p_contrato - 'clave_idempotencia';
3868:   end if;
3869: 
3870:   -- El contrato, cronograma, cuenta, vínculo, snapshot y job se confirman o
3871:   -- revierten juntos porque toda la cadena corre en esta transacción RPC.
3872:   v_resultado := crm.crear_contrato_con_cuenta(
3873:     v_contrato,
3874:     p_cronograma,
3875:     p_cuenta
3876:   );
3877:   begin
3878:     v_contrato_id := (v_resultado->>'id')::uuid;
3879:   exception when invalid_text_representation then
3880:     raise exception 'El alta no devolvió un contrato válido'
3881:       using errcode = 'P0001';
3882:   end;
3883:   if v_contrato_id is null then
3884:     raise exception 'El alta no devolvió un contrato válido'
3885:       using errcode = 'P0001';
3886:   end if;
3887: 
3888:   v_pdf := private.crear_job_contrato_pdf_base(v_contrato_id, v_actor_id);
3889:   if private.inversiones_escritura_bajo_candado() then
3890:     perform private.inversion_cotitulares_vincular(
3891:       (select id from crm.inversiones where contrato_id=v_contrato_id),'alta');
3892:   end if;
3893:   v_resultado := v_resultado || jsonb_build_object('pdf', v_pdf);
3894:   if v_clave is not null then
3895:     -- Misma transacción que el alta: o quedan los dos, o ninguno.
3896:     insert into private.contrato_altas_idempotentes (actor_id, clave, contrato_id, huella, respuesta)
3897:     values (v_actor_id, v_clave, v_contrato_id, v_huella, v_resultado);
3898:   end if;
3899:   return v_resultado;
3900: end;
3901: $function$;
3902: create or replace function private.f4_sincronizar_cierre()
3903: returns trigger language plpgsql security definer set search_path='' as $$
3904: declare v_inversion uuid;
3905: begin
3906:   update crm.inversiones i set empresa_id=e.id,
3907:     estado=case when new.anulado_en is null then 'vigente' else 'anulada' end
3908:   from crm.empresas e where i.cierre_externo_id=new.id and e.clave=new.cooperativa
3909:   returning i.id into v_inversion;
3910:   if v_inversion is not null and not new.es_cierre_inicial then
3911:     insert into crm.inversion_eventos(inversion_id,tipo,motivo,creado_por)
3912:     values(v_inversion,
3913:       case when old.anulado_en is null and new.anulado_en is not null then 'anulacion' else 'correccion' end,
3914:       case when old.anulado_en is null and new.anulado_en is not null then new.motivo_anulacion else 'Corrección de cierre externo' end,
3915:       (select auth.uid()));
3916:   end if;
3917:   return new;
3918: end;
3919: $$;
