3967: -- La inversión conserva su solicitud mientras Auth avanza en el servicio externo.
3968: -- Reutiliza el claim global de F3, su marca de servidor, token, versión y lease.
3969: -- Ningún paso recibe documento, asesor, claim ni perfil elegidos por el cliente.
3970: create or replace function crm.acceso_inversion_fn(p_solicitud uuid,p_paso text,p_payload jsonb default '{}'::jsonb)
3971: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
3972: declare
3973:   v_persona uuid;
3974:   v_origen uuid;
3975:   v_ctx jsonb;
3976:   v_s crm.inversion_solicitudes%rowtype;
3977:   v_datos jsonb;
3978:   v_auth_ctx jsonb;
3979:   v_hash_payload jsonb;
3980:   v_saga crm.multiempresa_idempotencia%rowtype;
3981:   v_r jsonb;
3982:   v_p public.perfiles%rowtype;
3983:   v_auth uuid;
3984:   v_version integer;
3985:   v_token text;
3986:   v_otras uuid[];
3987: begin
3988:   if p_solicitud is null or p_paso is null or p_paso not in ('reclamar','registrar_auth','crear_perfil','enlazar')
3989:      or jsonb_typeof(p_payload) is distinct from 'object' then
3990:     raise exception 'Solicitud o paso de acceso Avance inválido' using errcode='22023';
3991:   end if;
3992:   if exists(select 1 from jsonb_object_keys(p_payload) k where
3993:     k<>'token' and not (p_paso<>'reclamar' and k='version')
3994:     and not (p_paso='registrar_auth' and k='auth_user_id')) then
3995:     raise exception 'El paso de acceso contiene campos no admitidos' using errcode='22023';
3996:   end if;
3997:   v_token:=p_payload->>'token';
3998:   if v_token is not null and v_token !~ '^[a-f0-9]{48}$' then
3999:     raise exception 'Token de recuperación inválido' using errcode='22023';
4000:   end if;
4001:   select inversionista_id into v_persona from crm.inversion_solicitudes where id=p_solicitud;
4002:   v_origen:=v_persona;
4003:   v_ctx:=private.inversion_persona_autorizada(v_persona);
4004:   v_persona:=(v_ctx->>'inversionista_id')::uuid;
4005:   select * into v_s from crm.inversion_solicitudes where id=p_solicitud for update;
4006:   if not found or v_s.inversionista_id is distinct from v_origen then
4007:     raise exception 'La solicitud cambió; vuelve a cargarla' using errcode='40001';
4008:   end if;
4009:   if v_s.estado<>'confirmada' then
4010:     v_ctx:=private.inversion_persona_contexto(v_persona);
4011:   end if;
4012:   if not exists(select 1 from crm.empresas e where e.id=v_s.empresa_id and e.clave='avance' and e.activa)
4013:      or v_s.estado='cancelada' then
4014:     raise exception 'Esta solicitud no permite completar acceso Avance' using errcode='P0409';
4015:   end if;
4016:   if v_s.estado='preparada' and v_s.responsable_esperado_id is distinct from (v_ctx->>'responsable_id')::uuid then
4017:     raise exception 'El responsable cambió; corresponde revisar esta solicitud antes de continuar' using errcode='P0409';
4018:   end if;
4019: 
4020:   -- Un claim terminal conserva su clave de origen después de una fusión.
4021:   -- Los contextos anteriores a esta ampliación usaban la persona de la solicitud.
4022:   select * into v_saga from crm.multiempresa_idempotencia where clave='auth_persona:'||
4023:     case when v_s.auth_claim_id is null then v_persona::text
4024:       else coalesce(v_s.auth_contexto->>'inversionista_id',v_origen::text) end;
4025:   if v_s.auth_claim_id is not null and
4026:     (v_saga.clave is null or v_saga.resultado->>'claim_id' is distinct from v_s.auth_claim_id::text) then
4027:     raise exception 'El proceso de acceso original requiere conciliación' using errcode='P0409';
4028:   end if;
4029:   -- Un enlace concluido se devuelve aunque se perdiera su respuesta. No reinicia
4030:   -- Auth ni reescribe el perfil, su clave o su responsable.
4031:   if v_ctx->>'perfil_id' is not null and
4032:      (v_saga.clave is null or v_saga.resultado->>'estado'='enlazado') then
4033:     if v_saga.clave is not null and v_saga.resultado->>'perfil_id' is distinct from v_ctx->>'perfil_id' then
4034:       raise exception 'El acceso y la identidad requieren conciliación' using errcode='P0409';
4035:     end if;
4036:     return jsonb_build_object('estado','enlazado','perfil_id',v_ctx->>'perfil_id',
4037:       'inversionista_id',v_persona,'solicitud_id',v_s.id,'reanudar',true);
4038:   end if;
4039:   if v_s.estado='confirmada' then
4040:     raise exception 'El acceso de la inversión confirmada requiere conciliación' using errcode='P0409';
4041:   end if;
4042:   v_datos:=private.inversion_datos_portal(v_s.datos->'alta_portal');
4043:   v_auth_ctx:=coalesce(v_s.auth_contexto,jsonb_build_object('documento_tipo',v_ctx->>'documento_tipo',
4044:     'documento',v_ctx->>'documento','responsable_id',v_ctx->>'responsable_id','inversionista_id',v_persona));
4045:   if v_auth_ctx->>'documento_tipo' is distinct from v_ctx->>'documento_tipo'
4046:      or v_auth_ctx->>'documento' is distinct from v_ctx->>'documento' then
4047:     raise exception 'El documento cambió durante el alta; corresponde revisar el acceso pendiente' using errcode='P0409';
4048:   end if;
4049:   -- Misma proyección que alta_cliente_identidad_fn; los bancos pertenecen a la
4050:   -- cuenta contractual de esta inversión. El responsable inicial fija la huella.
4051:   v_hash_payload:=jsonb_build_object('v',1,'inv',v_persona,'correo',v_datos->>'correo',
4052:     'nombre',v_datos->>'nombre_completo','apellidos',coalesce(v_datos->>'apellidos',''),
4053:     'nombres',coalesce(v_datos->>'nombres',''),'telefono',coalesce(v_datos->>'telefono',''),
4054:     'domicilio',v_datos->'domicilio','bancarios','null'::jsonb,'asesor',v_auth_ctx->>'responsable_id');
4055: 
4056:   if p_paso='reclamar' then
4057:     -- Una segunda solicitud no sustituye un alta pendiente de esta persona.
4058:     -- Incluso "reclamado" puede tener Auth creado con respuesta perdida.
4059:     if v_saga.clave is not null and v_saga.resultado->>'estado'<>'enlazado' then
4060:       if exists(select 1 from crm.inversion_solicitudes s where s.id<>v_s.id
4061:         and s.auth_claim_id=(v_saga.resultado->>'claim_id')::uuid) then
4062:         raise exception 'Completa el acceso pendiente desde su solicitud original' using errcode='P0409';
4063:       end if;
4064:       if v_saga.hash_payload is distinct from private.idem_hash(v_hash_payload) then
4065:         raise exception 'La persona tiene otro alta pendiente; recupera ese proceso con sus datos originales' using errcode='P0409';
4066:       end if;
4067:     end if;
4068:     if v_saga.clave is null then
4069:       select array_agg(p.id order by p.id) into v_otras from public.perfiles p
4070:       where p.rol='cliente' and p.tipo_documento=v_ctx->>'documento_tipo'
4071:         and upper(regexp_replace(coalesce(p.dni,''),'[^A-Za-z0-9]','','g'))=v_ctx->>'documento';
4072:       if coalesce(cardinality(v_otras),0)>1 then
4073:         raise exception 'Hay varios perfiles con ese documento; requiere conciliación' using errcode='P0409';
4074:       elsif cardinality(v_otras)=1 then
