4086:        or v_r->>'perfil_id' is distinct from v_ctx->>'perfil_id') then
4087:       raise exception 'El perfil del acceso requiere conciliación con esta persona' using errcode='P0409';
4088:     end if;
4089:     if v_s.auth_claim_id is not null and v_s.auth_claim_id is distinct from (v_r->>'claim_id')::uuid then
4090:       raise exception 'El proceso de acceso cambió; requiere revisión' using errcode='P0409';
4091:     end if;
4092:     update crm.inversion_solicitudes set auth_claim_id=(v_r->>'claim_id')::uuid,
4093:       auth_contexto=v_auth_ctx,actualizado_en=statement_timestamp() where id=v_s.id;
4094:     return v_r||jsonb_build_object('solicitud_id',v_s.id,'datos_portal',v_datos,
4095:       'documento_tipo',v_auth_ctx->>'documento_tipo','documento',v_auth_ctx->>'documento');
4096:   end if;
4097: 
4098:   if v_s.auth_claim_id is null or v_saga.clave is null
4099:      or v_saga.resultado->>'claim_id' is distinct from v_s.auth_claim_id::text then
4100:     raise exception 'Primero reclama el acceso desde esta solicitud' using errcode='P0409';
4101:   end if;
4102:   -- El perfil y el avance de estado se confirman juntos. Una versión antigua
4103:   -- no puede dejar un perfil insertado ni enlazarlo por fuera de su claim.
4104:   select * into v_saga from crm.multiempresa_idempotencia where clave=v_saga.clave for update;
4105:   if v_token is null or v_saga.resultado->>'token_hash' is distinct from private.saga_token_hash(v_token) then
4106:     raise exception 'Token de recuperación inválido' using errcode='42501';
4107:   end if;
4108:   begin v_version:=(p_payload->>'version')::integer;
4109:   exception when invalid_text_representation or numeric_value_out_of_range then
4110:     raise exception 'Versión del acceso inválida' using errcode='22023';
4111:   end;
4112:   if v_version is null or v_saga.version is distinct from v_version then
4113:     raise exception 'El acceso cambió; vuelve a reclamar con tu token' using errcode='40001';
4114:   end if;
4115:   if p_paso='registrar_auth' then
4116:     begin v_auth:=(p_payload->>'auth_user_id')::uuid;
4117:     exception when invalid_text_representation then
4118:       raise exception 'Identificador de acceso inválido' using errcode='22023';
4119:     end;
4120:   else
4121:     v_auth:=(v_saga.resultado->>'auth_user_id')::uuid;
4122:   end if;
4123:   if not exists(select 1 from auth.users u where u.id=v_auth
4124:     and u.raw_app_meta_data->>'claim_id'=v_s.auth_claim_id::text
4125:     and lower(u.email)=v_datos->>'correo') then
4126:     raise exception 'El acceso no pertenece a esta solicitud o a su correo' using errcode='P0409';
4127:   end if;
4128:   if p_paso='registrar_auth' then
4129:     return private.saga_auth_avanzar(v_s.auth_claim_id,v_token,'auth_creado',v_auth,null,v_version);
4130:   end if;
4131:   if v_saga.resultado->>'estado' not in ('auth_creado','perfil_creado') then
4132:     raise exception 'El estado del acceso no permite este paso' using errcode='P0409';
4133:   end if;
4134:   select * into v_p from public.perfiles where id=v_auth for update;
4135:   if not found and p_paso='crear_perfil' then
4136:     insert into public.perfiles(id,rol,activo,nombre_completo,apellidos,nombres,tipo_documento,dni,
4137:       correo,telefono,domicilio,asesor_perfil_id,creado_por,debe_cambiar_password)
4138:     values(v_auth,'cliente',true,v_datos->>'nombre_completo',v_datos->>'apellidos',v_datos->>'nombres',
4139:       v_auth_ctx->>'documento_tipo',v_auth_ctx->>'documento',v_datos->>'correo',v_datos->>'telefono',
4140:       v_datos->>'domicilio',(v_ctx->>'responsable_id')::uuid,(select auth.uid()),true)
4141:     returning * into v_p;
4142:   end if;
4143:   if v_p.id is null or v_p.rol<>'cliente' or v_p.activo is not true
4144:      or v_p.tipo_documento is distinct from v_auth_ctx->>'documento_tipo'
4145:      or v_p.dni is distinct from v_auth_ctx->>'documento'
4146:      or lower(v_p.correo) is distinct from v_datos->>'correo'
4147:      or v_p.asesor_perfil_id is distinct from (v_ctx->>'responsable_id')::uuid then
4148:     raise exception 'El perfil pendiente requiere conciliación con esta persona y su responsable' using errcode='P0409';
4149:   end if;
4150:   if p_paso='crear_perfil' then
4151:     return private.saga_auth_avanzar(v_s.auth_claim_id,v_token,'perfil_creado',null,v_auth,v_version);
4152:   end if;
4153:   v_r:=private.asegurar_identidad_perfil(v_auth,'f4_acceso_portal');
4154:   if private.inversionista_canonica((v_r->>'inversionista_id')::uuid) is distinct from v_persona then
4155:     raise exception 'El perfil no corresponde a la persona de la inversión' using errcode='P0409';
4156:   end if;
4157:   return private.saga_auth_avanzar(v_s.auth_claim_id,v_token,'enlazado',null,v_auth,v_version)
4158:     ||jsonb_build_object('solicitud_id',v_s.id);
4159: end;
4160: $$;
