4164: -- Prueba acotada para el trigger de perfiles: solo permite alinear el asesor
4165: -- con la persona durante la misma sentencia que registró una revisión F4.
4166: -- Es INVOKER. El trigger la consulta únicamente desde el escritor postgres;
4167: -- un UPDATE directo authenticated no puede abrir esta excepción con un GUC.
4168: create or replace function private.f4_alineacion_perfil_permitida(p_perfil uuid,p_responsable uuid)
4169: returns boolean language sql stable security invoker set search_path='' as $$
4170:   select exists(
4171:     select 1 from crm.inversion_solicitudes s
4172:     join crm.inversionistas i on i.id=private.inversionista_canonica(s.inversionista_id)
4173:     join crm.inversion_solicitud_revisiones r on r.solicitud_id=s.id
4174:     where s.id=case when current_setting('crm.f4_revision_solicitud',true)
4175:       ~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
4176:       then current_setting('crm.f4_revision_solicitud',true)::uuid else null end
4177:       and s.estado='preparada' and s.responsable_esperado_id=p_responsable
4178:       and i.estado='activo' and not i.no_contactar and i.responsable_relacion_id=p_responsable
4179:       and r.revisado_por=(select auth.uid()) and r.transaccion=pg_current_xact_id()
4180:       and r.responsable_nuevo_id=p_responsable
4181:       and (i.perfil_id=p_perfil or (i.perfil_id is null and exists(
4182:         select 1 from crm.multiempresa_idempotencia m join auth.users u
4183:           on u.id=(m.resultado->>'auth_user_id')::uuid
4184:         where m.clave='auth_persona:'||i.id::text
4185:           and m.resultado->>'claim_id'=s.auth_claim_id::text
4186:           and m.resultado->>'estado' in ('auth_creado','perfil_creado')
4187:           and u.id=p_perfil and u.raw_app_meta_data->>'claim_id'=s.auth_claim_id::text
4188:       )))
4189:   );
4190: $$;
