4193: create or replace function crm.revisar_solicitud_inversion_fn(
4194:   p_solicitud uuid,p_responsable_revisado uuid,p_revision_esperada integer,p_motivo text)
4195: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
4196: declare
4197:   v_persona uuid;
4198:   v_origen uuid;
4199:   v_ctx jsonb;
4200:   v_s crm.inversion_solicitudes%rowtype;
4201:   v_revision crm.inversion_solicitud_revisiones%rowtype;
4202:   v_num integer;
4203:   v_motivo text:=btrim(p_motivo);
4204:   v_perfil uuid;
4205:   v_p public.perfiles%rowtype;
4206:   v_saga crm.multiempresa_idempotencia%rowtype;
4207:   v_config text:=current_setting('crm.f4_revision_solicitud',true);
4208: begin
4209:   if p_solicitud is null or p_responsable_revisado is null or p_revision_esperada is null or p_revision_esperada<0 then
4210:     raise exception 'Falta la solicitud, el responsable revisado o su versión' using errcode='22023';
4211:   end if;
4212:   select inversionista_id into v_persona from crm.inversion_solicitudes where id=p_solicitud;
4213:   v_origen:=v_persona;
4214:   v_ctx:=private.inversion_persona_contexto(v_persona);
4215:   v_persona:=(v_ctx->>'inversionista_id')::uuid;
4216:   select * into v_s from crm.inversion_solicitudes where id=p_solicitud for update;
4217:   if not found or v_s.inversionista_id is distinct from v_origen then
4218:     raise exception 'La solicitud cambió; vuelve a cargarla' using errcode='40001';
4219:   end if;
4220:   if v_s.estado<>'preparada' then
4221:     raise exception 'Solo se revisa el responsable de una solicitud pendiente; las inversiones confirmadas conservan su atribución' using errcode='P0409';
4222:   end if;
4223:   if p_responsable_revisado is distinct from (v_ctx->>'responsable_id')::uuid then
4224:     raise exception 'El responsable actual ya no coincide con el que revisaste' using errcode='40001';
4225:   end if;
4226:   perform private.motivo_sin_documento(v_motivo,
4227:     (select array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id=v_persona));
4228:   select * into v_revision from crm.inversion_solicitud_revisiones r
4229:     where r.solicitud_id=v_s.id order by r.revision desc limit 1;
4230:   v_num:=coalesce(v_revision.revision,0);
4231:   if p_revision_esperada<>v_num then
4232:     if p_revision_esperada=v_num-1 and v_revision.responsable_nuevo_id=p_responsable_revisado
4233:        and v_s.responsable_esperado_id=p_responsable_revisado and v_revision.motivo=v_motivo then
4234:       return private.inversion_solicitud_resultado(v_s.id,v_ctx)||jsonb_build_object('reintento',true);
4235:     end if;
4236:     raise exception 'La revisión cambió; vuelve a cargar la solicitud' using errcode='40001';
4237:   end if;
4238:   if v_s.responsable_esperado_id=p_responsable_revisado then
4239:     return private.inversion_solicitud_resultado(v_s.id,v_ctx)||jsonb_build_object('sin_cambios',true);
4240:   end if;
4241:   v_perfil:=(v_ctx->>'perfil_id')::uuid;
4242:   if v_s.auth_claim_id is not null then
4243:     select * into v_saga from crm.multiempresa_idempotencia m
4244:       where m.clave='auth_persona:'||coalesce(v_s.auth_contexto->>'inversionista_id',v_origen::text)
4245:         and m.resultado->>'claim_id'=v_s.auth_claim_id::text for update;
4246:     if not found then raise exception 'El proceso de acceso requiere conciliación' using errcode='P0409'; end if;
4247:     -- La corrección canónica solo se permite una vez enlazado el acceso. Su
4248:     -- contexto original queda histórico y no impide revisar al nuevo equipo.
4249:     if v_saga.resultado->>'estado'<>'enlazado' and not private.documento_es_de_identidad(
4250:       v_persona,v_s.auth_contexto->>'documento_tipo',v_s.auth_contexto->>'documento') then
4251:       raise exception 'El documento también cambió; revisa primero el acceso pendiente' using errcode='P0409';
4252:     end if;
4253:     if v_saga.resultado->>'auth_user_id' is not null then
4254:       if not exists(select 1 from auth.users u where u.id=(v_saga.resultado->>'auth_user_id')::uuid
4255:         and u.raw_app_meta_data->>'claim_id'=v_s.auth_claim_id::text) then
4256:         raise exception 'El acceso pendiente no tiene la procedencia esperada' using errcode='P0409';
4257:       end if;
4258:       if v_perfil is not null and v_perfil is distinct from (v_saga.resultado->>'auth_user_id')::uuid then
4259:         raise exception 'El perfil y el acceso pertenecen a procesos diferentes' using errcode='P0409';
4260:       end if;
4261:       select id into v_perfil from public.perfiles where id=(v_saga.resultado->>'auth_user_id')::uuid;
4262:       if v_perfil is null and v_saga.resultado->>'estado' in ('perfil_creado','enlazado') then
4263:         raise exception 'El perfil del proceso ya no existe; requiere revisión' using errcode='P0409';
4264:       end if;
4265:     end if;
4266:   end if;
4267:   if v_perfil is not null then
4268:     -- La gestión de tareas puede tener ya una tarea/perfil. No esperar bajo el
4269:     -- candado de persona: el intento se revierte entero y se puede repetir.
4270:     begin
4271:       perform 1 from crm.tareas t where t.perfil_id=v_perfil and t.estado='pendiente'
4272:         order by t.id for update nowait;
4273:       select * into v_p from public.perfiles where id=v_perfil for update nowait;
4274:     exception when lock_not_available then
4275:       raise exception 'Otra sesión está trabajando la ficha o sus tareas; vuelve a revisar' using errcode='40001';
4276:     end;
4277:     if not found or v_p.rol<>'cliente' or v_p.activo is not true
4278:        or not private.documento_es_de_identidad(v_persona,v_p.tipo_documento,v_p.dni) then
4279:       raise exception 'El perfil requiere conciliación con esta persona' using errcode='P0409';
4280:     end if;
4281:   end if;
4282: 
4283:   insert into crm.inversion_solicitud_revisiones(solicitud_id,revision,responsable_anterior_id,
4284:     responsable_nuevo_id,motivo,revisado_por)
4285:   values(v_s.id,v_num+1,v_s.responsable_esperado_id,p_responsable_revisado,v_motivo,(select auth.uid()));
4286:   update crm.inversion_solicitudes set responsable_esperado_id=p_responsable_revisado,
4287:     actualizado_en=statement_timestamp() where id=v_s.id;
4288:   if v_perfil is not null and v_p.asesor_perfil_id is distinct from p_responsable_revisado then
4289:     perform set_config('crm.f4_revision_solicitud',v_s.id::text,true);
4290:     begin
4291:       update public.perfiles set asesor_perfil_id=p_responsable_revisado where id=v_perfil;
4292:       if (select asesor_perfil_id from public.perfiles where id=v_perfil) is distinct from p_responsable_revisado then
4293:         raise exception 'El perfil no pudo alinearse con su responsable actual' using errcode='P0409';
4294:       end if;
4295:     exception when others then
4296:       perform set_config('crm.f4_revision_solicitud',coalesce(v_config,''),true);
4297:       raise;
4298:     end;
4299:     perform set_config('crm.f4_revision_solicitud',coalesce(v_config,''),true);
4300:   end if;
4301:   -- No cambia datos/hash/auth_contexto ni token/versión/lease de la saga.
4302:   return private.inversion_solicitud_resultado(v_s.id,v_ctx)||jsonb_build_object('reintento',false);
4303: end;
4304: $$;
4305: revoke all on function crm.revisar_solicitud_inversion_fn(uuid,uuid,integer,text) from public,anon,authenticated,service_role;
4306: grant execute on function crm.revisar_solicitud_inversion_fn(uuid,uuid,integer,text) to authenticated;
