4308: -- Continuación F4. Integrada en la candidata; sin ejecución productiva.
4309: -- Previsualización administrativa: no crea identidades, no modifica fuentes ni
4310: -- documentos, no asigna responsables. El escritor del lote se construye aparte.
4311: create or replace function private.inversion_historica_estado(p_tipo text,p_id uuid)
4312: returns jsonb language plpgsql stable security invoker set search_path='' as $$
4313: declare
4314:   v_c public.contratos%rowtype;
4315:   v_ce crm.cierres_externos%rowtype;
4316:   v_p public.perfiles%rowtype;
4317:   v_l crm.leads%rowtype;
4318:   v_i crm.inversionistas%rowtype;
4319:   v_inv crm.inversiones%rowtype;
4320:   v_tit crm.inversion_titulares%rowtype;
4321:   v_empresa uuid;
4322:   v_persona uuid;
4323:   v_perfil uuid;
4324:   v_documento uuid;
4325:   v_indicios uuid[] := '{}';
4326:   v_mapa jsonb;
4327:   v_fuente jsonb;
4328:   v_datos_identidad jsonb;
4329:   v_estado text := 'pendiente';
4330:   v_motivos text[] := '{}';
4331:   v_demo boolean := false;
4332:   v_estado_economico text;
4333:   v_fecha date;
4334:   v_inicial boolean;
4335:   v_creado_por uuid;
4336:   v_eliminacion boolean := false;
4337:   v_n integer;
4338: begin
4339:   if p_tipo is null or p_tipo not in ('contrato','cierre') or p_id is null then
4340:     raise exception 'Indica una fuente contractual o cooperativa concreta' using errcode='22023';
4341:   end if;
4342:   if p_tipo='contrato' then
4343:     select * into v_c from public.contratos where id=p_id;
4344:     if not found then
4345:       return jsonb_build_object('tipo',p_tipo,'id',p_id,'estado','ausente');
4346:     end if;
4347:     v_fuente:=to_jsonb(v_c);
4348:     v_demo:=v_c.es_demo;
4349:     v_fecha:=v_c.fecha_cierre_comercial;
4350:     v_estado_economico:='vigente'; -- El ciclo del contrato continúa en su fuente.
4351:     v_inicial:=false;
4352:     v_creado_por:=v_c.creado_por;
4353:     v_eliminacion:=private.contrato_en_eliminacion(p_id);
4354:     select id into v_empresa from crm.empresas where clave='avance';
4355:     select * into v_p from public.perfiles where id=v_c.cliente_id;
4356:     select id into v_perfil from crm.inversionistas
4357:       where perfil_id=v_c.cliente_id and estado<>'fusionado';
4358:     -- El documento se lee por el mismo reconocedor privado vigente de F3.
4359:     v_documento:=private.inversionista_por_documento(v_p.tipo_documento,v_p.dni);
4360:     v_indicios:=array[v_perfil,v_documento];
4361:     if v_p.rol is distinct from 'cliente' then
4362:       v_motivos:=array_append(v_motivos,'perfil_no_cliente');
4363:     end if;
4364:     if v_perfil is null then
4365:       v_motivos:=array_append(v_motivos,'perfil_sin_vinculo_canonico');
4366:     elsif not private.documento_es_de_identidad(v_perfil,v_p.tipo_documento,v_p.dni) then
4367:       v_motivos:=array_append(v_motivos,'documento_perfil_no_conciliado');
4368:     end if;
4369:     select to_jsonb(m) into v_mapa from crm.backfill_multiempresa_mapa m
4370:       where fuente='perfil' and fila_id=v_c.cliente_id;
