4404:     select * into v_inv from crm.inversiones where cierre_externo_id=p_id;
4405:   end if;
4406: 
4407:   if v_mapa->>'inversionista_id' is not null and v_mapa->>'clase'<>'E' then
4408:     v_indicios:=array_append(v_indicios,(v_mapa->>'inversionista_id')::uuid);
4409:   end if;
4410:   select coalesce(array_agg(distinct private.inversionista_canonica(x)
4411:     order by private.inversionista_canonica(x)),'{}') into v_indicios
4412:     from unnest(v_indicios) x where x is not null;
