4429: 
4430:   select count(*) into v_n from crm.inversion_titulares
4431:     where inversion_id=v_inv.id and rol='principal';
4432:   if v_n=1 then
4433:     select * into v_tit from crm.inversion_titulares
4434:       where inversion_id=v_inv.id and rol='principal';
4435:   end if;
4436:   if v_inv.id is not null then
