4450: 
4451:   -- La huella detecta deriva de fuente, vínculos, mapa, identidad y documentos.
4452:   -- El informe entrega solo referencias y huellas; no copia cifras ni documentos.
4453:   select coalesce(jsonb_agg(jsonb_build_object('persona',to_jsonb(i),
