4457:   return jsonb_build_object('tipo',p_tipo,'id',p_id,'estado',v_estado,
4458:     'motivos',v_motivos,'persona',v_persona,'empresa',v_empresa,
4459:     'indicios',v_indicios,'inversion',v_inv.id,'titular',v_tit.id,
4460:     'fuente_persona',case when p_tipo='cierre' then v_ce.inversionista_id else v_perfil end,
4461:     'perfil',case when p_tipo='contrato' then v_c.cliente_id else v_l.perfil_id end,
4462:     'lead',v_ce.lead_id,'fecha',v_fecha,'estado_economico',v_estado_economico,
4463:     'inicial',v_inicial,'creado_por',v_creado_por,
4464:     'huella',private.idem_hash(jsonb_build_object('fuente',v_fuente,'perfil',to_jsonb(v_p),
4465:       'lead',to_jsonb(v_l),'identidades',v_datos_identidad,'mapa',v_mapa,
4466:       'inversion',to_jsonb(v_inv),'titulares',(select coalesce(jsonb_agg(to_jsonb(t) order by t.id),'[]')
4467:         from crm.inversion_titulares t where t.inversion_id=v_inv.id),'eliminacion',v_eliminacion)));
4468: end;
4469: $$;
