4493: create or replace function private.f4_proteger_lote_historico()
4494: returns trigger language plpgsql security invoker set search_path='' as $$
4495: begin
4496:   if tg_when='AFTER' then
4497:     if exists (select 1 from crm.inversion_backfill_lotes l where l.id=new.id and l.finalizado_en is null) then
4498:       raise exception 'Un lote histórico no puede quedar incompleto' using errcode='23514';
