4507:        is distinct from (to_jsonb(old)-array['resultado','finalizado_en'])
4508:      or new.finalizado_en is null or new.resultado is null then
4509:     raise exception 'Solo puede concluirse el lote de esta transacción' using errcode='P0409';
4510:   end if;
4511:   return new;
4512: end;
4513: $$;
