4520: create or replace function private.inversion_historica_aplicar(p_lote uuid,p_mapa jsonb)
4521: returns jsonb language plpgsql security invoker set search_path='' set lock_timeout='5s' as $$
4522: declare
4523:   v_mapa jsonb;
4524:   v_hash text;
4525:   v_previo crm.inversion_backfill_lotes%rowtype;
4526:   v_r record;
4527:   v_actual jsonb;
4528:   v_final jsonb;
4529:   v_inversion uuid;
4530:   v_resultado jsonb;
4531:   v_filas jsonb := '[]';
4532:   v_n integer;
4533:   v_personas uuid[];
4534:   v_perfiles uuid[];
4535:   v_leads uuid[];
4536:   v_contratos uuid[];
4537:   v_cierres uuid[];
4538:   v_inversiones uuid[];
4539:   v_old_priv text := current_setting('crm.op_privilegiada',true);
4540: begin
4541:   -- Mantenimiento por conexión administrativa, nunca una puerta HTTP ni una
4542:   -- delegación implícita de service_role. INVOKER mantiene los privilegios reales.
4543:   if session_user not in ('postgres','supabase_admin') or current_user<>'postgres' then
4544:     raise exception 'La vinculación histórica exige una sesión administrativa' using errcode='42501';
4545:   end if;
4546:   if current_setting('transaction_isolation')<>'read committed' then
4547:     raise exception 'El lote histórico exige READ COMMITTED' using errcode='0A000';
4548:   end if;
4549:   if p_lote is null or jsonb_typeof(p_mapa) is distinct from 'array' then
4550:     raise exception 'Indica lote y previsualización completos' using errcode='22023';
4551:   end if;
4552:   if jsonb_array_length(p_mapa)<1 or jsonb_array_length(p_mapa)>100 then
4553:     raise exception 'El lote admite entre una y cien fuentes concretas' using errcode='22023';
4554:   end if;
4555:   select jsonb_agg(value order by value->>'tipo',value->>'id'),
4556:     count(distinct (value->>'tipo',value->>'id')) into v_mapa,v_n
4557:     from jsonb_array_elements(p_mapa);
4558:   if v_n<>jsonb_array_length(p_mapa) then
4559:     raise exception 'Una fuente no se repite dentro del lote' using errcode='22023';
4560:   end if;
4561:   v_hash:=private.idem_hash(v_mapa);
4562: 
4563:   -- Ventana breve y explícita de mantenimiento. El orden coincide con el
4564:   -- protocolo de banderas: identidad -> inversión. No se cambia ninguna bandera.
4565:   -- El exclusivo de identidad drena sus escritores antes de fijar la foto; las
4566:   -- correcciones financieras que no lo usan se arbitran con locks NOWAIT abajo.
4567:   perform pg_advisory_xact_lock(hashtext('crm_flag_resolver_en_puertas'));
4568:   perform pg_advisory_xact_lock(hashtext('crm_flag_inversiones_escritura'));
4569:   if not private.resolver_en_puertas_bajo_candado() then
4570:     raise exception 'La identidad debe estar encendida para vincular sus fuentes' using errcode='P0409';
4571:   end if;
4572:   if private.inversiones_escritura_bajo_candado() then
4573:     raise exception 'Apaga el escritor de inversiones antes del lote histórico' using errcode='P0409';
4574:   end if;
4575:   select * into v_previo from crm.inversion_backfill_lotes where id=p_lote;
4576:   if found then
4577:     if v_previo.hash_mapa<>v_hash then
4578:       raise exception 'El lote ya corresponde a otra previsualización' using errcode='P0409';
4579:     end if;
4580:     if v_previo.finalizado_en is null then
4581:       raise exception 'Lote histórico incoherente: requiere revisión' using errcode='P0409';
4582:     end if;
4583:     return v_previo.resultado;
4584:   end if;
4585: 
4586:   -- El mantenimiento F2 legado no participa en las banderas de identidad.
4587:   -- Bloquear filas existentes no cubre un mapa todavía ausente: SHARE fija
4588:   -- también ese conjunto frente a INSERT/UPDATE/DELETE hasta COMMIT. NOWAIT
4589:   -- rechaza otra intervención administrativa sin crear un ciclo de espera.
4590:   lock table crm.backfill_multiempresa_mapa in share mode nowait;
4591: 
4592:   -- Revalidar referencias antes de usarlas para bloquear; nunca confiar en los
4593:   -- IDs de persona/empresa o en el estado que envíe el consumidor del censo.
4594:   for v_r in select value from jsonb_array_elements(v_mapa) loop
4595:     v_actual:=private.inversion_historica_estado(v_r.value->>'tipo',(v_r.value->>'id')::uuid);
4596:     if v_actual is distinct from v_r.value then
4597:       raise exception 'La previsualización histórica cambió; repite el censo' using errcode='40001';
4598:     end if;
4599:     if v_actual->>'estado' not in ('pendiente','titular_pendiente','resuelto') then
4600:       raise exception 'El lote contiene una fuente que requiere revisión o está excluida' using errcode='P0409';
4601:     end if;
4602:   end loop;
4603:   select array_agg(distinct (value->>'persona')::uuid),
4604:     array_agg(distinct (value->>'perfil')::uuid),array_agg(distinct (value->>'lead')::uuid),
4605:     array_agg((value->>'id')::uuid) filter(where value->>'tipo'='contrato'),
4606:     array_agg((value->>'id')::uuid) filter(where value->>'tipo'='cierre'),
4607:     array_agg(distinct (value->>'inversion')::uuid)
4608:     into v_personas,v_perfiles,v_leads,v_contratos,v_cierres,v_inversiones
4609:     from jsonb_array_elements(v_mapa);
4610:   perform 1 from crm.inversionistas where id=any(v_personas) order by id for update nowait;
4611:   perform 1 from public.perfiles where id=any(v_perfiles) order by id for share nowait;
4612:   perform 1 from crm.cierres_externos where id=any(v_cierres) order by id for update nowait;
4613:   perform 1 from public.contratos where id=any(v_contratos) order by id for update nowait;
4614:   perform 1 from crm.inversiones where id=any(v_inversiones) order by id for update nowait;
4615:   perform 1 from crm.inversion_titulares where inversion_id=any(v_inversiones) order by id for update nowait;
4616:   perform 1 from crm.leads where id=any(v_leads) order by id for share nowait;
4617:   for v_r in select value from jsonb_array_elements(v_mapa) loop
4618:     if private.inversion_historica_estado(v_r.value->>'tipo',(v_r.value->>'id')::uuid)
4619:        is distinct from v_r.value then
4620:       raise exception 'La fuente histórica cambió mientras se bloqueaba; repite el censo' using errcode='40001';
4621:     end if;
4622:   end loop;
4623: 
4624:   -- Acta ANTES de enlazar. Si cualquier paso falla, PostgreSQL revierte acta y
4625:   -- enlaces; la restricción diferida impide confirmar un acta inconclusa.
4626:   insert into crm.inversion_backfill_lotes(id,hash_mapa,mapa) values(p_lote,v_hash,v_mapa);
4627:   for v_r in select value from jsonb_array_elements(v_mapa) loop
4628:     v_actual:=v_r.value;
4629:     if v_actual->>'estado'<>'resuelto' then
4630:       if v_actual->>'tipo'='cierre' and v_actual->>'fuente_persona' is null then
4631:         perform set_config('crm.op_privilegiada','on',true);
4632:         update crm.cierres_externos set inversionista_id=(v_actual->>'persona')::uuid
4633:           where id=(v_actual->>'id')::uuid and inversionista_id is null;
4634:         get diagnostics v_n=row_count;
4635:         perform set_config('crm.op_privilegiada',coalesce(v_old_priv,'off'),true);
4636:         if v_n<>1 then raise exception 'La fuente ya cambió de identidad' using errcode='40001'; end if;
4637:       end if;
4638:       v_inversion:=private.inversion_vincular_fuente((v_actual->>'persona')::uuid,
4639:         case when v_actual->>'tipo'='contrato' then (v_actual->>'id')::uuid end,
4640:         case when v_actual->>'tipo'='cierre' then (v_actual->>'id')::uuid end,
4641:         (v_actual->>'creado_por')::uuid,(v_actual->>'inicial')::boolean);
4642:     else
4643:       v_inversion:=(v_actual->>'inversion')::uuid;
4644:     end if;
4645:     v_final:=private.inversion_historica_estado(v_actual->>'tipo',(v_actual->>'id')::uuid);
4646:     if v_final->>'estado'<>'resuelto' or (v_final->>'inversion')::uuid<>v_inversion then
4647:       raise exception 'La vinculación histórica no quedó conciliada' using errcode='P0409';
4648:     end if;
4649:     v_filas:=v_filas||jsonb_build_array(jsonb_build_object('tipo',v_actual->>'tipo','id',v_actual->>'id',
4650:       'accion',case v_actual->>'estado' when 'resuelto' then 'sin_cambios'
4651:         when 'titular_pendiente' then 'titular_completado' else 'vinculada' end,
4652:       'inversion',v_inversion,'titular',v_final->>'titular','persona',v_final->>'persona',
4653:       'huella_final',v_final->>'huella'));
4654:   end loop;
4655:   v_resultado:=jsonb_build_object('lote',p_lote,'fuentes',v_filas,'hash_mapa',v_hash);
4656:   update crm.inversion_backfill_lotes set resultado=v_resultado,finalizado_en=clock_timestamp() where id=p_lote;
4657:   perform set_config('crm.op_privilegiada',coalesce(v_old_priv,'off'),true);
4658:   return v_resultado;
4659: exception when others then
4660:   perform set_config('crm.op_privilegiada',coalesce(v_old_priv,'off'),true);
4661:   raise;
4662: end;
4663: $$;
