4743: -- Sólo consume identidades verificadas. Un documento histórico reutilizado por
4744: -- otra persona queda en revisión: nunca se adivina quién firmó el contrato.
4745: create or replace function private.inversion_cotitular_estado(p_titular uuid)
4746: returns jsonb language plpgsql stable security invoker set search_path='' as $$
4747: declare
4748:   v_t public.contrato_titulares%rowtype;
4749:   v_o crm.inversion_cotitular_origenes%rowtype;
4750:   v_d crm.inversionista_identificadores%rowtype;
4751:   v_i uuid; v_p uuid; v_norm text; v_base jsonb; v_duenos integer;
4752: begin
4753:   select * into v_t from public.contrato_titulares where id=p_titular;
4754:   if not found then raise exception 'Titular no encontrado' using errcode='P0002'; end if;
4755:   select id into v_i from crm.inversiones where contrato_id=v_t.contrato_id;
4756:   v_base:=jsonb_build_object('titular_id',v_t.id,'orden',v_t.orden,'inversion_id',v_i);
4757:   select * into v_o from crm.inversion_cotitular_origenes where contrato_titular_id=v_t.id;
4758:   if found then
4759:     v_p:=private.inversionista_canonica(v_o.persona_origen_id);
4760:     if v_o.inversion_id is distinct from v_i or v_o.hash_fuente is distinct from private.idem_hash(to_jsonb(v_t))
4761:       or not exists(select 1 from crm.inversion_titulares where inversion_id=v_i and inversionista_id=v_p) then
4762:       return v_base||jsonb_build_object('estado','revision','motivo','procedencia_incoherente');
4763:     end if;
4764:     return v_base||jsonb_build_object('estado','vinculado','inversionista_id',v_p,
4765:       'persona_origen_id',v_o.persona_origen_id,'origen_registro',v_o.origen_registro);
4766:   end if;
4767:   if v_i is null or not private.contrato_documental_congelado(v_t.contrato_id) then
4768:     return v_base||jsonb_build_object('estado','pendiente','motivo','sin_inversion_o_snapshot');
4769:   end if;
4770:   v_norm:=upper(regexp_replace(coalesce(v_t.documento,''),'[^A-Za-z0-9]','','g'));
4771:   select count(distinct private.inversionista_canonica(inversionista_id)) into v_duenos
4772:     from crm.inversionista_identificadores where tipo_documento=v_t.tipo_documento and documento_normalizado=v_norm and verificado;
4773:   if v_duenos>1 then
4774:     return v_base||jsonb_build_object('estado','revision','motivo','documento_reutilizado');
4775:   end if;
4776:   select d.* into v_d from crm.inversionista_identificadores d join crm.inversionistas p on p.id=d.inversionista_id
4777:     where d.tipo_documento=v_t.tipo_documento and d.documento_normalizado=v_norm and d.estado='vigente'
4778:       and d.verificado and p.estado='activo' and private.inversionista_canonica(p.id)=p.id;
4779:   if not found then
4780:     return v_base||jsonb_build_object('estado','pendiente','motivo','identidad_verificada_pendiente');
4781:   end if;
4782:   return v_base||jsonb_build_object('estado','disponible','inversionista_id',v_d.inversionista_id,
4783:     'identificador_id',v_d.id);
4784: end;
4785: $$;
4786: revoke all on function private.inversion_cotitular_estado(uuid) from public,anon,authenticated,service_role;
