4788: create or replace function private.inversion_cotitulares_vincular(p_inversion uuid,p_origen_registro text)
4789: returns jsonb language plpgsql security invoker set search_path='' as $$
4790: declare
4791:   v_i crm.inversiones%rowtype; v_t public.contrato_titulares%rowtype;
4792:   v_d crm.inversionista_identificadores%rowtype; v_s jsonb; v_res jsonb:='[]'; v_p uuid;
4793: begin
4794:   if current_user<>'postgres' or p_origen_registro not in ('alta','conciliacion','administracion') then
4795:     raise exception 'Operación interna' using errcode='42501';
4796:   end if;
4797:   select * into v_i from crm.inversiones where id=p_inversion for update nowait;
4798:   if not found then raise exception 'Inversión no encontrada' using errcode='P0002'; end if;
4799:   if v_i.contrato_id is null then return v_res; end if;
4800:   perform 1 from public.contratos where id=v_i.contrato_id for share nowait;
4801:   for v_t in select * from public.contrato_titulares where contrato_id=v_i.contrato_id order by orden,id loop
4802:     begin
4803:       perform 1 from public.contrato_titulares where id=v_t.id for update nowait;
4804:       v_s:=private.inversion_cotitular_estado(v_t.id);
4805:       if v_s->>'estado'='disponible' then
4806:         -- Misma clave que F3; no esperar una corrección/fusión que necesita la
4807:         -- persona principal ya bloqueada por el alta de esta inversión.
4808:         if not pg_try_advisory_xact_lock(hashtext('inv_resolver:'||v_t.tipo_documento||':'||
4809:           upper(regexp_replace(coalesce(v_t.documento,''),'[^A-Za-z0-9]','','g')))) then
4810:           raise lock_not_available;
4811:         end if;
4812:         v_p:=(v_s->>'inversionista_id')::uuid;
4813:         perform 1 from crm.inversionistas where id=v_p for update nowait;
4814:         v_s:=private.inversion_cotitular_estado(v_t.id);
4815:         if v_s->>'estado'='disponible' and (v_s->>'inversionista_id')::uuid=v_p then
4816:           select * into strict v_d from crm.inversionista_identificadores where id=(v_s->>'identificador_id')::uuid;
4817:           insert into crm.inversion_titulares(inversion_id,inversionista_id,rol,creado_por)
4818:             values(v_i.id,v_p,'cotitular',(select auth.uid())) on conflict(inversion_id,inversionista_id) do nothing;
4819:           insert into crm.inversion_cotitular_origenes(contrato_titular_id,inversion_id,persona_origen_id,
4820:             identificador_origen_id,fuente_snapshot,identificador_snapshot,hash_fuente,vinculado_por,origen_registro)
4821:             values(v_t.id,v_i.id,v_p,v_d.id,to_jsonb(v_t),to_jsonb(v_d),private.idem_hash(to_jsonb(v_t)),(select auth.uid()),p_origen_registro);
4822:           v_s:=private.inversion_cotitular_estado(v_t.id);
4823:         end if;
4824:       end if;
4825:     exception when lock_not_available or deadlock_detected then
4826:       v_s:=jsonb_build_object('titular_id',v_t.id,'orden',v_t.orden,'inversion_id',v_i.id,
4827:         'estado','pendiente','motivo','identidad_ocupada');
4828:     end;
4829:     -- El lector comercial no recibe identificadores privados ni huellas.
4830:     v_res:=v_res||jsonb_build_array(v_s-'identificador_id');
4831:   end loop;
4832:   return v_res;
4833: end;
4834: $$;
4835: revoke all on function private.inversion_cotitulares_vincular(uuid,text) from public,anon,authenticated,service_role;
