4881: -- Validador único compartido por preparación y corrección explícita.
4882: create or replace function private.inversion_validar_datos(p_clave uuid,p_datos jsonb,p_contexto jsonb)
4883: returns uuid language plpgsql security invoker set search_path='' as $$
4884: declare
4885:   v_persona uuid:=(p_datos->>'inversionista_id')::uuid;
4886:   v_ctx jsonb:=p_contexto;
4887:   v_e crm.empresas%rowtype;
4888:   v_monto numeric; v_fecha date; v_vence date; v_ruta text;
4889: begin
4890:   if p_clave is null or p_datos is null or jsonb_typeof(p_datos)<>'object' then
4891:     raise exception 'Falta la clave o el contenido de la inversión' using errcode='22023';
4892:   end if;
4893:   if exists (select 1 from jsonb_object_keys(p_datos) k where k not in (
4894:     'inversionista_id','empresa','monto','moneda','fecha_comercial','vence_en','numero_transaccion',
4895:     'referencia','evidencia','producto_condicion_id','contrato','cronograma','cuenta','alta_portal'
4896:   )) then
4897:     raise exception 'La solicitud contiene campos no admitidos' using errcode='22023';
4898:   end if;
4899:   select * into v_e from crm.empresas where clave=p_datos->>'empresa' and activa for share;
4900:   if not found or v_e.clave not in ('avance','qorilazo','prodelco') then
4901:     raise exception 'Empresa no disponible para invertir' using errcode='22023';
4902:   end if;
4903:   if v_e.fuente_capital='cierres_externos' then
4904:     begin
4905:       v_monto := (p_datos->>'monto')::numeric;
4906:       v_fecha := (p_datos->>'fecha_comercial')::date;
4907:       v_vence := (p_datos->>'vence_en')::date;
4908:     exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
4909:       raise exception 'Revisa el monto y las fechas de la inversión' using errcode='22023';
4910:     end;
4911:     if v_monto is null or v_monto in ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric)
4912:        or v_monto<=0 or v_monto>999999999999.99 or v_monto<>trunc(v_monto,2) then
4913:       raise exception 'El monto debe ser positivo y tener como máximo dos decimales' using errcode='22023';
4914:     end if;
4915:     if p_datos->>'moneda' is distinct from 'PEN' or not ('PEN'=any(v_e.monedas)) then
4916:       raise exception 'Esta cooperativa registra inversiones en soles' using errcode='22023';
4917:     end if;
4918:     if v_fecha is null or not isfinite(v_fecha) or v_fecha>(statement_timestamp() at time zone 'America/Lima')::date
4919:        or v_vence is null or not isfinite(v_vence) or v_vence<=v_fecha then
4920:       raise exception 'La fecha comercial no puede ser futura y el vencimiento debe ser posterior' using errcode='22023';
4921:     end if;
4922:     if length(btrim(coalesce(p_datos->>'numero_transaccion',''))) not between 1 and 64
4923:        or length(btrim(coalesce(p_datos->>'referencia',''))) not between 1 and 64 then
4924:       raise exception 'El depósito y la referencia son obligatorios, con un máximo de 64 caracteres' using errcode='22023';
4925:     end if;
4926:     v_ruta := p_datos#>>'{evidencia,ruta}';
4927:     if v_ruta is null or v_ruta !~ ('^'||v_persona::text||'/'||p_clave::text||'/[a-zA-Z0-9_-]+\.(pdf|jpg|jpeg|png)$') then
4928:       raise exception 'El comprobante debe pertenecer a esta persona y solicitud' using errcode='22023';
4929:     end if;
4930:   else
4931:     if jsonb_typeof(p_datos->'contrato') is distinct from 'object'
4932:        or jsonb_typeof(p_datos->'cronograma') is distinct from 'array'
4933:        or jsonb_typeof(p_datos->'cuenta') is distinct from 'object' then
4934:       raise exception 'Avance requiere contrato, cronograma y cuenta de pago' using errcode='22023';
4935:     end if;
4936:     if p_datos#>>'{contrato,moneda}' is null or not (p_datos#>>'{contrato,moneda}'=any(v_e.monedas)) then
4937:       raise exception 'Moneda no admitida por Avance' using errcode='22023';
4938:     end if;
4939:     if p_datos#>>'{contrato,cliente_id}' is not null
4940:        and p_datos#>>'{contrato,cliente_id}' is distinct from v_ctx->>'perfil_id' then
4941:       raise exception 'El contrato debe pertenecer a esta persona' using errcode='P0409';
4942:     end if;
4943:     if v_ctx->>'perfil_id' is null or p_datos ? 'alta_portal' then
4944:       perform private.inversion_datos_portal(p_datos->'alta_portal');
4945:     end if;
4946:     if p_datos#>>'{contrato,analista_cierre_id}' is not null
4947:        and p_datos#>>'{contrato,analista_cierre_id}' is distinct from v_ctx->>'responsable_id' then
4948:       raise exception 'El analista debe corresponder al responsable de la persona al preparar la inversión' using errcode='P0409';
4949:     end if;
4950:   end if;
4951:   return v_e.id;
4952: end;
4953: $$;
