4993: create or replace function crm.corregir_solicitud_inversion_fn(
4994:   p_solicitud uuid,p_clave uuid,p_revision_datos_esperada integer,p_datos jsonb,p_motivo text)
4995: returns jsonb language plpgsql security definer set search_path='' set lock_timeout='5s' as $$
4996: declare
4997:   v_persona uuid; v_ctx jsonb; v_validacion jsonb;
4998:   v_s crm.inversion_solicitudes%rowtype;
4999:   v_r crm.inversion_solicitud_correcciones%rowtype;
5000:   v_hash text; v_inicial uuid; v_empresa uuid;
5001: begin
5002:   if p_clave is null or p_revision_datos_esperada is null or p_revision_datos_esperada<0
5003:     or p_datos is null or jsonb_typeof(p_datos)<>'object' then
5004:     raise exception 'Indica clave, versión y contenido de la corrección' using errcode='22023';
5005:   end if;
5006:   select inversionista_id into v_persona from crm.inversion_solicitudes where id=p_solicitud;
5007:   if not found then raise exception 'Solicitud no encontrada' using errcode='P0002'; end if;
5008:   -- Siempre ámbito/membresía actuales, también al recuperar una corrección.
5009:   v_ctx:=private.inversion_persona_autorizada(v_persona);
5010:   perform private.motivo_sin_documento(p_motivo,(select array_agg(documento_normalizado)
5011:     from crm.inversionista_identificadores where inversionista_id=private.inversionista_canonica(v_persona)));
5012:   v_hash:=private.idem_hash(jsonb_build_object('solicitud',p_solicitud,'revision',p_revision_datos_esperada,
5013:     'datos',p_datos,'motivo',btrim(p_motivo)));
