5032:     raise exception 'Revisa primero el cambio de responsable de esta solicitud' using errcode='P0409';
5033:   end if;
5034:   if p_datos->'inversionista_id' is distinct from v_s.datos->'inversionista_id'
5035:     or p_datos->'empresa' is distinct from v_s.datos->'empresa'
5036:     or p_datos#>'{contrato,cliente_id}' is distinct from v_s.datos#>'{contrato,cliente_id}'
5037:     or p_datos#>'{contrato,analista_cierre_id}' is distinct from v_s.datos#>'{contrato,analista_cierre_id}' then
5038:     raise exception 'La corrección conserva la persona, empresa y referencias originales del contrato' using errcode='22023';
5039:   end if;
5040:   if p_datos->'evidencia' is distinct from v_s.datos->'evidencia' then
5041:     raise exception 'La corrección conserva la ruta del comprobante de esta solicitud' using errcode='22023';
5042:   end if;
5043:   if v_s.auth_claim_id is not null and p_datos->'alta_portal' is distinct from v_s.datos->'alta_portal' then
5044:     raise exception 'El acceso Avance ya está reservado; conserva sus datos de alta' using errcode='P0409';
5045:   end if;
5046:   select responsable_anterior_id into v_inicial from crm.inversion_solicitud_revisiones
5047:     where solicitud_id=p_solicitud order by revision limit 1;
5048:   v_validacion:=v_ctx||jsonb_build_object('responsable_id',coalesce(v_inicial,v_s.responsable_esperado_id));
