5051:     raise exception 'La empresa cambió; revisa la solicitud' using errcode='40001';
5052:   end if;
5053:   if p_datos=v_s.datos then raise exception 'No hay datos distintos que corregir' using errcode='22023'; end if;
5054:   insert into crm.inversion_solicitud_correcciones(id,solicitud_id,revision_anterior,revision,
