11: function reemplazar(s,antes,despues,n=1) {
12:   const encontrados=s.split(antes).length-1;
13:   assert.equal(encontrados,n,`Ancla inesperada (${encontrados}): ${antes}`);
14:   return s.replaceAll(antes,despues);
