254:   if (path === `${contratoId}/contrato.pdf`) return true;
255:   const partes = path.split("/");
256:   return partes.length === 4 && partes[0] === contratoId &&
257:     partes[1] === "v2" &&
258:     uuidCanonico(partes[2]) && partes[3] === "contrato.pdf";
259: }
