319: export function normalizarUrlFirmadaV2(
320:   urlFirmada: string,
321:   basePublica: string,
322:   storagePathEsperado?: string,
323: ): string | null {
324:   try {
325:     const firmada = new URL(urlFirmada);
326:     const publica = new URL(basePublica);
327:     const loopback = new Set(["localhost", "127.0.0.1", "[::1]"]);
328:     const transporteSeguro = publica.protocol === "https:" ||
329:       (publica.protocol === "http:" && loopback.has(publica.hostname));
330:     const prefijo = `/storage/v1/object/sign/${CONTRATO_PDF_BUCKET}/`;
331:     if (
332:       !transporteSeguro || publica.username || publica.password ||
333:       firmada.username || firmada.password ||
334:       !firmada.pathname.startsWith(prefijo) ||
335:       firmada.pathname.slice(prefijo.length).length === 0 ||
336:       firmada.pathname.includes("\\") ||
337:       !firmada.searchParams.has("token") ||
338:       !firmada.searchParams.get("token")
339:     ) return null;
340:     if (storagePathEsperado !== undefined) {
341:       let pathFirmado: string;
342:       try {
343:         pathFirmado = decodeURIComponent(
344:           firmada.pathname.slice(prefijo.length),
345:         );
346:       } catch {
347:         return null;
348:       }
349:       if (pathFirmado !== storagePathEsperado) return null;
350:     }
351:     firmada.protocol = publica.protocol;
352:     firmada.host = publica.host;
353:     return firmada.toString();
354:   } catch {
355:     return null;
356:   }
357: }
