398: function parseEstado(valor: unknown, contratoId: string): EstadoPdf | null {
399:   if (!esObjeto(valor) || valor.contrato_id !== contratoId) return null;
400:   const estado = valor.estado;
401:   if (typeof estado !== "string" || !ESTADOS.has(estado as EstadoNombre)) {
402:     return null;
403:   }
404:   const jobId = valor.job_id;
405:   if (jobId !== null && !uuidCanonico(jobId)) return null;
406:   const path = valor.storage_path;
407:   const templateVersion = valor.template_version;
408:   if (
409:     valor.storage_bucket !== CONTRATO_PDF_BUCKET ||
410:     (path !== null && typeof path !== "string") ||
411:     (valor.nombre_archivo !== null && !nombreValido(valor.nombre_archivo)) ||
412:     (templateVersion !== null && typeof templateVersion !== "string") ||
413:     typeof valor.intentos !== "number" ||
414:     !Number.isSafeInteger(valor.intentos) || valor.intentos < 0 ||
415:     (valor.lease_expira_en !== null && !fechaIso(valor.lease_expira_en)) ||
416:     typeof valor.reintentable !== "boolean" ||
417:     (valor.sha256 !== null &&
418:       (typeof valor.sha256 !== "string" || !SHA256_RE.test(valor.sha256))) ||
419:     (valor.bytes !== null &&
420:       (typeof valor.bytes !== "number" || !Number.isSafeInteger(valor.bytes) ||
421:         valor.bytes <= 0 || valor.bytes > CONTRATO_PDF_MAX_BYTES))
422:   ) return null;
423:   if (
424:     path !== null &&
425:     !rutaValida(
426:       contratoId,
427:       jobId,
428:       typeof templateVersion === "string" ? templateVersion : null,
429:       path,
430:     )
431:   ) return null;
432:   const archivo = valor.archivo === null
433:     ? null
434:     : parseArchivo(valor.archivo, contratoId);
435:   if (valor.archivo !== null && !archivo) return null;
436:   // `reintentable` NO se exige aquí. Desde 2026-08-20 un contrato firmado antes
437:   // del 19-ago es del régimen documental anterior —ya tiene su contrato, el
438:   // sistema no le emite ninguno— y la RPC responde `sin_reserva` con
439:   // `reintentable: false`. Exigir `true`, como se hacía, descartaría la
440:   // respuesta entera (502) y rompería el detalle de todo contrato antiguo.
441:   if (
442:     estado === "sin_reserva" &&
443:     (jobId !== null || path !== null || valor.nombre_archivo !== null ||
444:       templateVersion !== null || valor.intentos !== 0 ||
445:       valor.lease_expira_en !== null ||
446:       valor.sha256 !== null || valor.bytes !== null || archivo !== null)
447:   ) return null;
448:   if (estado !== "sin_reserva" && estado !== "sellado" && jobId === null) {
449:     return null;
450:   }
451:   if (
452:     jobId !== null &&
453:     (!versionJobLegible(templateVersion) || path === null ||
454:       valor.nombre_archivo === null)
455:   ) return null;
456:   if (
457:     archivo &&
458:     (archivo.job_id !== jobId || archivo.storage_path !== path ||
459:       archivo.nombre_archivo !== valor.nombre_archivo ||
460:       archivo.template_version !== templateVersion ||
461:       archivo.sha256 !== valor.sha256 || archivo.bytes !== valor.bytes)
462:   ) return null;
463:   const integridad = estado === "integridad_bloqueada" ||
464:     (estado === "sellado" && archivo === null) ||
465:     (valor.ok === false && valor.codigo === "PDF_INTEGRIDAD_BLOQUEADA");
466:   return {
467:     contrato_id: contratoId,
468:     job_id: jobId,
469:     estado: estado as EstadoNombre,
470:     storage_bucket: CONTRATO_PDF_BUCKET,
471:     storage_path: path,
472:     nombre_archivo: valor.nombre_archivo as string | null,
473:     template_version: templateVersion as string | null,
474:     intentos: valor.intentos,
475:     lease_expira_en: valor.lease_expira_en as string | null,
476:     reintentable: valor.reintentable,
477:     sha256: valor.sha256 as string | null,
478:     bytes: valor.bytes as number | null,
479:     archivo,
480:     ...(integridad
481:       ? { ok: false as const, codigo: "PDF_INTEGRIDAD_BLOQUEADA" as const }
482:       : {}),
483:   };
484: }
