513: function respuestaBackend(
514:   result: BackendResult,
515:   contratoId: string,
516: ): { estado: EstadoPdf | null; status: number } {
517:   if (result.error) {
518:     const code = result.error.code;
519:     if (code === "42501") return { estado: null, status: 403 };
520:     if (code === "P0002" || code === "PGRST116") {
521:       return { estado: null, status: 404 };
522:     }
