532: async function leerJsonLimitado(req: Request): Promise<unknown> {
533:   const longitud = req.headers.get("Content-Length");
534:   if (longitud !== null) {
535:     const n = Number(longitud);
536:     if (!Number.isSafeInteger(n) || n < 0) {
537:       throw new Error("SOLICITUD_INVALIDA");
538:     }
539:     if (n > CONTRATO_PDF_MAX_REQUEST_BYTES) throw new Error("SOLICITUD_GRANDE");
540:   }
541:   if (!req.body) throw new Error("SOLICITUD_INVALIDA");
542:   const reader = req.body.getReader();
543:   const chunks: Uint8Array[] = [];
544:   let total = 0;
545:   while (true) {
546:     const { value, done } = await reader.read();
547:     if (done) break;
548:     total += value.byteLength;
549:     if (total > CONTRATO_PDF_MAX_REQUEST_BYTES) {
550:       await reader.cancel();
551:       throw new Error("SOLICITUD_GRANDE");
552:     }
553:     chunks.push(value);
554:   }
555:   const bytes = new Uint8Array(total);
556:   let offset = 0;
557:   for (const chunk of chunks) {
558:     bytes.set(chunk, offset);
559:     offset += chunk.byteLength;
560:   }
561:   let texto: string;
562:   try {
563:     texto = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
564:   } catch {
565:     throw new Error("SOLICITUD_INVALIDA");
566:   }
567:   try {
568:     return JSON.parse(texto);
569:   } catch {
570:     throw new Error("SOLICITUD_INVALIDA");
571:   }
572: }
