574: async function fingerprint(
575:   blob: Blob,
576: ): Promise<{ sha256: string; bytes: number }> {
577:   const buffer = await blob.arrayBuffer();
578:   const digest = await crypto.subtle.digest("SHA-256", buffer);
579:   return {
580:     sha256: [...new Uint8Array(digest)]
581:       .map((byte) => byte.toString(16).padStart(2, "0"))
582:       .join(""),
583:     bytes: buffer.byteLength,
584:   };
585: }
586: 
587: async function pdfValido(blob: Blob): Promise<boolean> {
588:   if (blob.size <= 5 || blob.size > CONTRATO_PDF_MAX_BYTES) return false;
589:   const encabezado = new Uint8Array(await blob.slice(0, 5).arrayBuffer());
590:   return new TextDecoder().decode(encabezado) === "%PDF-";
591: }
