599: export function crearHandlerContratoPdfV2(deps: DependenciasContratoPdfV2) {
600:   const origenes = new Set(ORIGENES_PRODUCCION);
601:   for (const origen of deps.origenesAdicionales ?? []) origenes.add(origen);
602: 
603:   return async (req: Request): Promise<Response> => {
604:     const origin = req.headers.get("Origin");
605:     if (req.method === "OPTIONS") {
606:       return new Response(null, {
607:         status: 204,
608:         headers: cabeceras(origin, origenes),
609:       });
610:     }
611:     if (req.method !== "POST") {
612:       return json(origin, origenes, {
613:         error: "Método no permitido",
614:         codigo: "METODO",
615:       }, 405);
616:     }
617:     const contentType = req.headers.get("Content-Type") ?? "";
618:     if (!/^application\/json(?:\s*;\s*charset=utf-8)?$/i.test(contentType)) {
619:       return json(
620:         origin,
621:         origenes,
622:         { error: "Se requiere application/json", codigo: "TIPO_CONTENIDO" },
623:         415,
624:       );
625:     }
626: 
627:     let cuerpo: unknown;
628:     try {
629:       cuerpo = await leerJsonLimitado(req);
630:     } catch (error) {
631:       const grande = error instanceof Error &&
632:         error.message === "SOLICITUD_GRANDE";
633:       return json(
634:         origin,
635:         origenes,
636:         {
637:           error: grande ? "Solicitud demasiado grande" : "JSON inválido",
638:           codigo: grande ? "SOLICITUD_GRANDE" : "JSON_INVALIDO",
639:         },
640:         grande ? 413 : 400,
641:       );
642:     }
643:     if (
644:       !esObjeto(cuerpo) || !clavesExactas(cuerpo, ["action", "contratoId"]) ||
645:       (cuerpo.action !== "ensure" && cuerpo.action !== "status" &&
646:         cuerpo.action !== "delete") ||
647:       !uuidCanonico(cuerpo.contratoId)
648:     ) {
649:       return json(
650:         origin,
651:         origenes,
652:         { error: "Solicitud inválida", codigo: "SOLICITUD_INVALIDA" },
653:         400,
654:       );
655:     }
656: 
657:     const token = bearer(req);
658:     if (!token) {
659:       return json(origin, origenes, {
660:         error: "Sesión inválida",
661:         codigo: "SESION",
662:       }, 401);
663:     }
664:     const actor = deps.crearActor(token);
665:     const sesion = await actor.verificarSesion();
666:     if (!sesion || !uuidCanonico(sesion.id)) {
667:       return json(origin, origenes, {
668:         error: "Sesión inválida",
669:         codigo: "SESION",
670:       }, 401);
671:     }
672:     const contratoId = cuerpo.contratoId;
673: 
674:     if (cuerpo.action === "delete") {
675:       const preparacionRaw = await deps.rpcAdmin(
676:         "contrato_eliminacion_preparar",
677:         { p_contrato_id: contratoId, p_actor_id: sesion.id },
678:       );
679:       if (preparacionRaw.error) {
680:         return json(
681:           origin,
682:           origenes,
683:           {
684:             error: mensajeErrorEliminacion(
685:               preparacionRaw.error,
686:               "No se pudo autorizar la eliminación del contrato",
687:             ),
688:             codigo: "CONTRATO_ELIMINACION_PREPARAR",
689:           },
690:           statusErrorBackend(preparacionRaw.error),
691:         );
692:       }
693:       const preparacion = parsePreparacionEliminacion(
694:         preparacionRaw.data,
695:         contratoId,
696:       );
697:       if (!preparacion) {
698:         return json(
699:           origin,
700:           origenes,
701:           {
702:             error: "El manifiesto de eliminación es incoherente",
703:             codigo: "INTEGRIDAD_ELIMINACION",
704:           },
705:           409,
706:         );
707:       }
708: 
709:       for (
710:         const bucket of [
711:           CONTRATO_PDF_BUCKET,
712:           CONTRATO_DOCUMENTOS_BUCKET,
713:         ] as const
714:       ) {
715:         const paths = preparacion.objetos
716:           .filter((objeto) => objeto.bucket === bucket)
717:           .map((objeto) => objeto.path);
718:         if (paths.length === 0) continue;
719:         const eliminacion = await deps.storage.eliminar(bucket, paths);
720:         if (eliminacion.error) {
721:           return json(
722:             origin,
723:             origenes,
724:             {
725:               error: "No se pudieron eliminar todos los archivos del contrato",
726:               codigo: "STORAGE_ELIMINACION",
727:             },
728:             503,
729:           );
730:         }
731:       }
732: 
733:       const finalRaw = await deps.rpcAdmin(
734:         "contrato_eliminacion_finalizar",
735:         {
736:           p_contrato_id: contratoId,
737:           p_token: preparacion.token,
738:           p_actor_id: sesion.id,
739:         },
740:       );
741:       if (finalRaw.error) {
742:         return json(
743:           origin,
744:           origenes,
745:           {
746:             error: mensajeErrorEliminacion(
747:               finalRaw.error,
748:               "Los archivos se retiraron, pero falta finalizar la eliminación",
749:             ),
750:             codigo: "CONTRATO_ELIMINACION_FINALIZAR",
751:           },
752:           statusErrorBackend(finalRaw.error),
753:         );
754:       }
755:       if (
756:         !esObjeto(finalRaw.data) ||
757:         !clavesExactas(finalRaw.data, [
758:           "contrato_id",
759:           "objetos_eliminados",
760:           "ok",
761:         ]) ||
762:         finalRaw.data.ok !== true ||
763:         finalRaw.data.contrato_id !== contratoId ||
764:         !Number.isInteger(finalRaw.data.objetos_eliminados) ||
765:         (finalRaw.data.objetos_eliminados as number) !==
766:           preparacion.objetos.length
767:       ) {
768:         return json(
769:           origin,
770:           origenes,
771:           {
772:             error: "La confirmación de eliminación es incoherente",
773:             codigo: "INTEGRIDAD_ELIMINACION",
774:           },
775:           409,
776:         );
777:       }
778:       return json(origin, origenes, {
779:         ok: true,
780:         contratoId,
781:         archivosEliminados: preparacion.objetos.length,
782:       });
783:     }
784: 
785:     const firmar = async (
786:       estado: EstadoPdf,
787:       yaVerificado = false,
788:     ): Promise<Response> => {
789:       const archivo = estado.archivo;
790:       if (estado.estado !== "sellado" || !archivo) {
791:         return json(
792:           origin,
793:           origenes,
794:           { error: "Metadata PDF incoherente", codigo: "INTEGRIDAD_METADATA" },
795:           409,
796:         );
797:       }
798:       if (!yaVerificado) {
799:         const descarga = await deps.storage.descargar(archivo.storage_path);
800:         if (descarga.error || !descarga.data) {
801:           return json(
802:             origin,
803:             origenes,
804:             {
805:               error: "PDF no disponible temporalmente",
806:               codigo: "STORAGE_DESCARGA",
807:             },
808:             503,
809:           );
810:         }
811:         const fp = await pdfValido(descarga.data)
812:           ? await fingerprint(descarga.data)
813:           : null;
814:         if (
815:           !fp || fp.sha256 !== archivo.sha256 ||
816:           fp.bytes !== archivo.bytes
817:         ) {
818:           return json(
819:             origin,
820:             origenes,
821:             {
822:               error: "Integridad del PDF bloqueada",
823:               codigo: "INTEGRIDAD_OBJETO",
824:             },
825:             409,
826:           );
827:         }
828:       }
829:       const firma = await deps.storage.firmar(archivo.storage_path, 300, req);
830:       if (firma.error || !firma.url) {
831:         return json(
832:           origin,
833:           origenes,
834:           { error: "No se pudo firmar la descarga", codigo: "STORAGE_FIRMA" },
835:           503,
836:         );
837:       }
838:       return json(origin, origenes, {
839:         pdf: pdfPublico(estado),
840:         url: firma.url,
841:       });
842:     };
843: 
844:     if (cuerpo.action === "status") {
