11: export function errorBackend(error: unknown): BackendError | null {
12:   if (!error || typeof error !== "object") return null;
13:   const valor = error as {
14:     code?: unknown;
15:     message?: unknown;
16:     statusCode?: unknown;
17:     status?: unknown;
18:   };
