20:   // envía statusCode numérico. Conservarlo permite distinguir NoSuchKey de red.
21:   const code = typeof valor.code === "string"
22:     ? valor.code
23:     : typeof valor.statusCode === "string" && !/^\d{3}$/.test(valor.statusCode)
24:     ? valor.statusCode
25:     : undefined;
26:   const statusRaw = typeof valor.statusCode === "number" ||
27:       (typeof valor.statusCode === "string" && /^\d{3}$/.test(valor.statusCode))
28:     ? valor.statusCode
29:     : valor.status;
30:   const statusCode = typeof statusRaw === "number"
31:     ? statusRaw
