50: // El límite incluye la lectura del cuerpo que hace el SDK, no solo recibir
51: // cabeceras. Cada operación posee su señal: cancelar una no afecta otra petición.
52: export function crearStorageContratoPdfV2(
53:   opciones: OpcionesStorage,
54: ): StorageContratoPdfV2 {
55:   const plazo = opciones.plazoMs ?? STORAGE_PLAZO_MS;
56:   if (!Number.isInteger(plazo) || plazo < 1 || plazo > 30_000) {
57:     throw new RangeError("Plazo Storage inválido");
58:   }
59:   const fetchImpl = opciones.fetchImpl ?? fetch;
60:   type ClienteStorage = ReturnType<typeof createClient>["storage"];
61:   const conLimite = async <T>(
62:     ejecutar: (storage: ClienteStorage) => Promise<T>,
63:   ): Promise<T> => {
64:     const control = new AbortController();
65:     let temporizador: ReturnType<typeof setTimeout> | undefined;
66:     const vencimiento = new Promise<never>((_resolver, rechazar) => {
67:       temporizador = setTimeout(() => {
68:         const error = Object.assign(
69:           new Error("Almacenamiento no disponible a tiempo"),
70:           {
71:             code: "STORAGE_TIMEOUT",
72:             statusCode: 504,
73:           },
74:         );
75:         rechazar(error);
76:         control.abort(error);
77:       }, plazo);
78:     });
79:     try {
80:       const cliente = createClient(opciones.supabaseUrl, opciones.secretKey, {
81:         auth: {
82:           autoRefreshToken: false,
83:           persistSession: false,
84:           detectSessionInUrl: false,
85:         },
86:         global: {
87:           fetch(input, init) {
88:             const previa = init?.signal ??
89:               (input instanceof Request ? input.signal : null);
90:             const signal = previa
91:               ? AbortSignal.any([previa, control.signal])
92:               : control.signal;
93:             return fetchImpl(input, { ...init, signal });
94:           },
95:         },
96:       });
97:       return await Promise.race([ejecutar(cliente.storage), vencimiento]);
98:     } finally {
99:       clearTimeout(temporizador);
100:       control.abort();
101:     }
102:   };
