111:             contentType: "application/pdf",
112:             upsert: false,
113:             cacheControl: "0",
114:           })
115:         );
116:         return { error: errorBackend(error) };
117:       } catch (error) {
118:         return { error: fallo(error) };
119:       }
120:     },
121:     async descargar(path) {
122:       try {
123:         const { data, error } = await conLimite((s) =>
124:           s.from(CONTRATO_PDF_BUCKET).download(path)
