141:           path,
142:         );
143:         return {
144:           url,
145:           error: errorBackend(error) ??
146:             (url ? null : { code: "SIGNED_URL_INVALID" }),
147:         };
148:       } catch (error) {
149:         return { url: null, error: fallo(error) };
150:       }
