1: CREATE OR REPLACE FUNCTION private.f4_comprobante_visible(p_ruta text)
2:  RETURNS boolean
3:  LANGUAGE sql
4:  STABLE SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7:   select coalesce(private.rol_crm((select auth.uid())) in ('vendedor','supervisor','gerencia') and exists (
8:     select 1 from crm.inversion_solicitudes s join crm.inversionistas i on i.id=private.inversionista_canonica(s.inversionista_id)
9:     where s.datos#>>'{evidencia,ruta}'=p_ruta and (
10:       private.rol_crm((select auth.uid()))='gerencia'
11:       or i.responsable_relacion_id in (select private.vendedor_ids_visibles((select auth.uid())))
12:     )
13:   ),false);
14: $function$

CATALOG SOURCE: crm.reasignar_responsable_relacion_fn(uuid, uuid, text)
1: CREATE OR REPLACE FUNCTION crm.reasignar_responsable_relacion_fn(p_inversionista uuid, p_nuevo_responsable uuid, p_motivo text)
2:  RETURNS jsonb
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6:  SET lock_timeout TO '5s'
7: AS $function$
8: declare
9:   v_uid uuid;
10:   v_inv crm.inversionistas%rowtype; v_tramo crm.inversionista_responsables%rowtype; v_nuevo_id uuid; v_ahora timestamptz; v_lead crm.leads%rowtype;
11:   v_rol_nuevo text; v_leads uuid[] := array[]::uuid[]; v_leads_movidos integer := 0; v_perfil_movido boolean := false; v_tenencia text := 'sin_cambios';  -- F2.b [D-2]
12: begin
13:   if not private.resolver_en_puertas_bajo_candado() then
14:     raise exception 'Identidad unificada apagada' using errcode = 'P0409';
15:   end if;
16:   if not private.es_gerencia_crm_activa() then
17:     raise exception 'Solo Gerencia reasigna el responsable de relación' using errcode = '42501';
18:   end if;
19:   v_uid := (select auth.uid());
20:   if p_inversionista is null or p_nuevo_responsable is null then
21:     raise exception 'Faltan la persona o el nuevo responsable' using errcode = '22023';
22:   end if;
23:   perform private.motivo_sin_documento(p_motivo, (select pg_catalog.array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id = p_inversionista));
24:   -- jerarquía compartida (el offboarding la toma exclusiva) + Gerencia y destinatario revalidados bajo ella -> identidad FOR UPDATE
25:   perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('crm.equipo.usuarios_jerarquia', 0));
26:   if not private.es_gerencia_crm_activa() then
27:     raise exception 'Solo Gerencia reasigna el responsable de relación (membresía revalidada)' using errcode = '42501';
28:   end if;
29:   if not coalesce(private.rol_crm(p_nuevo_responsable) in ('vendedor', 'supervisor', 'gerencia'), false) then
30:     raise exception 'El nuevo responsable debe ser un miembro activo del equipo comercial (rol efectivo)' using errcode = '22023';
31:   end if;
32:   select * into v_inv from crm.inversionistas where id = p_inversionista for update;
33:   if not found then
34:     raise exception 'La persona no existe' using errcode = 'P0002';
35:   end if;
36:   if v_inv.estado = 'fusionado' then
37:     raise exception 'Esta identidad está fusionada: reasigna en su canónica %', private.inversionista_canonica(v_inv.id) using errcode = 'P0409';
38:   elsif v_inv.estado <> 'activo' then
39:     raise exception 'La persona no está activa (%): revisión de Gerencia', v_inv.estado using errcode = 'P0409';
40:   end if;
41:   -- F2.b [D-2] (Codex #12): el motivo se revalida contra los documentos BAJO el lock de la persona (la validación de
42:   -- arriba corre antes del lock y una corrección documental concurrente pudo cambiarlos).
43:   perform private.motivo_sin_documento(p_motivo, (select pg_catalog.array_agg(d.documento_normalizado) from crm.inversionista_identificadores d where d.inversionista_id = p_inversionista));
44:   select * into v_tramo from crm.inversionista_responsables where inversionista_id = p_inversionista and hasta is null for update;
45:   if v_tramo.id is not null and v_tramo.responsable_id = p_nuevo_responsable then
46:     return pg_catalog.jsonb_build_object('ok', true, 'estado', 'sin_cambios', 'inversionista_id', p_inversionista, 'tramo_id', v_tramo.id);
47:   end if;
48:   -- F2.b [D-2]: capacidad operativa del nuevo responsable. Si puede tener cartera (vendedor/supervisor activo, rol
49:   -- efectivo), los leads VIVOS en tenencia operativa de la persona (enlace ∪ puente ∪ sueltos con su documento, D-13)
50:   -- pasan a su cartera y el perfil cliente de la persona también. Orden: persona (ya) → tramo (ya) → tareas
51:   -- pendientes → leads → perfil, como el veto (b2) y la fusión (b5). Con Gerencia como nuevo responsable no hay
52:   -- cartera que mover: solo el tramo (tenencia = 'sin_cambios').
53:   v_rol_nuevo := private.rol_crm(p_nuevo_responsable);
54:   if v_rol_nuevo in ('vendedor', 'supervisor') then
55:     select coalesce(pg_catalog.array_agg(s.id), array[]::uuid[]) into v_leads
56:     from (select l.id from crm.leads l
57:            where l.id in (select x from private.leads_de_personas(array[p_inversionista]) x)
58:              and l.activo = true
59:              and l.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
60:              and (l.vendedor_id is distinct from p_nuevo_responsable or l.asignado_supervisor_id is not null)
61:            order by l.id) s;
62:     -- (Codex N1/N4) tampoco se espera por una TAREA ni por el PERFIL: cerrar_tarea tiene la tarea y va tarea → lead/perfil;
63:     -- el Portal actualiza el perfil y su trigger va perfil → tareas. Con la persona y el tramo en la mano, todo lo demás
64:     -- se toma SIN esperar → 40001 y Gerencia reintenta.
65:     begin
66:       perform 1 from crm.tareas t
67:        where t.estado = 'pendiente'
68:          and (t.lead_id = any(v_leads) or (v_inv.perfil_id is not null and t.perfil_id = v_inv.perfil_id))
69:        order by t.id
70:        for update nowait;
71:       if v_inv.perfil_id is not null then
72:         perform 1 from public.perfiles p where p.id = v_inv.perfil_id for no key update nowait;
73:       end if;
74:     exception when lock_not_available then
75:       raise exception 'Otra sesión está trabajando una tarea o la ficha de la persona; vuelve a intentarlo'
76:         using errcode = '40001';
77:     end;
78:     -- (Codex #1) tareas → leads es el orden de b2/D-3 y de cerrar_tarea; derivar y repartir van lead → tareas (por el
79:     -- trigger de sincronización) bajo el mismo interlock compartido. Como la fusión (b5, E3-9): los leads se toman
80:     -- SIN esperar; si otra sesión tiene uno → 40001 y Gerencia reintenta.
81:     begin
82:       perform 1 from crm.leads l where l.id = any(v_leads) order by l.id for update nowait;
83:     exception when lock_not_available then
84:       raise exception 'Otra sesión está trabajando uno de los leads de la persona; vuelve a intentarlo'
85:         using errcode = '40001';
86:     end;
87:     v_tenencia := 'movida';
88:   end if;
89:   v_ahora := pg_catalog.clock_timestamp();
90:   perform pg_catalog.set_config('crm.op_privilegiada', 'on', true);
91:   if v_tramo.id is not null then
92:     update crm.inversionista_responsables set hasta = v_ahora where id = v_tramo.id;
93:   end if;
94:   insert into crm.inversionista_responsables (inversionista_id, responsable_id, desde, motivo, por)
95:   values (p_inversionista, p_nuevo_responsable, v_ahora, p_motivo, v_uid) returning id into v_nuevo_id;
96:   update crm.inversionistas set responsable_relacion_id = p_nuevo_responsable where id = p_inversionista;
97:   -- F2.b [D-2]: la cartera sigue al responsable (los triggers de leads llevan el ledger de asignaciones, la actividad
98:   -- «reasignacion», tenencia_desde y las tareas pendientes; el del perfil mueve las tareas de cliente y deja su actividad).
99:   if v_tenencia = 'movida' then
100:     if coalesce(pg_catalog.array_length(v_leads, 1), 0) > 0 then
101:       -- (auditor M2) se REVALIDA bajo los locks: sigue vivo, en etapa abierta y sigue siendo de la persona (un descarte o una
102:       -- conversión concurrentes solo bloquean el lead; la puerta del DNI de D-13 puede llevarse un suelto a otra persona).
103:       update crm.leads l
104:          set vendedor_id = p_nuevo_responsable,
105:              asignado_supervisor_id = null
106:        where l.id = any(v_leads)
107:          and l.activo = true
108:          and l.etapa in ('nuevo', 'contactado', 'reunion_agendada', 'propuesta_enviada')
109:          and l.id in (select x from private.leads_de_personas(array[p_inversionista]) x);
110:       get diagnostics v_leads_movidos = row_count;
111:     end if;
112:     if v_inv.perfil_id is not null then
113:       update public.perfiles p
114:          set asesor_perfil_id = p_nuevo_responsable,
115:              actualizado_en = pg_catalog.clock_timestamp()
116:        where p.id = v_inv.perfil_id and p.rol = 'cliente' and p.activo is true
117:          and p.asesor_perfil_id is distinct from p_nuevo_responsable;
118:       v_perfil_movido := found;
119:     end if;
120:     -- (auditor N5) «movida» solo si algo se movió de verdad.
121:     if v_leads_movidos = 0 and not v_perfil_movido then
122:       v_tenencia := 'sin_cambios';
123:     end if;
124:   end if;
125:   select * into v_lead from crm.leads where inversionista_id = p_inversionista and activo = true order by id limit 1;
126:   if v_lead.id is not null then
127:     insert into crm.actividades (lead_id, tipo, detalle, metadata, creado_por)
128:     values (v_lead.id, 'nota', 'Responsable de relación reasignado (Gerencia)',
129:             pg_catalog.jsonb_build_object('evento', 'reasignacion_responsable', 'inversionista_id', p_inversionista,
130:                                           'anterior', v_tramo.responsable_id, 'nuevo', p_nuevo_responsable, 'tramo_id', v_nuevo_id),
131:             v_uid);
132:   end if;
133:   perform pg_catalog.set_config('crm.op_privilegiada', 'off', true);
134:   return pg_catalog.jsonb_build_object('ok', true, 'estado', 'reasignado', 'inversionista_id', p_inversionista,
135:     'tramo_anterior_id', v_tramo.id, 'tramo_nuevo_id', v_nuevo_id, 'responsable_anterior', v_tramo.responsable_id, 'responsable_nuevo', p_nuevo_responsable,
136:     'tenencia', pg_catalog.jsonb_build_object('estado', v_tenencia, 'leads_movidos', v_leads_movidos, 'perfil_movido', v_perfil_movido));  -- F2.b [D-2]
137: end;
138: $function$

CATALOG SOURCE: private.contrato_pdf_snapshot_v2_base(uuid)
1: CREATE OR REPLACE FUNCTION private.contrato_pdf_snapshot_v2_base(p_contrato_id uuid)
2:  RETURNS jsonb
3:  LANGUAGE plpgsql
4:  STABLE SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare
8:   v_contrato public.contratos%rowtype;
9:   v_cliente public.perfiles%rowtype;
10:   v_analista public.perfiles%rowtype;
11:   v_cotitulares jsonb;
12:   v_cronograma jsonb;
13:   v_cuenta jsonb;
14: begin
15:   select * into strict v_contrato
16:   from public.contratos c
17:   where c.id = p_contrato_id;
18: 
19:   select * into strict v_cliente
20:   from public.perfiles p
21:   where p.id = v_contrato.cliente_id
22:     and p.rol = 'cliente';
23: 
24:   if v_contrato.creado_por is null then
25:     raise exception 'El contrato no identifica al analista que lo creó'
26:       using errcode = '23514';
27:   end if;
28: 
29:   select * into strict v_analista
30:   from public.perfiles p
31:   where p.id = v_contrato.creado_por;
32: 
33:   if nullif(btrim(v_contrato.numero_contrato), '') is null
34:      or nullif(btrim(v_cliente.nombre_completo), '') is null
35:      or nullif(btrim(v_cliente.tipo_documento), '') is null
36:      or nullif(btrim(v_cliente.dni), '') is null
37:      or nullif(btrim(v_cliente.domicilio), '') is null
38:      or nullif(btrim(v_cliente.correo), '') is null
39:      or nullif(btrim(v_analista.nombre_completo), '') is null
40:      or nullif(btrim(v_analista.dni), '') is null
41:      or nullif(btrim(v_analista.telefono), '') is null
42:      or nullif(btrim(v_analista.correo), '') is null then
43:     raise exception
44:       'Faltan datos legales obligatorios del titular o del analista'
45:       using errcode = '23514';
46:   end if;
47: 
48:   select coalesce(
49:     jsonb_agg(
50:       jsonb_build_object(
51:         'id', t.id,
52:         'orden', t.orden,
53:         'nombreCompleto', t.nombre_completo,
54:         'tipoDocumento', upper(t.tipo_documento),
55:         'documento', t.documento
56:       ) order by t.orden, t.id
57:     ),
58:     '[]'::jsonb
59:   ) into v_cotitulares
60:   from public.contrato_titulares t
61:   where t.contrato_id = p_contrato_id;
62: 
63:   select coalesce(
64:     jsonb_agg(
65:       jsonb_build_object(
66:         'id', cp.id,
67:         'numeroCuota', cp.numero_cuota,
68:         'fechaProgramada', cp.fecha_programada::text,
69:         'montoProgramado', cp.monto_programado,
70:         'tipo', cp.tipo
71:       ) order by cp.numero_cuota, cp.id
72:     ),
73:     '[]'::jsonb
74:   ) into v_cronograma
75:   from public.cronograma_pagos cp
76:   where cp.contrato_id = p_contrato_id;
77: 
78:   if jsonb_array_length(v_cronograma) = 0 then
79:     raise exception 'El contrato no tiene cronograma contractual'
80:       using errcode = '23514';
81:   end if;
82: 
83:   select jsonb_build_object(
84:     'cuentaId', cb.id,
85:     'moneda', cb.moneda,
86:     'banco', cb.banco,
87:     'tipoCuenta', cb.tipo_cuenta,
88:     'numeroCuenta', cb.numero_cuenta,
89:     'cci', cb.cci,
90:     'titularDistinto', cb.titular_distinto,
91:     'beneficiarioNombre', cb.beneficiario_nombre,
92:     'beneficiarioDocumento', cb.beneficiario_dni,
93:     'origen', cb.origen
94:   ) into v_cuenta
95:   from crm.contrato_cuentas_pago ccp
96:   join crm.cuentas_bancarias cb on cb.id = ccp.cuenta_bancaria_id
97:   where ccp.contrato_id = p_contrato_id;
98: 
99:   if v_cuenta is null then
100:     raise exception 'El contrato no tiene una cuenta de pago contractual'
101:       using errcode = '23514';
102:   end if;
103: 
104:   return jsonb_build_object(
105:     'snapshotVersion', 2,
106:     'contrato', jsonb_build_object(
107:       'id', v_contrato.id,
108:       'numero', v_contrato.numero_contrato,
109:       'clienteId', v_contrato.cliente_id,
110:       'capital', v_contrato.capital,
111:       'moneda', v_contrato.moneda,
112:       'porcentaje', v_contrato.tasa_anual,
113:       'modalidad', v_contrato.modalidad,
114:       'tipoInteres', v_contrato.tipo_interes,
115:       'categoria', v_contrato.categoria,
116:       'fechaInicio', v_contrato.fecha_inicio::text,
117:       'fechaVencimiento', v_contrato.fecha_vencimiento::text,
118:       'productoCondicionId', v_contrato.producto_condicion_id,
119:       'creadoPor', v_contrato.creado_por
120:     ),
121:     'titular', jsonb_build_object(
122:       'id', v_cliente.id,
123:       'nombreCompleto', v_cliente.nombre_completo,
124:       'tipoDocumento', upper(v_cliente.tipo_documento),
125:       'documento', v_cliente.dni,
126:       'domicilio', v_cliente.domicilio,
127:       'correo', v_cliente.correo
128:     ),
129:     'analista', jsonb_build_object(
130:       'id', v_analista.id,
131:       'nombreCompleto', v_analista.nombre_completo,
132:       'documento', v_analista.dni,
133:       'celular', v_analista.telefono,
134:       'correo', v_analista.correo
135:     ),
136:     'cotitulares', v_cotitulares,
137:     'cronograma', v_cronograma,
138:     'cuentaPago', v_cuenta
139:   );
140: exception when no_data_found then
141:   raise exception 'Contrato, titular o analista inexistente'
142:     using errcode = 'P0002';
143: end;
144: $function$

