CATALOG SOURCE: private.inversion_titular_coherente()
1: CREATE OR REPLACE FUNCTION private.inversion_titular_coherente()
2:  RETURNS trigger
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare v_principal uuid;
8: begin
9:   if new.rol = 'principal' then
10:     select i.inversionista_id into v_principal from crm.inversiones i where i.id = new.inversion_id;
11:     if new.inversionista_id is distinct from v_principal then
12:       raise exception 'inversion_titulares: el principal debe ser el inversionista de la inversion (% <> %)',
13:         new.inversionista_id, v_principal using errcode = '23514';
14:     end if;
15:   end if;
16:   return new;
17: end $function$

CATALOG SOURCE: private.inversionista_canonica(uuid)
1: CREATE OR REPLACE FUNCTION private.inversionista_canonica(p_id uuid)
2:  RETURNS uuid
3:  LANGUAGE sql
4:  STABLE SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7:   with recursive c as (
8:     select i.id, i.inversionista_canonico_id, 1 as n from crm.inversionistas i where i.id = p_id
9:     union all
10:     select i.id, i.inversionista_canonico_id, c.n + 1
11:     from c join crm.inversionistas i on i.id = c.inversionista_canonico_id
12:     where c.n < 16
13:   )
14:   select case when p_id is null then null
15:               else coalesce((select c.id from c where c.inversionista_canonico_id is null order by c.n desc limit 1), p_id) end
16: $function$

CATALOG SOURCE: private.log_audit_sin_secretos()
1: CREATE OR REPLACE FUNCTION private.log_audit_sin_secretos()
2:  RETURNS trigger
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare
8:   v_secretos text[];
9:   v_fila uuid;
10:   v_actor uuid;
11: begin
12:   if tg_nargs = 0 then
13:     raise exception 'log_audit_sin_secretos exige las columnas a enmascarar como argumentos del trigger (tabla %.%)',
14:       tg_table_schema, tg_table_name;
15:   end if;
16:   v_secretos := tg_argv::text[];
17: 
18:   -- Ruido fuera: el portal reescribe la suscripción entera en cada carga del
19:   -- panel; si lo único que cambia es el reloj, no hay nada que auditar.
20:   if tg_op = 'UPDATE'
21:      and (pg_catalog.to_jsonb(old) - 'actualizado_en')
22:        = (pg_catalog.to_jsonb(new) - 'actualizado_en') then
23:     return new;
24:   end if;
25: 
26:   begin
27:     v_fila := coalesce(
28:       (pg_catalog.to_jsonb(coalesce(new, old)) ->> 'id')::uuid,
29:       (pg_catalog.to_jsonb(coalesce(new, old)) ->> 'perfil_id')::uuid
30:     );
31:   exception when invalid_text_representation then
32:     v_fila := null;
33:   end;
34: 
35:   select p.id into v_actor
36:   from public.perfiles p where p.id = (select auth.uid());
37: 
38:   insert into public.audit_log (tabla, operacion, fila_id, usuario_id, data_antes, data_despues)
39:   values (
40:     tg_table_schema || '.' || tg_table_name,
41:     tg_op,
42:     v_fila,
43:     v_actor,
44:     case when tg_op in ('UPDATE','DELETE')
45:       then private.enmascarar_claves(pg_catalog.to_jsonb(old), v_secretos) end,
46:     case when tg_op in ('INSERT','UPDATE')
47:       then private.enmascarar_claves(pg_catalog.to_jsonb(new), v_secretos) end
48:   );
49: 
50:   return coalesce(new, old);
51: end;
52: $function$

