CATALOG SOURCE: private.resolver_en_puertas_bajo_candado()
1: CREATE OR REPLACE FUNCTION private.resolver_en_puertas_bajo_candado()
2:  RETURNS boolean
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare
8:   v_aisl text := pg_catalog.current_setting('transaction_isolation');
9: begin
10:   -- F2.b [D-19]. Un solo sitio para el invariante «leer la bandera implica tener su candado».
11:   -- 1) READ COMMITTED obligatorio: bajo REPEATABLE READ o SERIALIZABLE la transacción vería una foto anterior al
12:   --    encendido aunque el candado la hubiese hecho esperar, que es justo el error que esto viene a impedir.
13:   if v_aisl <> 'read committed' then
14:     raise exception 'La identidad unificada requiere READ COMMITTED (aislamiento actual: %)', v_aisl
15:       using errcode = '0A000';
16:   end if;
17:   -- 2) El COMPARTIDO del encendido. Es de transacción: una vez tomado, el valor no puede cambiar hasta el commit, y
18:   --    el UPDATE de la bandera (que toma el EXCLUSIVO por el trigger de D-5) espera a que esta llamada termine.
19:   --    Reentrante: tomarlo dos veces en la misma transacción no cuesta nada.
20:   perform pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtext('crm_flag_resolver_en_puertas'));
21:   -- 3) Y ahora sí, el valor.
22:   return coalesce((select f.activo from crm.multiempresa_flags f where f.nombre = 'resolver_en_puertas'), false);
23: end;
24: $function$

CATALOG SOURCE: private.rol_crm(uuid)
1: CREATE OR REPLACE FUNCTION private.rol_crm(p_perfil_id uuid)
2:  RETURNS text
3:  LANGUAGE sql
4:  STABLE SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7:   select e.rol_crm
8:   from crm.equipo e
9:   join public.perfiles p on p.id = e.perfil_id
10:   where e.perfil_id = p_perfil_id
11:     and e.activo is true and p.activo is true
12:     and e.rol_crm in (
13:       'vendedor','supervisor','gerencia','coordinador','directorio'
14:     )
15:     -- Directorio es una capacidad de lectura, no un alias operativo de
16:     -- Gerencia. Una pareja desalineada no recibe ningún rol efectivo.
17:     and (
18:       (p.rol = 'directorio' and e.rol_crm = 'directorio')
19:       or (p.rol is distinct from 'directorio' and e.rol_crm <> 'directorio')
20:     )
21:     -- Superadmin Portal gobierna roles CRM; solo una membresía de Gerencia le
22:     -- suma autoridad operativa. Cualquier otro rol queda fuera del gate global.
23:     and (p.rol is distinct from 'superadmin' or e.rol_crm = 'gerencia');
24: $function$

CATALOG SOURCE: private.saga_auth_avanzar(uuid, text, text, uuid, uuid, integer)
1: CREATE OR REPLACE FUNCTION private.saga_auth_avanzar(p_claim_id uuid, p_token text, p_estado text, p_auth_user_id uuid, p_perfil_id uuid, p_version integer)
2:  RETURNS jsonb
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare
8:   v_loc record;
9:   v_row crm.multiempresa_idempotencia%rowtype;
10:   v_est jsonb;
11:   v_prev text;
12: begin
13:   select * into v_loc from private.saga_auth_localizar(p_claim_id);
14:   if not found then
15:     raise exception 'Saga: claim inexistente' using errcode = 'P0002';
16:   end if;
17:   select * into v_row from crm.multiempresa_idempotencia where clave = v_loc.clave for update;
18:   v_est := v_row.resultado;
19:   if v_est->>'token_hash' is distinct from private.saga_token_hash(p_token) then
20:     raise exception 'Saga: token inválido' using errcode = '42501';
21:   end if;
22:   if p_version is null then
23:     raise exception 'Saga: falta la versión del claim (CAS)' using errcode = '22023';
24:   end if;
25:   if v_row.version is distinct from p_version then
26:     raise exception 'Saga: el claim cambió (versión % ≠ %); vuelve a reclamar', v_row.version, p_version
27:       using errcode = '40001';
28:   end if;
29:   v_prev := v_est->>'estado';
30:   if not ((v_prev = 'reclamado' and p_estado = 'auth_creado' and p_auth_user_id is not null)
31:        or (v_prev = 'auth_creado' and p_estado = 'perfil_creado' and p_perfil_id is not null and p_perfil_id = (v_est->>'auth_user_id')::uuid)
32:        or (v_prev in ('auth_creado','perfil_creado') and p_estado = 'enlazado')
33:        or (v_prev = 'auth_creado' and p_estado = 'reclamado')   -- compensación: el Auth se borró tras fallar el perfil
34:        or (v_prev = p_estado                                      -- repetición idempotente: NUNCA reescribe auth/perfil (auditor b3 A1)
35:            and coalesce(p_auth_user_id, (v_est->>'auth_user_id')::uuid) is not distinct from (v_est->>'auth_user_id')::uuid
36:            and coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid) is not distinct from (v_est->>'perfil_id')::uuid)) then
37:     raise exception 'Saga: transición inválida % -> %', v_prev, p_estado using errcode = 'P0409';
38:   end if;
39:   -- Procedencia verificada EN SERVIDOR (Codex E2 #2): el Auth declarado debe existir y llevar la
40:   -- marca de ESTE claim en app_metadata; el perfil debe existir con id = auth_user_id.
41:   if p_estado = 'auth_creado' and v_prev = 'reclamado' then
42:     if not exists (select 1 from auth.users u where u.id = p_auth_user_id
43:                     and u.raw_app_meta_data->>'claim_id' = p_claim_id::text) then
44:       raise exception 'Saga: el usuario de Auth no existe o no lleva la marca de este claim' using errcode = 'P0409';
45:     end if;
46:   end if;
47:   if p_estado = 'perfil_creado' then
48:     if not exists (select 1 from public.perfiles p where p.id = p_perfil_id and p.rol = 'cliente') then
49:       raise exception 'Saga: el perfil declarado no existe' using errcode = 'P0409';
50:     end if;
51:   end if;
52:   if p_estado = 'enlazado' and (v_est->>'auth_user_id') is not null
53:      and coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid) is distinct from (v_est->>'auth_user_id')::uuid then
54:     raise exception 'Saga: el perfil enlazado debe ser el usuario de Auth de este claim' using errcode = 'P0409';
55:   end if;
56:   if p_estado = 'reclamado' then
57:     if exists (select 1 from auth.users u where u.id = (v_est->>'auth_user_id')::uuid) then
58:       raise exception 'Saga: no se puede compensar: el usuario de Auth sigue existiendo' using errcode = 'P0409';
59:     end if;
60:     v_est := v_est - 'auth_user_id' || pg_catalog.jsonb_build_object('auth_user_id', null);
61:     p_auth_user_id := null;
62:   end if;
63:   v_est := v_est || pg_catalog.jsonb_build_object('estado', p_estado,
64:     'auth_user_id', case when p_estado = 'reclamado' then null else coalesce(p_auth_user_id, (v_est->>'auth_user_id')::uuid) end,
65:     'perfil_id', coalesce(p_perfil_id, (v_est->>'perfil_id')::uuid),
66:     'lease_hasta', pg_catalog.now() + interval '10 minutes', 'actualizado_en', pg_catalog.now());
67:   update crm.multiempresa_idempotencia set resultado = v_est, version = version + 1 where clave = v_loc.clave;
68:   return pg_catalog.jsonb_build_object('claim_id', p_claim_id, 'estado', p_estado, 'version', v_row.version + 1,
69:     'inversionista_id', v_loc.inversionista_id, 'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
70: end;
71: $function$

CATALOG SOURCE: private.saga_auth_reclamar(uuid, text, jsonb, uuid, text)
1: CREATE OR REPLACE FUNCTION private.saga_auth_reclamar(p_inv uuid, p_tipo text, p_payload jsonb, p_lead_id uuid DEFAULT NULL::uuid, p_token text DEFAULT NULL::text)
2:  RETURNS jsonb
3:  LANGUAGE plpgsql
4:  SECURITY DEFINER
5:  SET search_path TO ''
6: AS $function$
7: declare
8:   v_uid   uuid := (select auth.uid());
9:   v_clave text := 'auth_persona:' || p_inv::text;
10:   v_hash  text := private.idem_hash(coalesce(p_payload, '{}'::jsonb));
11:   v_token text := pg_catalog.encode(extensions.gen_random_bytes(24), 'hex');
12:   v_row   crm.multiempresa_idempotencia%rowtype;
13:   v_est   jsonb;
14:   v_claim uuid;
15: begin
16:   if p_inv is null or p_tipo not in ('alta_cliente','conversion') then
17:     raise exception 'Saga: identidad o tipo inválidos' using errcode = '22023';
18:   end if;
19:   select * into v_row from crm.multiempresa_idempotencia where clave = v_clave for update;
20:   if not found then
21:     v_claim := gen_random_uuid();
22:     v_est := pg_catalog.jsonb_build_object(
23:       'claim_id', v_claim, 'token_hash', private.saga_token_hash(v_token), 'tipo', p_tipo,
24:       'owner', v_uid, 'estado', 'reclamado', 'auth_user_id', null, 'perfil_id', null,
25:       'lead_id', p_lead_id, 'lease_hasta', pg_catalog.now() + interval '10 minutes',
26:       'creado_en', pg_catalog.now(), 'actualizado_en', pg_catalog.now());
27:     insert into crm.multiempresa_idempotencia (clave, tipo, hash_payload, resultado, creado_por)
28:     values (v_clave, p_tipo, v_hash, v_est, v_uid);
29:     return pg_catalog.jsonb_build_object('claim_id', v_claim, 'token', v_token, 'estado', 'reclamado',
30:       'version', 1, 'reanudar', false, 'inversionista_id', p_inv, 'auth_user_id', null, 'perfil_id', null);
31:   end if;
32:   v_est := v_row.resultado;
33:   if v_est->>'estado' = 'enlazado' then
34:     return pg_catalog.jsonb_build_object('claim_id', (v_est->>'claim_id')::uuid, 'token', null, 'estado', 'enlazado',
35:       'version', v_row.version, 'reanudar', true, 'inversionista_id', p_inv,
36:       'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
37:   end if;
38:   -- Reanudar SOLO con el token vigente (misma ejecución) o con el lease vencido. Compartir
39:   -- actor no basta: una segunda petición del mismo usuario no puede expulsar a la primera
40:   -- (Codex E2 #1). service_role (owner null) tampoco identifica un proceso.
41:   if (v_est->>'lease_hasta')::timestamptz > pg_catalog.now()
42:      and (p_token is null or v_est->>'token_hash' is distinct from private.saga_token_hash(p_token)) then
43:     raise exception 'Esta persona tiene un alta en curso; espera unos minutos'
44:       using errcode = 'P0409';
45:   end if;
46:   -- En 'reclamado' aún no existe nada externo: un payload distinto (correo corregido, etc.)
47:   -- REEMPLAZA la huella en vez de varar a la persona (auditor b3 A2). Desde 'auth_creado' el
48:   -- Auth y el perfil ya llevan los datos: un payload distinto es otra intención → P0409.
49:   if v_est->>'estado' <> 'reclamado' and v_row.hash_payload <> v_hash then
50:     raise exception 'La misma persona llegó con datos distintos; no se puede reintentar así'
51:       using errcode = 'P0409';
52:   end if;
53:   v_est := v_est || pg_catalog.jsonb_build_object('token_hash', private.saga_token_hash(v_token), 'owner', v_uid,
54:     'tipo', p_tipo, 'lead_id', coalesce(p_lead_id, (v_est->>'lead_id')::uuid),
55:     'lease_hasta', pg_catalog.now() + interval '10 minutes', 'actualizado_en', pg_catalog.now());
56:   update crm.multiempresa_idempotencia
57:      set resultado = v_est, version = version + 1,
58:          hash_payload = case when v_est->>'estado' = 'reclamado' then v_hash else hash_payload end,
59:          tipo = p_tipo
60:    where clave = v_clave;
61:   return pg_catalog.jsonb_build_object('claim_id', (v_est->>'claim_id')::uuid, 'token', v_token, 'estado', v_est->>'estado',
62:     'version', v_row.version + 1, 'reanudar', true, 'inversionista_id', p_inv,
63:     'auth_user_id', (v_est->>'auth_user_id')::uuid, 'perfil_id', (v_est->>'perfil_id')::uuid);
64: end;
